	\appendix
	\section{Technical tools}
	The following results are standard, and proofs in the Euclidean space ({\em e.g.}~\cite[Theorem 8.3.1]{Hormander97} for product estimates) straightforwardly adapt to the periodic setting.

	\begin{Proposition}[Continuous embedding]\label{prop.embedding}
		Let $s\in\RR$ , $s>d/2$ and \(f\in H^{s}((2\pi\TT)^d)\). Then \(f\in L^\infty((2\pi\TT)^d)\) and 
		\[\big|f \big|_{L^\infty} \leq C(s) \big|f \big|_{H^{s}}.\]
	\end{Proposition}


	\begin{Proposition}[Interpolation inequality]\label{prop.interpolation_inequality}
		Let $s_1,s_2\in\RR$ and \(f\in H^{s_1}((2\pi\TT)^d)\cap H^{s_2}((2\pi\TT)^d)\). Then for any \(0\leq\theta\leq 1\), \(f\in H^{\theta s_1+(1-\theta)s_2}((2\pi\TT)^d)\) and 
		\[\big|f \big|_{H^{\theta s_1+(1-\theta)s_2}} \leq  \big|f \big|_{H^{s_1}}^\theta \big|f \big|_{H^{s_2}}^{1-\theta}.\]
	\end{Proposition}


	\begin{Proposition}[Product estimates]\label{prop.product_estimates}
		Let \(s_0 >d/2, s\geq -s_0\) and \(f\in H^{s}((2\pi\TT)^{d})\bigcap H^{s_0}((2\pi\TT)^{d}), g\in H^{s}((2\pi\TT)^{d})\). Then \(fg \in H^{s}((2\pi\TT)^{d})\) and 
		\[\big|fg \big|_{H^{s}} \leq C(s_0,s) \Big(\big|f \big|_{H^{s_0}}\big|g \big|_{H^{s}}+\big|f \big|_{H^{s}}\big|g \big|_{H^{s_0}}\Big).\]
		If moreover $s\leq s_0$ then
		\[\big|fg \big|_{H^{s}} \leq C(s_0,s) \big|f \big|_{H^{s_0}}\big|g \big|_{H^{s}}.\]
	\end{Proposition}
	Assuming polynomial nonlinearities, the following proposition is a straightforward consequence of product estimates. Extending this result to general (smooth) functions $P$ requires an analysis that is outside of the scope of the present paper.
	\begin{Proposition}[Composition estimates]\label{prop.composition_estimates} 
		Let \(s_0 >d/2, s\geq -s_0\), \(f,g\in H^{s}((2\pi\TT)^{d})\bigcap H^{s_0}((2\pi\TT)^{d})\) and {$P\in\RR[X]$ a polynomial}. Then \(P(f),P(g) \in H^{s}((2\pi\TT)^{d})\) and 
		\begin{align*}\big|P(f) -P(g)\big|_{H^{s}} &\leq C(P,s_0,s,\big|f \big|_{H^{\max(s_0, s)}},\big|g \big|_{H^{\max(s_0, s)}}) \big|f -g\big|_{H^{s}},\\
		\big|P(f) -P(0)\big|_{H^{s}} &\leq C(P,s_0,s,\big|f \big|_{H^{s_0}}) \big|f \big|_{H^{s}}.
	\end{align*}
	\end{Proposition}



	\begin{Proposition}[Commutator estimates with symbols of order s]\label{prop.commutator_s}
		Let \(s_0>d/2, s\geq 0\) and \(\Lambda^s  = (\Id - \Delta)^{s/2}\). Let \(f\in H^{s}((2\pi\TT)^{d})\bigcap H^{s_0+1}((2\pi\TT)^{d}), g\in H^{s-1}((2\pi\TT)^{d})\bigcap H^{s_0}((2\pi\TT)^{d})\). Then 
		\[\big|[\Lambda^s ,f]g \big|_{L^2} \leq C(s_0, s)(\big|f \big|_{H^s}\big|g \big|_{H^{s_0}} + \big|f \big|_{H^{s_0 +1}}\big|g \big|_{H^{s-1}}).\]
	\end{Proposition}


	The following result is shown on \(\RR^d\) in~\cite[Lemma 4.5]{DucheneMelinand24}. It is straightforward to adapt the proof to the periodic setting.
	\begin{Proposition}[Commutator estimates with operators of order zero]\label{prop.commutator_0}
		Let \(s_0 > d/2, s\geq0\) and $G(D)$ be a Fourier multiplier with symbol \(G\) satisfying \(\big|G \big|_{L^{\infty}}, \big|\left|\,\cdot\, \right| \nabla G \big|_{L^{\infty}} \leq C_G\). Let \(f\in H^{s_0+1}((2\pi\TT)^d)\bigcap H^{s}((2\pi\TT)^d)\), \(g \in H^{s-1}((2\pi\TT)^d)\). Then
	   \[\big|[G(D), f] g\big|_{H^s} \leq C(s_0, s)\, C_G\, \big|f \big|_{H^{\max(s_0+1,s)}}\big|g \big|_{H^{s-1}}.\]
   \end{Proposition}
   \begin{Remark}
   	Notice that if \(G\) is such that \(\big|G \big|_{L^{\infty}}, \big|\left|\,\cdot\, \right| \nabla G \big|_{L^{\infty}} \leq C_G\), then $G_N\coloneq G(\cdot/N)$ satisfies  \[\big|G_N \big|_{L^{\infty}}, \big|\left|\,\cdot\, \right| \nabla G_N \big|_{L^{\infty}} \leq C_G\] uniformly with respect to $N$.
   \end{Remark}

