\section{Relating Crossing, Edge, Cell, Trail, and Configuration Counts}\label{sec:constraints}

In this section, we present a number of (in)equalities, each relating the number of certain cells, configurations, edges, or crossings. Due to space constraints we discuss only two of these inequalities, the rest can be found in \cref{app:constraints}. 
Our proof relies on the Density Formula for~$t=5$.
For this value of~$t$, $\Clarge$-cells contribute negatively in the formula. 
Intuitively, large cells account for many crossings: 
If many trails end in large cells, we obtain a lower bound on the sum~$\sum_{a \geq 6}a \abs{\calC_a}$ of sizes of large cells.
This yields a lower bound on the sum~$\sum_{c \in \calC_{\geq 6}}(\norm{c}-5)$ in the Density Formula, 
where $\calC_{\geq 6}$ denotes the set of large cells.
If there are few such trails, we obtain configurations that contain many crossed edges.

\begin{lemma}%5.A
    If $\Gamma$ is a $3$-saturated drawing, then
    \begin{align}
    \tag{5.A}
    \label{eq:5A}
    \sum_{a \geq 6}a \abs{\calC_a} \geq \cor{\CIVvI}{\Clarge} + \cor{\CVvI}{\Clarge} + \cor{\CIIIvO}{\Clarge} + \cor{\CVvO}{\Clarge} + 5\mul\CVIvII.
    \end{align}
\end{lemma}
\begin{proof}
    As we want to obtain a lower bound on the sum $\sum_{a \geq 6}a \abs{\calC_a}$, it suffices to count the number of vertex and edge-segment incidences of large cells. 
    Each trail that ends in a large cell enters this cell via an inner edge-segment.
    As no two trails share such an inner edge-segment, we obtain one edge-segment incidence for each such trail.

    A \CVIvII-cell is in particular large. 
    As it is incident to only one inner-segment, it is the endpoint of only one trail.
    We have not counted the remaining three edge-segment incidences and the two vertex incidences when considering trails.
    Therefore, each \CVIvII-cell yields at least five more edge-segment and vertex incidences.
\end{proof}

\begin{lemma}%3.C
    If~$\Gamma$ is a $3$-saturated drawing, then
    \begin{align}
    \tag{3.C}
    \label{eq:3C}
    \cor{\CIIIvO}{\CVvI} \leq \YTriQuadTri.
    \end{align}
\end{lemma}
\begin{proof}
    Consider a \CIIIvO-\CVvI-trail. 
    As every edge is crossed at most three times, the trail contains no $\CIVvO$-cell and we are in the situation represented in \cref{fig:3C}.
    The vertices~$u$ and~$v$ lie on the boundary of a cell~$c$. 
    As the drawing is $3$-saturated, the edge~$uv$ is contained in~$G$ and the cell~$c$ is a $\CVvII$-cell.
    The trail together with~$c$ forms a \YTriQuadTri-configuration.
    As every \CIIIvO-\CVvI-trail is only part of one such configuration, the statement follows.
    \begin{figure}
        \centering
        \includegraphics[page=3]{figures/adjacencies_two_images.pdf}
        \caption{A \CIIIvO-\CVvI-trail (light blue). 
        It forms a \YTriQuadTri-configuration (dark) with an adjacent cell.}
        \label{fig:3C}
    \end{figure}
\end{proof}

\section{Discussion}
The \emph{$k$-planar crossing number} $\mathrm{cr}_k(G)$ is similar to the crossing number, except that the minimum is taken over all $k$-plane drawings of~$G$.
Clearly, $\mathrm{cr}(G) \leq \mathrm{cr}_k(G)$ for all~$k$ and~$G$. But there are $k$-planar $n$-vertex graphs $G$ with $\mathrm{cr}(G) \in \mathcal{O}(k)$ and $\mathrm{cr}_k(G) \in \Omega(kn)$ \cite[Theorem~2]{chimani2024crossingNumberRevisited}.
By \cref{thm:3-planar_upper_bound_crossings_and_edges}, every $3$-plane drawing of an $n$-vertex graph~$G$ has $\abs{X} \leq 5.5(n-2)$~crossings, and hence $\mathrm{cr}(G) \leq \mathrm{cr}_3(G) \leq 5.5(n-2)$. 
Although \cref{thm:3-planar_upper_bound_crossings_and_edges} is tight, 
we could have~$\mathrm{cr}(G),\mathrm{cr}_3(G)<5.5(n-2)$,
and a similar question arises for $2$-planar graphs.

\begin{question}{\ }
    \begin{itemize}
        \item Are there $3$-planar $n$-vertex graphs~$G$ with $\mathrm{cr}_3(G) = 5.5(n-2)$ or $\mathrm{cr}(G) = 5.5(n-2)$?
        \item Are there $2$-planar $n$-vertex graphs~$G$ with $\mathrm{cr}_2(G) = 3.\overline{3}(n-2)$ or $\mathrm{cr}(G) = 3.\overline{3}(n-2)$?
    \end{itemize}
\end{question}


