\section{Relating Crossing, Edge, Cell, Trail, and Configuration Counts}\label{app:constraints}

As explained above, we shall present a number of (in)equalities, each relating the number of certain cells, configurations, edges, or crossings.
We begin with three obvious equations.

\begin{observation}
    If~$\Gamma$ is a $3$-plane drawing, we have
    \begin{align}
        \tag{9.A} \label{eq:9A} \abs{E} &= \abs{E_{\times}} + \abs{E_0} \\
        \tag{8.A} \label{eq:8A} \abs{E_{\times}} &= \abs{E_1} + \abs{E_2} + \abs{E_3}  \\
        \tag{8.B} \label{eq:8B} 2\abs{X} &= \abs{E_1} + 2 \abs{E_2} + 3 \abs{E_3}  
    \end{align}
\end{observation}

Configurations are arrangements of several cells and edge-segments in a drawing~$\Gamma$ of a graph~$G$.
Formally, a \emph{configuration} is a connected labeled embedded subgraph~$H$ of the planarization~$\Lambda$ of~$\Gamma$. 
The label of a vertex~$v \in V(H)$ indicates whether~$v$ arises from a vertex of~$G$ or a crossing.
Two configurations are of the same \emph{type} if they are isomorphic as labeled embedded graphs (after possibly reflecting one of them).
We also denote the types by small pictograms such as $\YTriTriTri$ and $\YTriTri$, see \cref{fig:configurations_trails} (left) for an example.


A cell~$c$ is \emph{interior} to a configuration~$C$ if all of its boundary~$\partial c$ is part of~$C$.
We color interior cells gray in the pictograms.
An edge-segment is \emph{interior} to~$C$ if both its incident cells are interior to~$C$.
For example, a $\YTriTri$-configuration~$C$ has an interior $\CVvII$-cell and an interior $\CIVvI$-cell, whose shared outer edge-segment is the only interior edge-segment of~$C$.

%Definition trail
Now, trails are specific configurations.
Let~$T = (A_1, \dots, A_{\ell})$ be a sequence of $\ell \geq 2$ cells whose dual is a walk\footnote{in~$3$-plane drawings these are always paths} in the planarization of~$\Gamma$.
The configuration~$T$ is a \emph{trail} if 
\textbf{(1)} neither $A_1$ nor $A_{\ell}$ is a \CIVvO-cell, 
\textbf{(2)} for each $i \in [\ell-1]$ cells $A_i$ and $A_{i+1}$ share an inner edge-segment (that is interior to~$T$), and
\textbf{(3)} each of $A_2,\ldots,A_{\ell-1}$ is a \CIVvO-cell $c$ whose two interior edge-segments are opposite on its boundary~$\partial c$.
See \cref{fig:configurations_trails} (right) for an example.
Note that only two of the four inner edge-segments of each \CIVvO-cell of~$T$ are interior to~$T$ (as no edge self-intersects).
Every trail~$T$ has two \emph{bounding edges}~$e_1$ and~$e_2$, which are those crossing all interior edge-segments of~$T$. 
An $A$-$B$-trail is a trail whose endpoints are cells of type~$A$ and~$B$ respectively. 
We denote by $\cor{A}{B}$ the number of $A$-$B$-trails in~$\Gamma$.
Note in particular that $\cor{A}{B} = \cor{B}{A}$.


Recall that a $3$-plane, non-homotopic, connected, filled drawing~$\Gamma$ of a graph on at least three vertices is called \emph{$3$-saturated}.
In every $3$-saturated drawing, all cells of size at most five are non-degenerate and of one of the following types:
$\CIIIvO$, $\CIVvO$, $\CIVvI$, $\CVvO$, $\CVvI$, and $\CVvII$; cf.~\cref{fig:cell-characterization}.

\begin{lemma}
\label{lem:augmentation_to_3-saturated-drawing}
    Every $3$-plane drawing~$\Gamma$ of a connected graph~$G$ on at least three vertices can be completed to a $3$-saturated drawing by only adding edges.
\end{lemma}
\begin{proof}
    Note that the drawing~$\Gamma$ is connected as~$G$ is connected.
    We therefore only need to enforce the filled property, while preserving all other properties.
    Suppose there is a cell~$c$ with vertices~$u$ and $v$ on its boundary, but no edge~$uv$ lies on~$\partial c$. 
    We can insert an edge~$uv$ within the cell~$c$, without creating new crossings. 
    The edge might be a parallel edge. 
    Yet, as no edge connecting $u$ and~$v$ lies on the boundary~$\partial c$, we did not create an empty lens.
    Therefore, the drawing is still non-homotopic.
    Neither does this create self-crossings or incident crossing edges.
    Inductively, the claim follows.
\end{proof}






\subsection{Lower Bounds on the Number of Cells and Configurations}


\begin{lemma}%2.A-2.D
    If~$\Gamma$ is a $3$-saturated drawing, then 
    \begin{align}
        \tag{2.A} \label{eq:2A} \CIVvI &= \cor{\CIVvI}{\CVvI} + \cor{\CIVvI}{\CVvO} + \cor{\CIVvI}{\Clarge} \\
        \tag{2.B} \label{eq:2B} 2\mul \CVvI &= \cor{\CIVvI}{\CVvI} + 2\cor{\CVvI}{\CVvI} + \cor{\CVvI}{\CIIIvO} + \cor{\CVvI}{\CVvO} + \cor{\CVvI}{\Clarge} \\
        \tag{2.C} \label{eq:2C} 3\mul\CIIIvO &= \cor{\CIIIvO}{\CVvI} + \cor{\CIIIvO}{\CVvO} + \cor{\CIIIvO}{\Clarge} \\
        \tag{2.D} \label{eq:2D} 5\mul\CVvO &= \cor{\CIIIvO}{\CVvO} + \cor{\CVvO}{\CIVvI} + \cor{\CVvO}{\CVvI} + 2\cor{\CVvO}{\CVvO} + \cor{\CVvO}{\Clarge}
    \end{align}
\end{lemma}
\begin{proof}
    We only prove the first equality. 
    The remaining equations can be shown in a similar way.
    Consider a \CIVvI-cell~$c$. 
    By \cref{obs:one_corridor_per_inner_segment}, the inner edge-segment on the boundary of~$c$ is interior to a trail starting in~$c$. 
    Let~$c'$ be the cell corresponding to the other end of the trail. 
    As parallel edges do not form an empty lens, $c'$ cannot be a \CIVvI-cell.
    Further, no two adjacent edges cross.
    Thus, $c'$ cannot be a \CIIIvO-cell.
    Recall that no end of a trail corresponds to a \CIVvO-cell, yet the cell~$c'$ has to be incident to an inner edge-segment. 
    Thus, $c'$ is a \CVvI-, a \CVvO- or a \Clarge-cell (i.e. a cell of size at least~$6$).
    As every \CIVvI-cell is only incident to one inner edge-segment, we obtain one trail for each such cell.
    Double-counting yields \eqref{eq:2A}.
\end{proof}



\begin{lemma}%3.A
    If~$\Gamma$ is a $3$-saturated drawing, then
    \begin{align}
    \tag{3.A}
    \label{eq:3A}
    \cor{\CIIIvO}{\CVvO} \leq \YTriQuad.
    \end{align}
\end{lemma}
\begin{proof}
    Consider a \CIIIvO-\CVvO-trail~$T$, see \cref{fig:3A}. 
    We use the same notation as in \cref{fig:3A}.
    Note that~$T$ contains no \CIVvO-cell as each of its bounding edges~$u'u$ and~$v'v$ is already crossed three times.
    For the same reason, one of the endpoints of $uu'$ and $vv'$ lies on the boundary of~$c$ and~$c'$, respectively, i.e. $u \in \partial c$ and $v \in \partial c'$.
    As the edge~$e$ is crossed at least twice, an endpoint~$w$ of~$e$ is incident to~$c$ or~$c'$. 
    We may assume without loss of generality that~$w$ lies on~$\partial c'$. 
    Observe that~$w$ and~$v$ are both incident to~$c'$.
    Since the drawing is $3$-saturated, $vw \in E(G)$ and $c'$ is a $\CVIvII$-cell.
    Similarly, we see that $uv \in E(G)$ and the cell~$c''$ is a \CVvII-cell.
    Thus, the cells~$c'$ and~$c''$ form a \YTriQuad-configuration~$C$.

    We now observe that no other \CIIIvO-\CVvO-trail is adjacent to~$C$.
    The two outer segments of the \CVvII-cell in~$C$ are part of the two bounding edges of the \CIIIvO-\CVvO-trail~$T$, see \cref{fig:3A} (right).
    As no two \CIIIvO-\CVvO-trails have the same bounding edges, each is adjacent to a different \YTriQuad-configuration and the inequality above follows.
    \begin{figure}[bt]
        \centering
        \includegraphics[page=1]{figures/adjacencies_two_images.pdf}
        \caption{A $\CIIIvO$-$\CVvO$-trail (light blue) and its boundary (thick) is represented on the left. Such a trail is always adjacent to a $\YTriQuad$ (dark blue). The adjacency is represented on the right.}
        \label{fig:3A}
    \end{figure}
\end{proof}

\begin{lemma}%3.B
    If~$\Gamma$ is a $3$-saturated drawing, then
    \begin{align}
    \tag{3.B}
    \label{eq:3B}
    \cor{\CVvO}{\CVvI} \leq \YQuintQuadTri.
    \end{align}
\end{lemma}
\begin{proof}
    Consider a \CVvO-\CVvI-trail.
    As the drawing is $3$-plane, the trail contains no \CIVvO-cell, and we are in the situation represented in \cref{fig:3B}. 
    The edge~$e$ (represented by a thick line) is crossed three times.
    Thus, one of its endpoints lies on the boundary of the cell~$c$. 
    Let~$u$ denote this vertex.
    Note that the vertex~$v$, which is the only vertex on the \CVvI-cell, is also incident to~$c$.
    As the drawing is $3$-saturated, $uv$ is an edge and $c$ is a \CVvII-cell.
    The \CVvO-\CVvI-trail together with~$c$ forms a \YQuintQuadTri.
    For every \CVvO-\CVvI-trail, we obtain a distinct \YQuintQuadTri (which may share a \CVvII-cell with another such configuration) and the inequality follows. 
    \begin{figure}[tb]
        \centering
        \includegraphics[page=2]{figures/adjacencies_two_images.pdf}
        \caption{A \CVvO-\CVvI-trail (light blue). The bounding edge~$e$ (thick) is crossed three times. Such a trail forms a \YQuintQuadTri with an adjacent cell. The \YQuintQuadTri (dark blue) is represented on the right.}
        \label{fig:3B}
    \end{figure}
\end{proof}


\begin{lemma}%3.D
     If~$\Gamma$ is a $3$-saturated drawing, then
    \begin{align}
    \tag{3.D}
    \label{eq:3D}
    \CIVvI \leq \YTriTri + \YTriTriTri.
    \end{align}
\end{lemma}
\begin{proof}
    We show that each \CIVvI-cell is contained in a \YTriTri- or a \YTriTriTri-configuration.
    Consider the inner edge-segment of a \CIVvI-cell~$c$ and let~$e$ be the corresponding edge.
    We denote the two cells sharing an outer edge-segment with~$c$ by $c'$ and~$c''$.
    As the edge~$e$ is crossed at most three times, an endpoint~$v$ of~$e$ lies on the boundary of~$c'$ or~$c''$. 
    Without loss of generality, we are therefore in the situation represented in \cref{fig:3D}.
    The two vertices~$u$ and~$v$ lie on the boundary of the cell~$c''$.
    As~$\Gamma$ is $3$-saturated, $uv$ is an edge of~$G$ and~$c''$ is a \CVvII-cell. 

    If~$e$ is crossed three times, the three cells $c', c$ and $c''$ are in \YTriTri-configuration.
    Otherwise, $e$ is crossed twice and the same argument as above shows that $c'$ is also a \CVvII-cell. 
    In particular, the cells $c', c$ and $c''$ are in \YTriTriTri-configuration.

    As every \CIVvI-cell is only contained in one such configuration, the upper bound on the number of \CIVvI-cells follows.
