\end{proof}

\begin{lemma}%3.E
    If~$\Gamma$ is a $3$-saturated drawing, then
    \begin{align}
    \tag{3.E}
    \label{eq:3E}
    \cor{\CIVvI}{\CVvI} \leq \frac{1}{2} \abs{E_1} + \YTriQuadQuad.
    \end{align}
\end{lemma}
\begin{proof}
    Note that it suffices to show that every $\CIVvI$-$\CVvI$-trail forms a $\YTriQuadQuad$-configuration or has a bounding edge that is crossed at most once.
    The claim then follows as every edge is a bounding edge of at most two trails.

    Consider a \CIVvI-\CVvI-trail. 
    As every edge is crossed at most three times, the trail contains at most one~$\CIVvO$-cell.

    If the trail contains no such cell, we are in the situation depicted on the left of \cref{fig:3E}. 
    Note that the bounding edge~$e$ of the trail is crossed only once. 

    If the trail contains a $\CIVvO$-cell, we are in the situation represented on the right of \cref{fig:3E}. 
    The trail forms a $\YTriQuadQuad$-configuration.

    Thus, the number of \CIVvI-\CVvI-trails yields a lower bound on the sum of half the number of edges that are crossed only once, and the number of $\YTriQuadQuad$-configurations.
    \begin{figure}[t]
        \centering
        \includegraphics[page=5]{figures/adjacencies_two_images.pdf}
        \caption{A \CIVvI-\CVvI-trail with no $\CIVvO$-cell is depicted on the left, and with one $\CIVvO$-cell on the right.}
        \label{fig:3E}
    \end{figure}
\end{proof}

\begin{lemma}%4.A
    If~$\Gamma$ is a $3$-saturated drawing, then
    \begin{align}
    \tag{4.A}
    \label{eq:4A}
    2\mul\cor{\CVvO}{\CVvO} + \cor{\CIVvI}{\CVvO} + \cor{\CIIIvO}{\CVvO} - 4\mul \CVvO \leq \YStar.
    \end{align}
\end{lemma}
\begin{proof}
    Let~$T$ be a trail ending in a $\CVvO$-cell and let~$e_1$ and~$e_2$ be the two edges on its boundary.
    If the other end of~$T$ corresponds to a $\CIVvI$-, $\CVvO$- and $\CIIIvO$-cell, the edges~$e_1$ and~$e_2$ have the same number of crossings within the trail.
    We therefore call these cells \emph{crossing-even} and use the same term for trails where one endpoint corresponds to a $\CVvO$-cell, the other to a crossing-even cell. 
    A $\CVvO$-cell where every incident trail ends in a crossing-even cell is \emph{saturated}.
    We denote the number of saturated $\CVvO$-cells by~$\ell$.

    \proofsubparagraph{An upper bound on the number~$\bm{\ell}$ of saturated $\CVvO$-cells.}
    We first show that every saturated $\CVvO$-cell is part of at least one $\YStar$-configuration. 
    As no such configuration contains two $\CVvO$-cells, we then obtain
    \[
    \label{eq:num_saturated_c5v0_at_most_number_ystar}
    \ell \leq \YStar. \tag{$\star$}
    \]

    Consider a saturated $\CVvO$-cell~$c$. 
    We say that a trail incident to~$c$ is \emph{uncrossed} if its boundary contains no crossing that is not incident to~$c$.
    Otherwise, we say that it is \emph{crossed}.
    In fact, all such uncrossed trails end in a $\CIVvI$-cell and contain no $\CIVvO$-cell. 
    Every trail~$T$ incident to~$c$ contains an inner edge-segment~$s(T)$ on the boundary of~$c$ in its interior.
    Two such trails~$T$ and~$T'$ are called \emph{consecutive} if the edge-segments~$s(C)$ and~$s(C')$ share a crossing.

    We first show that there are at least three consecutive uncrossed trails incident to the saturated cell~$c$. 
    If none of the incident trails of~$c$ is crossed, the claim clearly holds.
    Otherwise, some trail~$A$ is crossed, see \cref{fig:4_oversaturation} (left).
    Recall that~$A$ is crossing-even.
    Thus, the two edges on its boundary are crossed three times.
    Therefore, the trails~$C$ and $D$ are uncrossed.
    The same argument shows that only one of the two remaining trails~$B$ and~$E$ is crossed.
    We therefore obtain three consecutive uncrossed trails.

    As every uncrossed trail ends in a $\CIVvI$-cell and contains no $\CIVvO$-cell, we are in the situation depicted in \cref{fig:4_oversaturation} (right).
    \begin{figure}[tb]
        \centering
        \includegraphics[page=6]{figures/adjacencies_two_images.pdf}
        \caption{Left: A saturated $\CVvO$-cell with its incident trails is represented. One of the trails is crossed. The corresponding boundary edges are represented with thick lines.
        Right: A saturated $\CVvO$-cell with three consecutive uncrossed trails.}
        \label{fig:4_oversaturation}
    \end{figure}
    Note that the vertices~$u$ and~$v$ lie on the boundary of a cell~$c'$. 
    Thus, $uv \in E(G)$ and~$c'$ is a $\CVvII$-cell as~$\Gamma$ is $3$-saturated.
    Similarly, we see that $vw \in E(G)$ and~$c''$ is a $\CVvII$-cell.
    The cells~$c$, $c'$ and~$c''$ form a $\YStar$-configuration.
    It follows that every saturated $\CVvO$-cell is part of a $\YStar$-configuration.

    \medskip

    \proofsubparagraph{A lower bound on the number~$\bm{\ell}$ of saturated $\CVvO$-cells.}
    We define \[k \coloneqq 2\mul\cor{\CVvO}{\CVvO} + \cor{\CIVvI}{\CVvO} + \cor{\CIIIvO}{\CVvO},\]
    i.e. $k$ corresponds to the number of incidences between crossing-even trails and~$\CVvO$-cells.
    It remains to show that 
    \[
    \label{eq:num_saturated_c5v0_lower_bounded_by_crossing_even_ccorridors}
    k  - 4\mul \CVvO \leq \ell. \tag{$\star\star$}
    \]
    The claim then follows by combining~\eqref{eq:num_saturated_c5v0_at_most_number_ystar} and \eqref{eq:num_saturated_c5v0_lower_bounded_by_crossing_even_ccorridors}.

    Every $\CVvO$-cell that is not saturated is incident to at most four crossing-even trails while every saturated $\CVvO$-cell is incident to five such trails.
    As there are $k$~incidences between crossing-even trails and $\CVvO$-cells, we obtain $k \leq 4(\CVvO-\ell) + 5\ell = 4\CVvO + \ell$.
    Thus, \eqref{eq:num_saturated_c5v0_lower_bounded_by_crossing_even_ccorridors} holds.
\end{proof}

\begin{lemma}%4.B
    If~$\Gamma$ is a $3$-saturated drawing, then
    \begin{align}
    \tag{4.B}
    \label{eq:4B}
    \YTriTriTri \geq \YStar.
    \end{align}
\end{lemma}
\begin{proof}
    Each \YStar-configuration contains a \YTriTriTri.
    As no two \YStar-configurations share a \YTriTriTri, the claim follows.
\end{proof}

\begin{lemma}%9.C
    For every drawing~$\Gamma$, we have
    \begin{align}
    \tag{9.C}
    \label{eq:9C}
        2\mul\CVvII \geq  \YQuintQuadTri +  \YTriQuad +  \YTriQuadTri +  \YTriTri + 2\YTriTriTri.
    \end{align}
\end{lemma}
\begin{proof}
    We give a lower bound on the number of \CVvII-cells by double-counting the number of outer edge-segments incident to a \CVvII-cell.

    Every \CVvII-cell is incident to two outer edge-segments.

    Recall that an edge-segment is interior to a configuration~$C$ if both its incident cells are interior to~$C$.
    In each of the configurations $\YQuintQuadTri$, $\YTriQuad$, $\YTriQuadTri$, $\YTriTri$ and $\YTriTriTri$, exactly one outer edge-segment~$s_c$ of each interior $\CVvII$-cell~$c$ is interior to the configuration.
    Note in particular that we did not count any such edge-segment twice due to the choice of the configurations we consider.
    Indeed, any two configurations may share a \CVvII-cell~$c$, but the corresponding outer edge-segments~$s_c$ do not coincide.
    As each $\YQuintQuadTri$, $\YTriQuad$, $\YTriQuadTri$ and $\YTriTri$ contains one outer edge-segment that is incident to a \CVvII-cell in its interior, and \YTriTriTri contains two such segments, the lower bound on the number of \CVvII-cells follows.
\end{proof}


\subsection{Lower Bounds on the Number of Edges}

\begin{lemma}%6. Counting outer segments
    For every drawing $\Gamma$, we have
    \begin{align}
    \tag{6}
    \label{eq:6}
        4 \abs{E_{\times}} \geq 2\mul\CIVvI + 2\mul\CVvI + 2\mul \CVvII + 2\mul \CVIvII.
    \end{align}
\end{lemma}
\begin{proof}
    We double count the number~$\ell$ of incidences between outer edge-segments and cells.

    Every crossed edge has exactly two outer edge-segments. 
    Each of them is incident to two cells.
    Thus, $4 \abs{E_{\times}} = \ell$. 

    Every \CIVvI-cell, every \CVvI-cell, every \CVvII-cell and every \CVIvII-cell is incident to exactly two outer edge-segments.
    We therefore have, $\ell \geq 2\CIVvI + 2\mul\CVvI + 2\mul \CVvII + 2\mul \CVIvII$ which yields the claim.
\end{proof}

\begin{lemma}%7. Counting inner segments
    For every drawing~$\Gamma$, we have
    \begin{align}
        2\abs{E_2} + 4 \abs{E_3} \geq 3\mul\CIIIvO &+  \CIVvI + 4\mul\CIVvO + 2\mul \CVvI + 5\mul\CVvO \notag \\
        &+ \cor{\CIVvI}{\Clarge} + \cor{\CVvI}{\Clarge} + \cor{\CIIIvO}{\Clarge} + \cor{\CVvO}{\Clarge}. \tag{7}
    \label{eq:7}
    \end{align}
\end{lemma}
\begin{proof}
    We double count the number~$\ell$ of incidences between inner edge-segments and cells.

    An edge that is crossed $k$ times is split into $k+1$ edge-segments, $k-1$ of which are inner edge-segments. 
    Each inner edge-segment is incident to two cells.
    We therefore have $2 \abs{E_2} + 4 \abs{E_3} \geq \ell$.

    On the other hand, every \CIIIvO-cell, every \CIVvI-cell, every \mul\CIVvO-cell, every \CVvI-cell and every \CVvO-cell is incident to $3$, $1$, $4$, $2$ and $5$ inner edge-segments respectively.
    In order to obtain a lower bound for the number of inner edge-segment incidences with large cells, it suffices to count the number of trails ending in large cells.
    Indeed, each such trail enters a large cell through an inner edge-segment.
    This yields the right side of the inequality above.
\end{proof}

\begin{lemma}%8.C
    For every drawing~$\Gamma$, we have
    \begin{align}
    \tag{8.C}
    \label{eq:8C}
        \abs{E_2} \geq \frac{1}{2} \mul \YTriQuadQuad + \YStar
    \end{align}
\end{lemma}
\begin{proof}
    Every \YTriQuadQuad-configuration contains an edge that is crossed twice. 
    This edge may be contained in at most two such configurations. 
    Similarly, every \YStar-configuration contains an edge that is crossed twice. 
    Note that this edge cannot be contained in any other \YStar- or \YTriQuadQuad-configuration.

    Thus, the sum of $\frac{1}{2}\YTriQuadQuad$ and $\YStar$ provides a lower bound on the number~$\abs{E_2}$ of edges that are crossed exactly twice.
\end{proof}

Double-counting the number of incidences of uncrossed edges with cells yields the following.
\begin{lemma}%9.B
    For every drawing~$\Gamma$, we have
    \begin{align}
    \tag{9.B}
    \label{eq:9B}
        2\abs{E_0} \geq \CVvII + \CVIvII.
    \end{align}
\end{lemma}

\subsection{Relating the Number of Cells, Crossings and Edges}


\begin{corollary}%5.B
    If $\Gamma$ is a $3$-saturated drawing on at least three vertices, then
    \begin{align}
    \tag{5.B}
    \label{eq:5B}
    \abs{X} \leq 5\abs{V} + 2\mul\CIIIvO + \CIVvO + \CIVvI -\frac{1}{6}\sum_{a \geq 6} a \abs{\calC_a} - \abs{E}.
    \end{align}
\end{corollary}
\begin{proof}
    Recall that every $3$-saturated drawing is in particular connected.
    As the graph contains at least three vertices, every cell has size at least~$3$. 
    Considering $t=5$ in the density formula (\cref{thm:density_formula}) yields
    \begin{equation}
        \label{eq:density_first_inequality}
        \abs{E} \leq 5\abs{V} - \sum_{c \in \calC}\left(\norm{c} - 5 \right) - \abs{X} \tag{$\star$}.
    \end{equation}
    Thus, only cells of size at most~$4$ have a positive contribution to the right side.
    Recall that there is only one cell-type of size~$3$, namely \CIIIvO, and only two types of size~$4$: \CIVvO \, and \CIVvI. 
    Cells of size~$5$ have no contribution. 
    For $a \geq 6$, we have $a-5 \geq \frac{1}{6}a$. 
    We therefore obtain
    \[
    \sum_{c \in C, \norm{c} \geq 6}\left(\norm{c} - 5\right) = \sum_{a \geq 6} \abs{\calC_a}(a-5) \geq \frac{1}{6} \sum_{a \geq 6} a \abs{\calC_a}.
    \]
    Together with \eqref{eq:density_first_inequality}, we get
    \[
        \abs{E} \leq 5\abs{V} + 2\mul\CIIIvO + \CIVvO + \CIVvI - \frac{1}{6} \sum_{a \geq 6} a \abs{\calC_a} - \abs{X}. \qedhere
    \]    
\end{proof}


