We now want to find a formulation of Theorem~\ref{thm:singer} for the case of the vector space $\V=\F^{n\times n}$, where $\F\in\{\R,\C\}$, with the spectral norm $\|\cdot\|_2$ (see \eqref{eqn:spectral}), and a given $k$-dimensional subspace $\X=\mathrm{span}\{X_1,\dots,X_k\}\subset\V$. Thus, for a given matrix $Y\in\V\setminus\X$ we are interested in characterizing its spectral approximations $X_*$ from the subspace $\X$, i.e., the solutions $X_*\in\X$ of the best approximation problem
%
\begin{equation}\label{eqn:main-prob}
\|Y-X_*\|_2=\min_{X\in\X}\|Y-X\|_2=\min_{X\in\mathcal{X}}\max_{\substack{v\in\F^n\\\|v\|_2=1}}\|(Y-X)v\|_2.
\end{equation}

In order to do so, we will determine $\norm{\cdot}_2$, the dual norm of $\|\cdot\|_2$ on $\V^*=(\F^{n\times n})^*$, and the extremal vectors in $\Omega^*\subset\V^*$.

Let $f\in\V^*$ be given. Using the standard basis $\{E_{ij}=e_ie_j^T\,:\,i,j=1,\dots,n\}$ of $\V$, every matrix $A=[a_{ij}]\in \V$ can be written as $\sum_{i,j=1}^n a_{ij}E_{ij}$. Thus,
%
$$f(A)=f\Big(\sum_{i,j=1}^n a_{ij}E_{ij}\Big)=\sum_{i,j=1}^n a_{ij}f(E_{ij})=\mathrm{trace}(F^{H}A),$$
%
where 
%
$$F=[f_{ij}]\in\V\quad\mbox{with}\quad f_{ij}\equiv \overline{f(E_{ij})}.$$ 
%
We call the uniquely determined matrix $F\in\V$ the \emph{standard matrix representation} of the linear functional $f\in\V^*$. It is well known that the map $\V^*\to \V$, $f\mapsto F$, is a vector space isomorphism.

\begin{rmk}
Note that, in general, a matrix representation of a linear functional $f:\V\rightarrow\F$ depends on the chosen bases of $\V$ and $\F$. Our choice of the two bases, namely the standard basis of $\V$ and the basis $\{1\}$ of $\F$, yields the unique matrix representation $F$ satisfying $f(A)=\mathrm{trace}(F^HA)$ for each $A\in\V$. This feature is convenient for the derivation of the dual norm $\norm{\cdot}_2$ on $\V^*$.
\end{rmk}

If we denote
%
$$\langle F,A\rangle\equiv \mathrm{trace}(F^{H}A),$$
%
then the dual norm of $\|\cdot\|_2$ on $\V^*$ is given by (cf. Definition~\ref{def1})
%
\begin{equation}\label{eqn:dual}
\norm{f}_2=\max_{A\in\Omega}|f(A)|=\max_{A\in\Omega}|\langle F,A\rangle|.
\end{equation}
%
Suppose that $\mathrm{rank}(F)=r\leq n$, and let 
%
\begin{equation}\label{eqn:svd}
F=U_r\Sigma_r V_r^H= \sum_{j=1}^r \sigma_j u_jv_j^H,\quad \sigma_1\geq\cdots\geq\sigma_r>0,
\end{equation}
%
be a singular value decomposition of $F$. Then for any $A=[a_{ij}]\in \V$ we have 
%
\begin{align}\label{eqn:ident}
\langle F,A\rangle &=
\mathrm{trace}(V_r\Sigma_r U_r^HA)=
\mathrm{trace}(\Sigma_r U_r^HAV_r)=\sum_{j=1}^r \sigma_j u_j^H Av_j.
\end{align}
%
We use this identity to prove the following result; cf.~\cite[Theorem~1]{LaRi1981}.

\begin{lem}
Consider the vector space $\F^{n\times n}$ with the spectral norm $\|\cdot\|_2$. If $f\in(\F^{n\times n})^*$ has the standard matrix representation $F\in\F^{n\times n}$ with the singular value decomposition \eqref{eqn:svd}, then 
%
$$\norm{f}_2=\sum_{j=1}^r\sigma_j.$$
%
Thus, $\norm{f}_2$ is equal to the Schatten 1-norm (or nuclear norm, trace norm) of $F$, and we write $\norm{F}_2\equiv \norm{f}_2$.
%
\end{lem}

\begin{proof}
The definition of the dual norm in \eqref{eqn:dual}, the identity \eqref{eqn:ident}, and the triangle and Cauchy-Schwarz inequalities yield
%
$$\norm{f}_2\leq \sum_{j=1}^r \sigma_j \max_{A\in\Omega} |u_j^H Av_j|\leq 
\sum_{j=1}^r \sigma_j \max_{A\in\Omega} \|Av_j\|_2 =\sum_{j=1}^r \sigma_j.$$
%
On the other hand, for the matrix $A=U_rV_r^H\in\Omega$ we obtain
%
$$\norm{f}_2\geq |\langle F,A\rangle|=\mathrm{trace}(V_r\Sigma_r U_r^HU_r V_r^H)=\mathrm{trace}(\Sigma_r)=\sum_{j=1}^r \sigma_j.$$
\end{proof}

Note that any matrix $F\in\F^{n\times n}$ with a singular value decomposition of the form \eqref{eqn:svd} satisfies 
%
$$\sigma_1=\|F\|_2\leq \norm{F}_2=\sum_{j=1}^r \sigma_j,$$
%
which shows that $\|F\|_2=\norm{F}_2$ holds if and only if $\mathrm{rank}(F)=1$. 
The next lemma is~\cite[Theorem~2]{LaRi1981}, here including also the complex case and with a modified proof.

\begin{lem}
Consider the vector space $\F^{n\times n}$ with the spectral norm $\|\cdot\|_2$ and the corresponding unit sphere $\Omega$. A functional $f\in\Omega^*$ is extremal if and only if its standard matrix representation $F\in\F^{n\times n}$ is of the form $F=uv^H$ with unit Euclidean norm vectors $u,v\in\F^n$.     
\end{lem}

\begin{proof}
We start analogously to the proof in~\cite[p.~115]{LaRi1981}. Suppose that $f\in\Omega^*$ has the standard matrix representation $F\in\F^{n\times n}$ with $\mathrm{rank}(F)=r\geq 2$. We will show that $f$ is then not extremal. We have $1=\norm{f}_2=\norm{F}_2$, and hence $F$ has a singular value decomposition of the form
%
$$F=\sum_{j=1}^r \sigma_j u_jv_j^H,\quad \mbox{where}\quad \sum_{j=1}^r \sigma_j=1.$$
%
In particular, we must have $0<\sigma_2\leq \sigma_1<1$. 
Let $\epsilon>0$ be such that $\sigma_1+\epsilon<1$ and $\sigma_2-\epsilon>0$, and define the matrices
%
\begin{align*}
F_1 &\equiv (\sigma_1+\epsilon)u_1v_1^H+(\sigma_2-\epsilon)u_2v_2^H+\sum_{j=3}^r\sigma_j u_jv_j^H,\\
F_2 &\equiv (\sigma_1-\epsilon)u_1v_1^H+(\sigma_2+\epsilon)u_2v_2^H+\sum_{j=3}^r\sigma_j u_jv_j^H.
\end{align*}
%
Then $\norm{F_1}_2=\norm{F_2}_2=1$, and $F=\frac12(F_1+F_2)$, while $F_1\neq F_2$. 
If $f_1,f_2\in\Omega^*$ are the uniquely determined linear functionals corresponding to the matrices $F_1,F_2$, respectively, then $f=\frac12(f_1+f_2)$, while $f_1\neq f_2$, which shows that $f$ is not extremal.

Now let $f\in\Omega^*$ have the standard matrix representation $F\in\F^{n\times n}$ with $\mathrm{rank}(F)=1$. Then $\norm{f}_2=\norm{F}_2=\|F\|_2=1$, and hence $F=uv^H$ with $\|u\|_2=\|v\|_2=1$. We will show that $f$ is extremal, but we proceed differently than in~\cite{LaRi1981}.

Let $f_1,f_2\in\Omega^*$ be such that $f=\frac12(f_1+f_2)$, then the corresponding standard matrix representations satisfy $F=\frac12(F_1+F_2)$. Since $\norm{F_1}_2=\norm{F_2}_2=1$, we have $\|F_1\|_2\leq 1$ and $\|F_2\|_2\leq 1$, so that
%
$$1=\norm{F}_2=\|F\|_2=\frac12 \|F_1+F_2\|_2\leq \frac12 (\|F_1\|_2+\|F_2\|_2)\leq 1,$$
%
which implies $\|F_1\|_2=\|F_2\|_2=1$. 

We now consider one of the matrices $F_j$, $j=1,2$. From $\norm{F_j}_2=\|F_j\|_2=1$ we see that $\mathrm{rank}(F_j)=1$, and hence $F_j=u_jv_j^H$ with $\|u_j\|_2=\|v_j\|_2=1$. Since $\|F_j\|_2=1$, we have $|u^HF_jv|\leq 1$. The equalities $F=\frac12(F_1+F_2)$ and $F=uv^H$ imply $2=u^HF_1v+u^HF_2v$, and combining this with $|u^HF_jv|\leq 1$ yields 
%
$$1=u^HF_jv=(u^Hu_j)(v_j^Hv),$$
%
from which we obtain $u^Hu_j=e^{i\alpha_j}$ and $v_j^Hv=e^{-i\alpha_j}$ for some $\alpha_j\in [0,2\pi)$. Since $1=|u^Hu_j|=\|u\|_2\|u_j\|_2$, we must have $u_j=\beta_j u$ with $|\beta_j|=1$, and thus $\beta_j=e^{i\alpha_j}$, i.e., $u_j=e^{i\alpha_j}u$. Analogously we get $v_j=e^{i\alpha_j}v$, and hence
%
$$F_j=u_jv_j^H=(e^{i\alpha_j} u)(e^{i\alpha_j} v)^H=uv^H=F, \quad j=1,2.$$
%
This yields $f_1=f_2=f$, so that $f$ is indeed extremal.
\end{proof}

If $f\in\Omega^*$ is extremal, and $F=uv^H$ is its standard matrix representation, then for every $A\in\F^{n\times n}$ we have
%
$$\langle F,A\rangle =\mathrm{trace}(uv^HA)=\mathrm{trace}(v^HAu)=v^HAu.$$
%
We use this observation in condition (2) of our following matrix-version of Theorem~\ref{thm:singer}; cf.~\cite[Theorem~3]{LaRi1981}.

\begin{thm}\label{thm:singer-mat1}
Consider a $k$-dimensional subspace $\X\subset \F^{n\times n}$, and let $Y\in\F^{n\times n}\setminus\X$ and $X_*\in\X$ be given. Then the following are equivalent:
\begin{itemize}
    \item[$(1)$] The matrix $X_*$ is a spectral approximation of $Y$ from the subspace $\X$, i.e., it solves the problem \eqref{eqn:main-prob}.
    \item[$(2)$] There exist $\ell$ rank-one matrices $u_1v_1^H,\dots,u_\ell v_\ell^H\in\F^{n\times n}$, with $\|u_i\|_2=\|v_i\|_2=1$ for $i=1,\dots,\ell$, where $1\leq\ell\leq k+1$ if $\F=\R$ and $1\leq\ell\leq2k+1$ if $\F=\C$, and $\ell$ positive real numbers $\omega_{1},\dots,\omega_{\ell}$ with $\omega_{1}+\dots+\omega_{\ell}=1$, such that 
    \begin{align*}
    \sum_{j=1}^{\ell}\omega_{j}u_j^H Xv_j & = 0,\quad \mbox{for all $X\in\X$, and }\\
    u_j^H(Y-X_*)v_j & = \|Y-X_{*}\|_2,\quad \mbox{for $j=1,\dots,\ell$.}
    \end{align*}
\end{itemize}
\end{thm}

Further equivalent characterizations of spectral approximations are given in~\cite[Corollary~4.1]{Zi1993} and~\cite[p.~173]{Zi1996} (cf. also~\cite[Lemma~3.2]{LiTi2009} and~\cite[Section~7]{Zi2017}).

If we denote the rank-one matrices in condition (2) of Theorem~\ref{thm:singer-mat1} by $F_j\equiv u_jv_j^H$, $j=1,\dots,\ell$, and define $F\equiv \sum_{j=1}^\ell \omega_j F_j$, then $F\in\F^{n\times n}$ is a matrix with $\norm{F}_2=1$ and rank at most $\ell$ that satisfies
%
$$\langle F, Y-X_*\rangle = \|Y-X_*\|_2.$$
%
This observation is a variant of~\cite[Theorem~4.1]{Zi1993}. 

Next note that if
\[
u_j^{H}(Y-X_{*})v_j=\|Y-X_{*}\|_2
\]
holds for unit Euclidean norm vectors $u_j$ and $v_j$, then these vectors are left resp. right singular vectors corresponding to the maximal singular value of $Y-X_{*}$. We call such vectors \emph{maximal} left and right singular vectors, and we denote by $\Sigma_{Y-X_{*}}$ the span of the maximal right singular vectors of $Y-X_{*}$. We thus can formulate the following result.

\begin{cor} 
\label{cor:cond3}
In the notation of Theorem~\ref{thm:singer-mat1}, the matrix $X_*\in\X$ solves the problem \eqref{eqn:main-prob} if and only if there exist $\ell$ vectors $v_1,\dots,v_\ell\in\Sigma_{Y-X_*}$, where $1\leq\ell\leq k+1$ if $\F=\R$ and $1\leq\ell\leq2k+1$ if $\F=\C$, and $\ell$ positive real numbers $\omega_{1},\dots,\omega_{\ell}$ with $\omega_{1}+\dots+\omega_{\ell}=1$, such that 
%
\begin{equation}\label{eqn:cond3}
\sum_{j=1}^{\ell}\omega_{j}u_j^H Xv_j = 0,\quad \mbox{for all $X\in\X$,}
\end{equation}
%
where the $u_j$ are corresponding maximal left singular vectors, i.e., $(Y-X_*)v_j=\sigma_1 u_j$ for $j=1,\dots,\ell$.
\end{cor}

The problem of minimizing the spectral norm of the matrix $Y-X$ also can be formulated as a semidefinite program; see \cite[p.~55]{VaBo1996} for the case $\F=\R$ and \cite{ToTr1998} for $\F=\C$.
The notion of duality discussed in this section via Singer's theorem
then coincides with semidefinite programming duality; see \cite[pp.~67--68]{VaBo1996} for $\F=\R$. Based on the results of \cite{ToTr1998},
extending the dual problem formulation to $\mathbb{F}=\mathbb{C}$
would be straightforward. Since the optimal duality gap is zero for this
class of semidefinite programs, it becomes possible to investigate
the structure of the Hermitian positive semidefinite matrices in $\mathbb{F}^{2n\times2n}$
that solve the semidefinite dual problem. In particular, this structure can be described in terms of the maximal right and left singular vectors of $Y-X_{*}$ and the positive scalars $\omega_{i}$ introduced above. This would offer yet another equivalent characterization of a spectral approximation $X_{*}$ from the semidefinite programming perspective. 
The precise formulation of this characterization lies beyond the scope of this paper, but we will mention some details for the case $\F=\R$.

In the notation of Corollary~\ref{cor:cond3} we can define the matrices 
%
$$U\equiv [u_1,\dots,u_\ell],\quad V\equiv [v_1,\dots,v_\ell],\quad
\Lambda\equiv \frac12 {\rm diag}(\omega_1,\dots,\omega_\ell),$$
%
and
%
$$
Z\equiv \begin{bmatrix}
    U\Lambda U^T & U\Lambda V^T\\ V\Lambda U^T & V\Lambda V^T
\end{bmatrix}\equiv \begin{bmatrix} C & B^T\\ B & D\end{bmatrix}.
$$
%
Then $Z\in\R^{2n\times 2n}$ is a symmetric positive semidefinite matrix with $\mathrm{trace}(Z)=1$, and according to \eqref{eqn:cond3}  we have
$$
\mathrm{trace}(BX_i)=\mathrm{trace}(\Lambda U^TX_iV)=\sum_{j=1}^\ell\omega_j u_j^TX_i v_j=0, \quad i=1,\dots,k.
$$
Moreover,
\begin{align*}
\mathrm{trace}(BY) &=
\mathrm{trace}(B(Y-X_*)) = 
\mathrm{trace}(\Lambda U^T(Y-X_*)V) = 
\frac{\sigma_1}{2},
\end{align*}
%
so that $Z$ solves the dual problem 
\begin{equation}
\max2\,\mathrm{trace}\left(BY\right)\quad\mbox{s.t.}\quad Z^{T}=Z\equiv\left[\begin{array}{cc}
C & B^{T}\\
B & D
\end{array}\right]\geq 0,\label{eq:dual}
\end{equation}
\[
0=\mathrm{trace}\left(BX_{i}\right),\ i=1,\dots,k,\quad1=\mathrm{trace}(Z);
\]
see \cite[p.~66]{VaBo1996} for the formulation of the dual semidefinite program to \eqref{eqn:main-prob}. (Here $Z\geq 0$ means that $Z$ is positive semidefinite.)

Note that formulating \eqref{eqn:main-prob} as a semidefinite program is also useful for computing spectral approximations numerically. To solve problem \eqref{eqn:main-prob} one can use CVX, a package for specifying and solving convex programs \cite{cvx,gb08}.
The standard CVX distribution includes well-tuned software packages for semidefinite programming such as SDPT3~\cite{SDPT3} and SeDuMi~\cite{SeDuMi}. For completeness we provide the MATLAB function {\tt bestmat}, which we have used in Example~\ref{ex:LauRhia} to compute a spectral approximation.

\begin{lstlisting}[style=Matlab-editor] 
function [S,R,a] = bestmat(Y,X)
% INPUT
%   Y ... the n x n matrix to be approximated
%   X ... a basis of the k-dimensional subspace
% OUTPUT
%   S ... a spectral approximation X_* of Y
%   R ... the residual matrix Y - S
%   a ... the coefficients of S in the basis X
n = size(Y, 1); 
k = length(X);
cvx_precision best 
cvx_begin sdp
    variables a(k) t
    expression R(n, n)
    S = zeros(n,n);
    for i=1:k, S = S + a(i)*X{i}; end
    R = Y - S;
    minimize( t )
    subject to
        [t * eye(n), R;
         R', t * eye(n)] >= 0;
cvx_end
end 
\end{lstlisting}


\section{Geometric characterizations of spectral approximations}\label{sec:geometry}

In this section we derive further equivalent characterizations of spectral approximations. Our approach is motivated by the analysis in~\cite{FaJoKnMa1996}, where the authors used certain generalizations of the field of values of matrices in the convergence analysis of Krylov subspace methods for solving linear algebraic systems; see Section~\ref{sec:minmax} for further details about this. In order to proceed we need the following definition; see also \cite[Definition 1.8.10, p.~85]{B:HoJo1994}.

\begin{defn}\label{def:FofM}
Let $k\geq 1$ be a given integer, and let $\F\in\{\R,\C\}$. The {\em $k$-dimensional field of the $k$ matrices $A_1,\dots,A_k\in{\mathbb F}^{n\times n}$ restricted to the subspace $\mathcal S\subseteq \F^n$} is defined by
\begin{equation}\label{eqn:GFV}
\mathscr{F}(A_1,\dots,A_k;{\mathcal S})
\equiv
\left\{\begin{bmatrix}
v^{H}A_{1}v\\
\vdots\\
v^{H}A_{k}v
\end{bmatrix}: v\in{\mathcal S},\;\|v\|_2=1\right\}\,\subset\,\F^k.    
\end{equation}
If $S=\F^n$, we call the set $\mathscr{F}(A_1,\dots,A_k;\F^n)$ the {\em $k$-dimensional field of the $k$ matrices $A_1,\dots,A_k$}, and denote it simply by $\mathscr{F}(A_1,\dots,A_k)$.
\end{defn}

Note that the matrices $A_1,\dots,A_k$ and the subspace ${\mathcal S}$ in Definition~\ref{def:FofM} are considered over the same field ${\mathbb F}$. Thus, if we consider $A_1,\dots,A_k \in \R^{n\times n}$, then $\mathcal{S}\subseteq \R^n$. In particular, the classical field of values of a single matrix $A\in\F^{n\times n}$ is the set $\mathscr{F}(A)=\mathscr{F}(A;{\C^n})$ (here a real matrix $A$ is considered complex). 

The set $\mathscr{F}(A_1,\dots,A_k)$ was called \emph{the generalized field of values} of the matrices $A_1,\dots,A_k\in\F^{n\times n}$ in~\cite{FaJoKnMa1996}. The set $\mathscr{F}(A_1,\dots,A_k;\C^n)$ for $A_1,\dots,A_k\in\F^{n\times n}$ was called the \emph{joint numerical range}, e.g., in~\cite{BiLi91,DavLiSal08,GutJonKar04,LauLiPoo22,LiPoo99}, the \emph{multiform numerical range} in~\cite{Poo94}, and the \emph{$k$-dimensional generalized field of values} in~\cite{Gre02}. The set $\mathscr{F}((A-\zeta I),\dots,(A-\zeta I)^k;\C^n)$ for certain $\zeta\in\C$ is useful in the analysis of the polynomial numerical hull of degree $k$ of a given matrix $A\in\F^{n\times n}$; see, e.g.,~\cite{DavLiSal08,Gre02}. 


Let us give two illustrations of the $k$-dimensional field of $k$ matrices with a particular focus on the (non-)convexity if this set, which will be of great interest in the following.

\begin{example} (cf. \cite[Example~3.1]{MulTom20}) 
We consider $\F=\R$ and the two matrices
%
$$A_1=\begin{bmatrix} 1& 0\\ 0 & 0\end{bmatrix},\quad
A_2=\begin{bmatrix} 0& 0\\ 1 & 0\end{bmatrix}$$
%
in $\R^{2\times 2}$. Writing the elements of $\R^2$ in the form $v=[z_1,z_2]^T$ with $z_1,z_2\in\R$ we obtain
%
$$\mathscr{F}(A_1,A_2)=\left\{
\begin{bmatrix}
z_1^2\\ z_1z_2\end{bmatrix} : z_1,z_2\in\R,\;z_1^2+z_2^2=1\right\}\subset\R^2.$$
%
We now easily see that
%
$$\begin{bmatrix}
    0\\0
\end{bmatrix},
\begin{bmatrix}
    1\\0
\end{bmatrix}\in \mathscr{F}(A_1,A_2),\quad\mbox{but}\quad
\begin{bmatrix}
    z\\0
\end{bmatrix}\notin \mathscr{F}(A_1,A_2)\;\mbox{for $0<z<1$,}$$
%
and hence $\mathscr{F}(A_1,A_2)$ is not convex.
\end{example}


\begin{example} (cf.~\cite[Example~1.2]{BiLi91} or~\cite[Example~1]{GutJonKar04})
We consider $\F=\C$ and the three matrices
%
$$A_1=\begin{bmatrix} 1& 0\\ 0 & -1\end{bmatrix},\quad
A_2=\begin{bmatrix} 0& 1\\ 1 & 0\end{bmatrix},\quad
A_3=\begin{bmatrix} 0& -i\\ -i & 0\end{bmatrix}=-i A_2$$
%
in $\C^{2\times 2}$. Writing the elements of $\C^2$ in the form $v=[z_1,z_2]^T$ with $z_1,z_2\in\C$, we obtain
%
$$\mathscr{F}(A_1,A_2,A_3)=\left\{
\begin{bmatrix}
|z_1|^2-|z_2|^2 \\ 2\mathrm{Re}(\overline{z}_1z_2) \\ 
2\mathrm{Im}(\overline{z}_1z_2) \end{bmatrix} : z_1,z_2\in\C,\;|z_1|^2+|z_2|^2=1\right\}\subset\R^3.$$
%
Every element $w\in\mathscr{F}(A_1,A_2,A_3)$ satisfies
%
\begin{align*}
\|w\|_2^2 =(|z_1|^2-|z_2|^2)^2+4|z_1z_2|^2=(|z_1|^2+|z_2|^2)^2=1,   
\end{align*}
%
i.e., $\mathscr{F}(A_1,A_2,A_3)$ is the unit sphere in $\R^3$. Thus, the set $\mathscr{F}(A_1,A_2,A_3)$ is real (although $\F=\C$) and not convex. 
\end{example}



We are now ready to formulate another equivalent characterization of 
the solution of the problem \eqref{eqn:main-prob}.

\begin{cor} \label{cor:cond4}
Consider a $k$-dimensional subspace $\X=\mathrm{span}\{X_1,\dots,X_k\}\subset \F^{n\times n}$, and let $Y\in\F^{n\times n}\setminus\X$ and $X_*\in\X$ be given.
The matrix $X_*\in\X$ solves the problem \eqref{eqn:main-prob} if and only if 
\begin{equation}\label{eqn:cond4}
0 \in 
\mathrm{cvx}\left( \mathscr{F}(A_1,\dots,A_k;\Sigma_{Y-X_{*}}) \right),
\end{equation}
where $\mathrm{cvx}$ denotes the convex hull, and 
\begin{equation}\label{eqn:Ai}
    A_i \equiv (Y-X_{*})^{H}X_{i},\quad i=1,\dots,k.
\end{equation}
\end{cor}

\begin{proof} Using $(Y-X_*)v_i=\sigma_1 u_i$, 
 condition \eqref{eqn:cond3} in Corollary~\ref{cor:cond3} is equivalent to
\[
\sum_{j=1}^{\ell}\omega_j \begin{bmatrix}
v_{j}^{H}A_{1}v_{j}\\
\vdots\\
v_{j}^{H}A_{k}v_{j}
\end{bmatrix}=
 \begin{bmatrix}
0\\
\vdots\\
0
\end{bmatrix}
 \in\mathbb{F}^{k}.
\]
Since $\omega_{1},\dots,\omega_{\ell}$ are positive real numbers with $\omega_{1}+\dots+\omega_{\ell}=1$, this means that the zero vector lies in the convex hull of the set $ \mathscr{F}(A_1,\dots,A_k;\Sigma_{Y-X_{*}})$.
\end{proof}
\medskip

The characterization presented in Corrolary~\ref{cor:cond4} can be identified with \cite[Lemma~2.15]{FaJoKnMa1996}, and also with \cite[Lemma 2.4]{GrGu1994} (for real matrices). While the proofs in~\cite{FaJoKnMa1996,GrGu1994} are non-trivial, our proof easily follows from the charaterzation of the spectral approximation in Theorem~\ref{thm:singer-mat1} and its reformulation in Corollary~\ref{cor:cond3}.


The characterization in Corollary~\ref{cor:cond4} uses the span of the maximal right singular vectors $\Sigma_{Y-X_*}$, which is inconvenient from a practical point of view. We next derive yet another equivalent characterization that avoids using this span.

\begin{thm}\label{thm:cond5}
Consider a $k$-dimensional subspace $\X=\mathrm{span}\{X_1,\dots,X_k\}\subset\F^{n\times n}$, and let $Y\in\F^{n\times n}\setminus\X$ and $X_*\in\X$ be given. In the notation of Corollary~\ref{cor:cond4}, 
condition \eqref{eqn:cond4} holds if and only if 
\begin{equation}\label{eqn:cond5}
\varrho \, e_1 \in 
\mathrm{cvx} \left( \mathscr{F}(A_Y, A_1,\dots,A_k) \right),
\end{equation}
where the matrices $A_1,\dots,A_k$ are defined by \eqref{eqn:Ai}, 
$$
    A_Y \equiv (Y-X_*)^HY,\quad \varrho \equiv \|Y-X_{*}\|_2^{2},
$$
and $e_1 \in \R^{k+1}$ is the first column of the identity matrix.
%
\end{thm}

\begin{proof}
If $0\in\mathrm{cvx}\left( \mathscr{F}(A_1,\dots,A_k;\Sigma_{Y-X_{*}}) \right)$, then there exist $v,w\in\Sigma_{Y-X_{*}}$ and 
$\alpha\in [0,1]$, such that
\[
\alpha\begin{bmatrix}
w^{H}A_1w\\
\vdots\\
w^{H}A_{k}w
\end{bmatrix}+(1-\alpha)\begin{bmatrix}
v^{H}A_{1}v\\
\vdots\\
v^{H}A_{k}v
\end{bmatrix}=\begin{bmatrix}
0\\
\vdots\\
0
\end{bmatrix}.
\]
Using $X_*\in \mathrm{span}\{X_1,\dots,X_k\}$ and denoting 
$A_{*}\equiv (Y-X_{*})^{H}X_{*}$, we find out that
$A_{*} \in \mathrm{span}\{A_1,\dots,A_k\}$ and, therefore also
$$
\alpha w^{H}A_{*}w+(1-\alpha)v^{H}A_{*}v=0.
$$
Further, realize that for any $z\in\Sigma_{Y-X_{*}}$ it holds that
$$
\varrho = z^{H}\left(Y-X_{*}\right)^{H}\left(Y-X_{*}\right)z
= z^{H}(A_Y-A_{*})z.
$$
Taking any two vectors $v,w\in\Sigma_{Y-X_{*}}$ 
we obtain
\begin{align*}
\varrho  &=  \alpha w^{H}\left(A_Y-A_{*}\right)w+(1-\alpha)v^{H}\left(A_Y-A_{*}\right)v\\
  &=  \alpha w^{H}A_Y w+(1-\alpha)v^{H} A_Y v,
\end{align*}
which shows that 
\begin{equation}\label{eqn:cond5aux}
\alpha\begin{bmatrix}
w^{H}A_Yw\\
w^{H}A_1w\\
\vdots\\
w^{H}A_{k}w
\end{bmatrix}+(1-\alpha)\begin{bmatrix}
v^{H}A_Yv\\
v^{H}A_{1}v\\
\vdots\\
v^{H}A_{k}v
\end{bmatrix}=\begin{bmatrix}
\varrho \\
0\\
\vdots\\
0
\end{bmatrix},
\end{equation}
i.e., the condition~\eqref{eqn:cond5} holds.

On the other hand, let \eqref{eqn:cond5aux} hold for some unit Euclidean norm vectors $v,w\in\F^n$ and a scalar $\alpha\in [0,1]$. Since $A_*\in\mathrm{span}\{A_1,\dots,A_k\}$, the last $k$ entries in this vector equation yield
\[
\alpha w^{H}A_{*}w+(1-\alpha)v^{H}A_{*}v=0.
\]
Using this in the first entry of the above vector equation \eqref{eqn:cond5aux} leads to
%
\begin{align*}
\varrho & =  \alpha w^{H}A_Yw+(1-\alpha)v^{H}A_Yv\\
& =  \alpha w^{H}(A_Y-A_*)w+(1-\alpha)v^{H}(A_Y-A_*)v\\
 & =  \alpha w^{H}\left(Y-X_{*}\right)^{H}\left(Y-X_{*}\right)w+(1-\alpha)v^{H}\left(Y-X_{*}\right)^{H}\left(Y-X_{*}\right)v.
\end{align*}
%
This shows that $v,w\in\Sigma_{Y-X_{*}}$, and hence $0\in\mathrm{cvx}\left( \mathscr{F}(A_1,\dots,A_k;\Sigma_{Y-X_{*}}) \right)$. 
\end{proof}

We next illustrate the characterization \eqref{eqn:cond5} in Theorem~\ref{thm:cond5} using several examples of known spectral approximations that have appeared in the previous literature.


\begin{example}\label{ex:singular}
Let $\X=\mathrm{span}\{X_1,\dots,X_k\}$ be any $k$-dimensional subspace of $\F^{n\times n}$, where each matrix $X\in\X$ statisfies $Xw=0$ for some fixed unit norm vector $w\in\F^n$. Thus, the matrices in $\X$ are singular and have a common eigenvector corresponding to the common eigenvalue zero. Let $Y\in\F^{n\times n}\setminus\X$ be any matrix that satisfies $Yw=\|Y\|_2w$, i.e., the vector $w$ is a maximal right singular vector of $Y$. Using our characterization in Theorem~\ref{thm:cond5} we want to show that $X_*=0\in\X$ is a spectral approximation of $Y$ from~$\X$. (This is easily seen by the fact that any $X\in\X$ satisfies $\|Y-X\|_2\geq \|(Y-X)w\|_2=\|Y\|_2$, with equality for $X=0$.) For $X_*=0$ and the matrices used in Theorem~\ref{thm:cond5} we obtain
%
$$\begin{bmatrix}
w^HA_Yw\\
w^{H}A_{1}w\\
\vdots\\
w^{H}A_{k}w
\end{bmatrix}=
\begin{bmatrix}
w^HY^HYw\\
w^{H}Y^HX_1w\\
\vdots\\
w^{H}Y^HX_kw
\end{bmatrix}=
\begin{bmatrix}
\|Y\|_2^2\\
0\\
\vdots\\
0
\end{bmatrix}=\varrho\, e_1\in\mathscr{F}(A_Y,A_1,\dots,A_k),$$
%
and hence the condition of Theorem~\ref{thm:cond5} is satisfied. A special case of this example is given by a singular matrix $A\in\F^{n\times n}$, and $X_i=A^i$ for $i=1,\dots,k$, where $k$ is less than the degree of the minimal polynomial of $A$. Then $Y=I\in\F^{n\times n}\setminus\X$,
and we can formulate the result just obtained in the form 
%
$$\min_{\substack{\mathrm{deg}(p)\leq k\\p(0)=1}}\|p(A)\|_2=1,$$
%
i.e., ideal GMRES (see \eqref{eqn:iG}) completely stagnates for a singular matrix $A$; cf.~\cite[Proposition 2.1]{FaJoKnMa1996}.
\end{example}

\begin{example}\label{ex:non-unique}
Consider a singular diagonal matrix 
%
$$A=\mathrm{diag}(0,\lambda_2,\dots,\lambda_n)\in\R^{n\times n},$$
%
where $\lambda_2,\dots,\lambda_{n}$ are nonzero and pairwise distinct, and the subspace $\X={\rm span}\{A,\dots,A^k\}\subset\R^{n\times n}$, where $1\leq k\leq n-1$. We already know from Example~\ref{ex:singular}, that in this case $X_*=0$ is a spectral approximation of $Y=I$ from~$\X$. As explained in~\cite[Remark~2.4]{LiTi2009} (for a more general problem), the spectral approximation in this case is not uniquely determined. Indeed, any matrix 
%
$$X_*=\sum_{j=1}^k\alpha_j A^j \equiv p(A)\in\X$$
%
that satisfies $|1-p(\lambda_i)|\leq 1$ for $i=2,\dots,n$ is a spectral approximation of $Y=I$ from~$\X$. In Figure~\ref{fig:kfield-plots} (top) we show the set $\mathscr{F}(A_Y,A_1,A_2)\subset\R^3$ for the matrix $A\in\R^{3,3}$ with $\lambda_2=1$, $\lambda_3=2$, $\X=\mathrm{span}\{A,A^2\}$, and $X_*=0.2\,A+0.3\,A^2$, which yields $\varrho=\|Y-X_*\|_2^2=1$. The location of the vector $e_1\in\R^3$ is marked by a big (red) dot. We generated all plots of $\mathscr{F}(A_Y,A_1,A_2)\subset\R^3$ in Figure~\ref{fig:kfield-plots} in MATLAB R2024b using the function \texttt{sphere} for obtaining unit norm vectors $v\in\R^3$, and the function \texttt{surf} for plotting the corresponding vectors $[v^TA_Yv,\,v^TA_1v,\,v^TA_2v]^T\in\R^3$. 
\end{example}

\begin{example}\label{ex:jordan}
Let $J_\lambda\in\F^{n\times n}$ be the $n\times n$ Jordan block with eigenvalue $\lambda$. We consider the $k$-dimensional subspace $\X=\mathrm{span}\{I,J_\lambda,\dots,J_\lambda^{k-1}\}\subset \F^{n\times n}$, and $Y=J_\lambda^{k}$, where $1\leq k\leq n-1$. It was shown in~\cite[Theorem~3.4] {LiTi2009} that
%
$$X_*=J_\lambda^k-(J_\lambda-\lambda I)^k=Y-J_0^k$$ 
%
is a spectral approximation of $Y$ from~$\X$. In the notation of Theorem~\ref{thm:cond5} we have $Y-X_*=J_0^k$, hence $\varrho=\|Y-X_*\|_2^2=1$. For the vector $v=e_{k+1}$ we obtain $v^H(Y-X_*)^H=(J_0^ke_{k+1})^T=e_1^T$. Therefore,
$$\begin{bmatrix}
v^HA_Yv\\
v^{H}A_{1}v\\
\vdots\\
v^{H}A_{k}v
\end{bmatrix}=
\begin{bmatrix}
e_1^TJ_\lambda^{k}e_{k+1}\\
e_1^TJ_\lambda^{k-1}e_{k+1}\\
\vdots\\
e_1^Te_{k+1}
\end{bmatrix}= e_1\in\mathscr{F}(A_Y,A_1,\dots,A_k),$$
%
and hence the condition of Theorem~\ref{thm:cond5} is satisfied. In Figure~\ref{fig:kfield-plots} (middle) we show the set $\mathscr{F}(A_Y,A_1,A_2)\subset\R^3$ for the matrix $J_1\in\R^{3,3}$, and again the location of the vector $e_1\in\R^3$ is marked by a big (red) dot.
\end{example}

\begin{example}\label{ex:LauRhia}
Lau and Riha~\cite[pp.~119--120]{LaRi1981} gave a numerical example for a spectral approximation of the symmetric matrix 
%
$$Y=\begin{bmatrix}
0.67 & -0.13 & 0.27\\ -0.13 & 0.49 & 0.33\\ 0.27 & 0.33 & 0.63\end{bmatrix}\in\R^{3\times 3}$$
%
from the subspace $\X={\mathrm span}\{X_1,X_2\}\subset\R^{3,3}$, where
%
$$X_1 = \begin{bmatrix} 0.13 & 0.04 & -0.06\\ 0.04 & 0.44 & 0.21\\  -0.06 & 0.21 & 0.39\end{bmatrix},\quad
X_2 = \begin{bmatrix}0.22 & -0.09 & -0.11\\ -0.09 & 0.35 & 0.18\\ -0.11 & 0.18 & 0.51\end{bmatrix}.$$
According to our computation using the CVX software and the MATLAB function {\tt bestmat}, a spectral approximation of $Y$ is given by 
%
$$X_*=0.270019\,X_1+1.587964\,X_2,$$
%
where the coefficients are rounded to six decimal places. (In~\cite{LaRi1981} the coefficients rounded to six decimal places are $0.270020$ and $1.587963$.) Using MATLAB's {\tt norm} function we compute $\varrho=\|Y-X_*\|_2^2\approx 0.294068$.  In Figure~\ref{fig:kfield-plots} (bottom) we show the corresponding set $\mathscr{F}(A_Y,A_1,A_2)\subset\R^3$. The location of the vector $\varrho\, e_1\in\R^3$, again marked by a big (red) dot, numerically confirms that $\varrho\, e_1\in \mathscr{F}(A_Y,A_1,A_2)$.
\end{example}


