Note that $\lim \inf_{n \to \infty} T_n= \infty$ (and thus $T_n \to \infty$), since $U \in \RR_+$ and $a_n \to \infty$. Furthermore, $\lim_{n \to \infty} T_n/a_n= U$ and then 
applying Lemma~\ref{lem:frechet-technical-2} together with inequality  \eqref{ineq:apx} we obtain that
\[\apx_k(F) \ge  \frac{\Gamma(k)}{\Gamma(k+1-1/\alpha)} U \exp(- U^{-\alpha}) \sum_{j=1}^k \sum_{s=j}^{\infty} \frac{U^{-s \alpha}}{s!}.\]

Given that the inequality above holds for every positive real number $U$, we have 
\[\apx_k(F) \ge  \frac{\Gamma(k)}{\Gamma(k+1-1/\alpha)} \max_{U \in \RR_+} U \exp(- U^{-\alpha}) \sum_{j=1}^k \sum_{s=j}^{\infty} \frac{U^{-s \alpha}}{s!}= \varphi_k (\alpha).\] 

In the rest of the proof we show that, for each positive real number $k$ and each $\alpha \in (1, \infty)$, $\varphi_k(\alpha)$ is lower bounded by $ 1-1/\sqrt{2k \pi}.$ 
To this end, we just need to evaluate the objective function of our optimization problem in a well chosen value.
An inequality for the Gamma function due to Gautschi~\cite{gautschi} states that for every $s \in (0,1)$ and every $x \ge 1$ we have $\Gamma(x+1)>x^{1-s}\cdot \Gamma(x+s)$.
Then, setting $x=k$ and $s=1-1/\alpha$ yields $\Gamma(k+1)>k^{1/\alpha} \Gamma(k+1-1/\alpha).$
Since $\Gamma(k)=\Gamma(k+1)/k$, we therefore obtain
$ k^{1-1/\alpha}>\Gamma(k+1-1/\alpha)/\Gamma(k).$
On the other hand, note that for each $U \in (0, \infty)$ we have 
\begin{eqnarray*}
	U \exp(-U^{-\alpha})\sum_{j=1}^k\sum_{s=j}^\infty \frac{U^{-s \alpha}}{s!} 
	&=& U \exp(-U^{-\alpha})\left( \sum_{s=1}^k \frac{s\cdot  U^{-s \alpha}}{s!}+ k \sum_{s=k+1}^\infty \frac{U^{-s\alpha}}{s!}\right) \\
	&=&U \exp(-U^{-\alpha})\left( U^{-\alpha} \sum_{s=0}^{k-1} \frac{U^{-s \alpha}}{s!}+ k \sum_{s=k+1}^\infty \frac{U^{-s\alpha}}{s!}\right).
\end{eqnarray*}
In particular, by taking $U_{k,\alpha}=k^{-1/\alpha}$ we get that
{\small \begin{eqnarray*}
	\varphi_k(\alpha)\cdot \frac{\Gamma(k+1-1/\alpha)}{\Gamma(k)} &\ge& U_{k,\alpha}\cdot  k \exp(-U_{k,\alpha}^{-\alpha}) \left(\sum_{s=0}^{k-1} \frac{U_{k,\alpha}^{-s \alpha}}{s!}+ \sum_{s=k+1}^\infty \frac{U_{k,\alpha}^{-s\alpha}}{s!}\right) \\
	&=&  U_{k,\alpha}\cdot  k \exp(-U_{k,\alpha}^{-\alpha}) \left(\exp(U_{k,\alpha}^{-\alpha})- \frac{U_{k,\alpha}^{-\alpha k}}{k!}\right) \\
	&= & k^{1-1/\alpha} \left( 1- \frac{e^{-k}k^k}{k!}\right)\ge \frac{\Gamma(k+1-1/\alpha)}{\Gamma(k)}\left(1- \frac{1}{\sqrt{2 \pi k}} \right),
\end{eqnarray*}}
where the first inequality follows since the value of $\varphi_k(\alpha)$ involves the maximum over $(0,\infty)$, the first equality from the Taylor series for the exponential function and the last inequality is obtained by applying Stirling's approximation inequality.
This concludes the proof of the theorem.
\end{proof}

Below, we show a result that we need to prove Lemma~\ref{lem:frechet-technical-2}.
\begin{lemma}
	\label{lem:fre-integral}
	Let $F$ be a distribution with extreme type distribution Fr\'echet of parameter $\alpha\in (1,\infty)$ and let $\{T_n\}_{n\in \NN}$ be a sequence of real values such that $T_n\to \infty$.
	Then, we have that
	\begin{equation*}
		\lim_{n\to \infty}\frac{\EE(X|X> T_n)}{T_n}= \frac{\alpha}{\alpha-1}.
	\end{equation*}
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lem:fre-integral}
]
	To prove the lemma, recall the classic dominated convergence theorem: Suppose that $\{ f_n\}_{n\in \NN}$ is a sequence of measurable functions such that $f_n \to f$ pointwise almost everywhere as $n \to \infty$. 
	If there exists an integrable function $g$ satisfying $|f_n|\leq g$ for every positive integer $n$, then f is also integrable and $\int f \mathrm du= \lim_{n \to \infty} \int f_n \mathrm du.$
	We first observe that by expanding the conditional expectation we get that 
	\[\frac{\EE(X|X> T_n)}{T_n}=1+\frac{1}{T_n(1-F(T_n))}\int_{T_n}^{\infty}(1-F(s))\mathrm ds\]
	for every positive integer $n$.
	By Lemma~\ref{lem:fre-key}, there exists a slowly varying function $\ell_F$ such that $1-F(t)=t^{-\alpha}\ell_F(t)$ for every $t\in \RR_+$.
	Therefore, 
	\begin{align*}
		\frac{1}{T_n(1-F(T_n))}\int_{T_n}^{\infty}(1-F(s))\mathrm ds&=\frac{1}{T_n\cdot T_n^{-\alpha}\cdot \ell_F(T_n)}\int_{T_n}^{\infty}s^{-\alpha}\ell_F(s)\mathrm ds \\
		&=\frac{1}{T_n^{1-\alpha}}\int_{T_n}^{\infty}s^{-\alpha}\frac{\ell_F(s)}{\ell_F(T_n)}\mathrm ds.
	\end{align*}
	We perform a change of variables in the integral by setting $s=u\cdot T_n$.
	Then, we obtain that the integral above is equal to
{\small	\begin{align*}
		\frac{1}{T_n^{1-\alpha}}\int_{T_n}^{\infty}s^{-\alpha}\frac{\ell_F(s)}{\ell_F(T_n)}\mathrm ds&=\frac{1}{T_n^{1-\alpha}}\int_{1}^{\infty}u^{-\alpha}T_n^{-\alpha}\frac{\ell_F(uT_n)}{\ell_F(T_n)} \cdot T_n\mathrm du=\int_{1}^{\infty}u^{-\alpha}\frac{\ell_F(uT_n)}{\ell_F(T_n)}\mathrm du.
	\end{align*}}
	Since the function $\ell_F$ is slowly varying and $T_n\to \infty$ we have that for every $u\in [1,\infty)$ it holds  $u^{-\alpha}\ell_F(uT_n)/\ell_F(T_n)\to u^{-\alpha},$
	when $n\to \infty$.
	Furthermore, for every $\alpha\in (1,\infty)$ the function $u^{-\alpha}$ is integrable in $(1,\infty)$ and thus by the dominated convergence theorem we have that 
	\begin{equation*}
		\lim_{n\to \infty}\int_{1}^{\infty}u^{-\alpha}\frac{\ell_F(uT_n)}{\ell_F(T_n)}\mathrm du = \int_{1}^{\infty}u^{-\alpha}\mathrm du=\frac{1}{\alpha-1},
	\end{equation*}
	which finishes the proof of the lemma.	
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem:frechet-technical-2}]
%We start by proving \ref{lem:frechet-limit}.
	First, recall the following fact: If we have a sequence of probability distributions $\{G_n\}_{n\in \NN}$ such that $G_n$ converges point-wise to a probability distribution $G$, then $G_n(z_n)\to G(z)$ when $z_n\to z$.
	Consider a positive sequence $\{T_n\}_{n\in \NN}$ such that the following holds: $T_n\to \infty$ and there exists $U\in \RR_+$ such that $T_n/a_n\to U$.
	Since $F$ has extreme type distribution Fr\'echet of parameter $\alpha$, by Theorem~\ref{thm:leadbetter} we have that  
	 \begin{eqnarray*}
		\lim_{n \to \infty} \PP(M_n^{j}/a_n \le T_n/a_n) 
		&=&  \exp(-U^{-\alpha})\sum_{s=0}^{j-1} \frac{(-\log(\exp(-U^{-\alpha})))^s}{s!} \\
		&=& \exp(-U^{-\alpha})\sum_{s=0}^{j-1} \frac{U^{-\alpha s}}{s!},
	\end{eqnarray*}
	and therefore
	\[
	\lim_{n \to \infty} \sum_{j=1}^{k} \PP(M_n^{j}>T_n)=\exp(-U^{-\alpha})\sum_{j=1}^k\sum_{s=j}^{\infty} \frac{U^{-\alpha s}}{s!},
	\]
	where the equality follows since $\sum_{s=0}^{\infty} U^{-\alpha s}/s!=\exp(U^{-\alpha})$. 
	In the remainder of the proof, we analyze the limit of $T_n/\sum_{j=1}^k\EE(M_n^j)$ when $n\to \infty$, which is equivalent to analyzing the sequence $(T_n/a_n)/\sum_{j=1}^k \EE(M_n^j/a_n)$.
	To this end, we first note that $\{M_n^j/a_n \}_{n\in \NN}$ converges not only in distribution but also in expectation to a random variable distributed according to 
	\[G_j(t)=H(t) \sum_{s=0}^{j-1} \frac{(-\log H(t))^s}{s!},\] 
	with $H(t)=\exp(-t^{-\alpha})$. 
	More specifically, $\lim_{n \to \infty} \EE(M_n^j/a_n)= \EE(Z_j)$
	where $Z_j$ is distributed according to  $G_j.$ 
	This follows from a result on the convergence of moments in extreme value theory~\cite[p. 77, Proposition 2.1]{libroextremo}.
	Furthermore, 
	\begin{align*}
		\EE(Z_j)&=\int_{0}^\infty t \;\mathrm{d}G_j(t) \\
		&= \int_{0}^\infty \exp(-t^{-\alpha})\cdot \alpha \sum_{s=0}^{j-1} \frac{t^{-\alpha(s+1)}}{s!} \mathrm{d}t - \int_{0}^\infty \exp(-t^{-\alpha}) \cdot \alpha \sum_{s=1}^{j-1} \frac{t^{-\alpha s}}{(s-1)!} \mathrm{d}t \\
		&= \int_{0}^\infty \alpha \exp(-t^{-\alpha}) \frac{t^{-\alpha j}}{(j-1)!} \mathrm{d}t\\ 
		&= \frac{1}{\Gamma(j)}  \int_{0}^\infty \alpha \exp(-t^{-\alpha}) \cdot t^{-\alpha j} \mathrm{d}t \\
%		&= \frac{1}{\Gamma(j)}\int_{\infty}^0 \exp(-x) x^j (-x^{-(1+1/\alpha)}) \mathrm{d}x\\
&= \frac{1}{\Gamma(j)}\int_{0}^\infty e^{-x}  x^{j-1-1/\alpha} \mathrm{d}x = \frac{\Gamma(j-1/\alpha)}{\Gamma(j)},
	\end{align*}
	where the fourth equality holds because for every natural number $\Gamma(x)=(x-1)!,$ the fifth by performing the change of variables $x=t^{-\alpha}$ and the last one follows from the definition of the Gamma function.
	\begin{claim} \label{claim:sum:gamma}
		For every positive integer $k$ and real value $\alpha>1$, it holds that
		\begin{equation}\label{eq:sum:gammas}
			\sum_{j=1}^k \frac{\Gamma(j-1/\alpha)}{\Gamma(j)}=\frac{\alpha}{\alpha-1} \cdot \frac{\Gamma(k+1-1/\alpha)}{\Gamma(k)}. 
		\end{equation}
	\end{claim}	
    \begin{proof}
    We prove the claim by induction on $k$. 
    Note that when $k=1$ the claim follows directly by observing that $\Gamma(2-1/\alpha)=(1-1/\alpha)\cdot \Gamma(1-1/\alpha)$.
    When $k>1$, by manipulating the left hand side of  \eqref{eq:sum:gammas} we obtain 
	\begin{align*}
		\sum_{j=1}^k \frac{\Gamma(j-1/\alpha)}{\Gamma(j)}&= \sum_{j=1}^{k-1} \frac{\Gamma(j-1/\alpha)}{\Gamma(j)}+ \frac{\Gamma(k-1/\alpha)}{\Gamma(k)}\\
		&=\frac{1}{1-1/\alpha} \cdot \frac{\Gamma(k-1/\alpha)}{\Gamma(k-1)}+  \frac{\Gamma(k-1/\alpha)}{\Gamma(k)} \\
		%&=\frac{k-1}{1-1/\alpha} \cdot \frac{\Gamma(k-1/\alpha)}{\Gamma(k)}+  \frac{\Gamma(k-1/\alpha)}{\Gamma(k)}\\
		&= \frac{\Gamma(k-1/\alpha)}{\Gamma(k)} \left( \frac{k-1}{1-1/\alpha}+1\right)\\
		&= \frac{\Gamma(k-1/\alpha)}{\Gamma(k)} \cdot  \frac{k-1/\alpha}{1-1/\alpha} =  \frac{\alpha}{\alpha-1} \cdot \frac{\Gamma(k+1-1/\alpha)}{\Gamma(k)},
	\end{align*}
	where the second equality follows by applying the induction hypothesis and the third and the last equalities follow from the identity $\Gamma(x)\cdot x=\Gamma(x+1)$ for $x=k-1$ and $x=k-1/\alpha$, respectively.
    \end{proof}
	Using the above claim, along with the fact that $T-n/a_n \to U$ as $n$ goes to infinity, we have that 
	\[\lim_{n\to \infty}\frac{T_n/a_n}{\sum_{j=1}^k \EE(M_n^j/a_n)}= U\cdot \frac{\alpha-1}{\alpha} \cdot \frac{\Gamma(k)}{\Gamma(k+1-1/\alpha)}\]
	when $n\to \infty$.
	Thus, combining the above with Lemma~\ref{lem:fre-integral}, we get that 
	\begin{align*}
	&\EE \left(X \vert X > T_n\right)\frac{\sum_{j=1}^{k} \PP(M_n^{j}>T_n)}{\sum_{j=1}^k \EE(M_n^{j})}\\
	&=\frac{\EE \left(X \vert X > T_n\right)}{T_n}\cdot \frac{T_n/a_n}{\sum_{j=1}^k \EE(M_n^j/a_n)}\cdot \sum_{j=1}^{k} \PP(M_n^{j}>T_n)\\
	&\to \frac{\alpha}{\alpha-1}\cdot U\cdot \frac{\alpha-1}{\alpha} \cdot \frac{\Gamma(k)}{\Gamma(k+1-1/\alpha)}\exp(-U^{-\alpha}) \sum_{j=1}^k \sum_{s=j}^{\infty} \frac{U^{-s \alpha}}{s!}\\
	&=\frac{\Gamma(k)}{\Gamma(k+1-1/\alpha)} U \exp(-U^{-\alpha}) \sum_{j=1}^k \sum_{s=j}^{\infty} \frac{U^{-s \alpha}}{s!},
	\end{align*}
	when $n\to \infty$.
