\begin{lemma}
	\label{lem:mises-to-gumbel}
	Let $F$ be a distribution with extreme type in the Gumbel family such that $\omega_1(F)=\infty$ and let $(V,\eta)$ be a Von Mises representation of $F$ such that $\lim_{t\to \infty}\eta(t)=\eta^{\star}$.
	Let $\{a_n\}_{n\in\NN}$ and $\{b_n\}_{n\in\NN}$ be scaling and shifting sequences, respectively, for $V$.
	For every positive integer $n$ consider $b_n^{\eta}=b_n+a_n\log \eta^{\star}$.
	Then, the following holds:
	\begin{enumerate}[label=\normalfont(\roman*)]
%		\item For every $t\in \RR_+$ we have that $\PP\left(M_n-b_n\le a_n\cdot t\right)=\exp(- \eta^{\star} e^{-t})$.\label{limite-gumbel}
		\item $\{a_n\}_{n\in\NN}$ and $\{b_n^{\eta}\}_{n\in\NN}$ are scaling and shifting sequences, respectively, for $F$.\label{sequences-gumbel}
		\item For every $U\in \RR$ we have $\lim_{n\to \infty}(a_nU+b_n^{\eta})= \infty$. \label{limit-between}
		\item For every $U\in \RR$ and every positive integer $k$ we have that $\lim_{n\to \infty}(a_nU+b_n^{\eta})/\sum_{j=1}^k \EE(M_n^{j})=1/k$,
where $M_n^1,\ldots,M_n^n$ are the order statistics for $F$. \label{lem:gumbel-k-second}
	\end{enumerate}
\end{lemma}
\begin{proof}
	To prove the first point we start by checking that for every $t$ we have $\PP\left(M_n-b_n\le a_n\cdot t\right)=F^n(a_nt+b_n)\to \exp(- \eta^{\star} e^{-t})$. 
%	$F^n(a_nt+b_n)\to \exp(-\eta^{\star} e^{-t})$ when $n\to \infty$.
	For every positive integer $n$, let $\eta_n=\eta(a_nt+b_n)$ and $d_n=V(a_nt+b_n)$.
	Observe that, by Lemma~\ref{prop:Gumbel-prop}, $F^n(a_nt+b_n)=\left(1-\eta_n(1-d_n)n\cdot \frac{1}{n}\right)^n,$
	and therefore, it is enough to check that $\eta_n(1-d_n)n\to \eta^{\star} e^{-t}$.
	Recall that by Lemma~\ref{lem:von-mises-prop} we have that $a_n=\aux(b_n)$, where $\mu$ is the auxiliary function of $V$ and $b_n=\inf\{y\in \RR:V(y)\ge 1-1/n\}\to \infty$ (since $\omega_1(V)=\infty$).
	Therefore, we have that $a_nt+b_n=\mu(b_n)t+b_n\to \infty$, where the limit holds by Lemma~\ref{lem:von-mises-prop} for $x = t$ and $t = b_n$, since $b_n\to \infty$.  
	Furthermore, since $d_n \to 1$, we have  $\lim_{x\to 1}(1-x)^{-1}\log(1/x)=1$ and therefore $\lim_{n\to \infty}n(1-d_n)=\lim_{n\to \infty}n\log(1/d_n)=e^{-t}$, since $d_n^n\to \exp(-e^{-t})$. Thus, for every $t > 0$, we have $\lim_{n \to \infty} \eta_n(1 - d_n) n = \eta^{\star} e^{-t}$
%	That concludes \ref{limite-gumbel}.
	On the other hand, from the definition of the sequences, we have
	\begin{align*}
		\PP\left(M_n-b_n^{\eta}\le a_n\cdot t\right)&=\PP\left(M_n-b_n-a_n\log \eta^{\star}\le a_n\cdot t\right)\\
		&=\PP\left(M_n-b_n\le a_n(t+\log \eta^{\star})\right)\\ 
		&\to \exp\Big(- \eta^{\star} e^{-(t+\log \eta^{\star})}\Big)=\exp(-e^{-t}),
	\end{align*}
	which is the Gumbel distribution and that concludes \ref{sequences-gumbel}.
	To prove \ref{limit-between},
	note that for every $U$, we have that $a_nU+b_n^{\eta}=a_nU+b_n+a_n\log \eta^{\star}=\mu(b_n)(U+\log\eta^{\star})+b_n\to \infty$,  
where this limit holds since $b_n\to \infty$ and by Lemma~\ref{lem:von-mises-prop}. 

We now prove part \ref{lem:gumbel-k-second}.
We show that for every $j\in \{1,\ldots,k\}$ we have that $\EE(M_n^j/(a_nU+b_n^{\eta}))\to 1$ when $n\to \infty$.
By part \ref{sequences-gumbel} we have that $\{a_n\}_{n\in\NN}$ and $\{b_n^{\eta}\}_{n\in\NN}$ are scaling and shifting sequences, respectively, for $F$.
We first note that $\{(M_n^j-b^{\eta}_n)/a_n \}_{n\in \NN}$ converges not only in distribution but also in expectation to a random variable distributed according to 
\[G_j(t)=H(t) \sum_{s=0}^{j-1} \frac{(-\log H(t))^s}{s!},\] 
with $H(t)=\exp(- e^{-t})$. 
More specifically, $\lim_{n \to \infty} \EE((M_n^j-b^{\eta}_n)/a_n)= \EE(Z_j)$
where $Z_j$ is distributed according to  $G_j$.
This follows from a result on the convergence of moments in extreme value theory~\cite[Proposition 2.1, p. 77]{libroextremo}.
Furthermore, we have $\EE(Z_j)\le \EE(Z_1)<\infty$. 
We claim that $b^{\eta}_n/a_n\to \infty$.
Since $\omega_1(V)=\infty$ we have that $b_n=\inf\left\{t\in \RR:V(t)\ge 1-1/n\right\}\to \infty$ when $n\to \infty$.
Therefore, by Lemma~\ref{lem:von-mises-prop} it follows that
$b_n/a_n=b_n/\aux(b_n)\to \infty$ when $n\to \infty$, where $\mu$ is the auxiliary function of $V$, and therefore $b^{\eta}_n/a_n=b_n/\mu(b_n)+\log(\eta^{\star})\to \infty$, where the limit holds since $b_n/\mu(b_n)\to \infty$ by Lemma~\ref{lem:von-mises-prop} and the fact that $b_n\to \infty$. 
\begin{claim}
\label{claim:seq-limit}
Suppose we have three positive sequences of real values $\{z_n\}_{n\in \NN}$, $\{w_n\}_{n\in \NN}$ and $\{v_n\}_{n\in \NN}$ such that $(z_n-w_n)/v_n\to L<\infty$ and $w_n/v_n\to \infty$. 
Then, $z_n/v_n\to \infty$ and $z_n/w_n\to 1$.
\end{claim}
\begin{proof}
For every $M\ge L-1$, there exists a positive integer $n_0$ such that for every $n\ge n_0$ the following inequalities hold: $w_n>(M-L+1)v_n$ and $z_n-w_n>(L-1)v_n$.
Therefore, for every $n\ge n_0$ we have that $z_n>(M-L+1)v_n+(L-1)v_n=Mv_n$ and thus we conclude that $z_n/v_n\to \infty$.
For the other one, observe that there exists $n_1$ such that for every $n\ge n_1$ we have that $(L/2)v_n<z_n-w_n<(3L/2)v_n$.
Therefore, for every $n\ge n_1$ we have that $(L/2)\frac{v_n}{w_n}<z_n/w_n-1<(3L/2)\frac{v_n}{w_n}$ and since $v_n/w_n\to 0$ we conclude that $z_n/w_n\to 1$.
\end{proof}
Using Claim \ref{claim:seq-limit} with $z_n=\EE(M^j_n)$, $w_n=b^{\eta}_n$ and $v_n=a_n$ we conclude that $\EE(M^j_n)/a_n\to \infty$ and $\EE(M^j_n)/b^{\eta}_n\to 1$.
Then, we have that $U\cdot a_n/\EE(M^j_n)+b^{\eta}_n/\EE(M^j_n) \to 1$ for every $U\in \RR$.
\end{proof}

\begin{lemma}
	\label{lem:gumbel-first-term}
	Let $F$ be a distribution with extreme type in the Gumbel family and let $\{\Theta_n\}_{n\in \NN}$ be a sequence of real values such that $\Theta_n\to \infty$.
	Then, we have $\lim_{n\to \infty}\EE(X|X>\Theta_n)/\Theta_n=1$, where $X$ is distributed according to $F$.
%	\[\lim_{n\to \infty}\frac{1}{\Theta_n(1-F(\Theta_n))}\int_{\Theta_n}^{\infty}(1-F(s))\mathrm ds= 0.\]
\end{lemma}
\begin{proof}
	Let $(V,\eta)$ be a Von Mises representation of $F$ such that $\lim_{t\to \infty}\eta(t)=\eta^{\star}$, guaranteed by Lemma \ref{prop:Gumbel-prop}.
	First observe that when $X$ is distributed according to $F$, we have that 
	\[\frac{\EE(X|X>\Theta_n)}{\Theta_n}=1+\frac{1}{\Theta_n(1-F(\Theta_n))}\int_{\Theta_n}^{\infty}(1-F(s))\mathrm ds.\]
	Let $n_0$ be a sufficiently large positive integer such that $\Theta_n>0$ for every $n\ge n_0$.
	Then, for every $n\ge n_0$ and from the Von Mises representation we obtain that
	\begin{align*}
		\frac{1}{\Theta_n(1-F(\Theta_n))}\int_{\Theta_n}^{\infty}(1-F(s))\mathrm ds &= \int_{\Theta_n}^{\infty}\frac{\eta(s)}{\eta(\Theta_n)}\cdot \frac{1-V(s)}{\Theta_n(1-V(\Theta_n))}\mathrm ds \\
		&=\int_{1}^{\infty}\frac{\eta(\omega \Theta_n)}{\eta(\Theta_n)}\cdot \frac{1-V(\omega \Theta_n)}{1-V(\Theta_n)}\mathrm d\omega,
	\end{align*} 
	where the last equality comes by performing a change of variables.
	\begin{claim}\label{clm:tail-equiv-von-mises}
		For every $\omega\in (1,\infty)$ we have that $\displaystyle \frac{1-V(\omega\Theta_n)}{1-V(\Theta_n)}\to 0.$
	\end{claim}
    \begin{proof}
    Since $V$ is a Von Mises function, there exists an auxiliary function $\mu$ and a $z_0 \in \R$ such that 
	\[
	\frac{1-V(\omega\Theta_n)}{1-V(\Theta_n)}=
	\exp\left(- \int\limits_{z_0}^{\omega \Theta_n} \frac{1}{\aux(s)}\mathrm  ds  \right) 
	\exp\left(  \;\int\limits_{z_0}^{\Theta_n} \frac{1}{\aux(s)}\mathrm  ds \right) 
	=\exp\left(  -\int\limits_{\Theta_n}^{\omega \Theta_n} \frac{1}{\aux(s)}\mathrm  ds \right)
	\]
	To complete the proof it is sufficient to show that the integral above goes to $\infty$ when $n\to \infty$.
	By changing variables we have that
	\[
	\int\limits_{\Theta_n}^{\omega \Theta_n} \frac{1}{\aux(s)}\mathrm  ds = \int\limits_1^\omega \frac{\Theta_n}{\aux(y\Theta_n)} \mathrm d y.
	\]
	Since $\Theta_n\to \infty$, for every $y\in (1,\omega)$ we have that
	\begin{equation*}
		\lim_{n\to \infty}\frac{\Theta_n}{\aux(y \Theta_n)}=\frac{y \Theta_n}{\aux(y \Theta_n)}\cdot \frac{1}{y}= \infty,
	\end{equation*}
	where the limit holds thanks to Lemma~\ref{lem:von-mises-prop}. 
	We therefore conclude that  
	\begin{equation*}
		\lim_{n\to \infty}\frac{1-V(\omega\Theta_n)}{1-V(\Theta_n)}=\lim_{n\to \infty}\exp\left( -\int\limits_1^\omega \frac{\Theta_n}{\aux(y \Theta_n)} \mathrm d y \right)= 0.\qedhere
	\end{equation*}
    \end{proof}
	We conclude the proof of the lemma, using Claim~\ref{clm:tail-equiv-von-mises}.
	Since $\Theta_n\to \infty$, we have that $\eta(\Theta_n)\to \eta^{\star}$ and $\eta(\omega \Theta_n)\to \eta^{\star}$ for every $\omega\in (1,\infty)$.
	Therefore, we have that 
	\[\lim_{n\to \infty}\frac{\eta(\omega \Theta_n)}{\eta(\Theta_n)}\cdot \frac{1-V(\omega \Theta_n)}{1-V(\Theta_n)}= \frac{\eta^{\star}}{\eta^{\star}}\cdot 0=0,\]
	and thanks to the dominated convergence theorem this implies that
	\[
	\frac{1}{\Theta_n(1-F(\Theta_n))}\int_{\Theta_n}^{\infty}(1-F(s))\mathrm ds =\int_{1}^{\infty}\frac{\eta(\omega \Theta_n)}{\eta(\Theta_n)}\cdot \frac{1-V(\omega \Theta_n)}{1-V(\Theta_n)}\mathrm d\omega \to 0.\qedhere
	\]
\end{proof}

We are now ready to prove Theorem~\ref{thm:apx:multi}\ref{multiple-Gumbel} for the Gumbel family.

\begin{proof}[Proof of Theorem \ref{thm:apx:multi}\ref{multiple-Gumbel} for the Gumbel family]
Let $F$ be a distribution with extreme type in the Gumbel family such that $\omega_1(F)=\infty$. 
Consider a Von Mises pair $(V,\eta)$ that represents $F$ with $\lim_{t\to \infty}\eta(t)=\eta^{\star}>0$, guaranteed to exist by Lemma \ref{prop:Gumbel-prop}.
Let $\{a_n\}_{n\in\NN}$ and $\{b_n\}_{n\in\NN}$ be scaling and shifting sequences, respectively, for $V$.
For every positive integer $n$ consider $b_n^{\eta}=b_n+a_n\log \eta^{\star}$.
By Proposition~\ref{prop:numerator-multi}, we can lower bound the value of $\apx_k(F)$ by 
\begin{equation}\label{eq:gumbel-apx-program}
\sup_{U\in \RR}\liminf_{n\to \infty} \frac{\EE \left(X \vert X > a_nU+b_n^{\eta} \right)}{a_nU+b_n^{\eta}} \cdot \frac{a_nU+b_n^{\eta}}{\sum_{j=1}^k \EE(M_n^{j})}\cdot \sum_{j=1}^{k} \PP(M_n^{j}>a_nU+b_n^{\eta}).
\end{equation}
Our threshold $T_n$ will be defined as $T_n = a_n U + b_n^{\eta}$, where $U$ is the optimal solution to \eqref{eq:gumbel-apx-program}.
By Lemma~\ref{lem:mises-to-gumbel}\ref{limit-between}, we have  $a_nU+b_n^{\eta}\to \infty$ for every $U$ when $n\to \infty$, and therefore from Lemma~\ref{lem:gumbel-first-term} we obtain
\[\lim_{n\to \infty}\frac{\EE \left(X \vert X > a_nU+b_n^{\eta} \right)}{a_nU+b_n^{\eta}}=1
%\lim_{n\to \infty}\left(1+\frac{1}{(a_nU+b_n^{\eta})(1-F(a_nU+b_n^{\eta}))}\int_{a_nU+b_n^{\eta}}^{\infty}(1-F(s))\mathrm ds\right)= 1
,\]
for every $U$.
Furthermore, Lemma~\ref{lem:mises-to-gumbel}\ref{lem:gumbel-k-second} implies that for every $U$ and every positive integer $k$ it holds $(a_nU+b_n^{\eta})/\sum_{j=1}^k \EE(M_n^{j})\to 1/k$.
We conclude that for every $U$ 
\[\lim_{n\to \infty} \frac{\EE \left(X \vert X > a_nU+b_n^{\eta} \right)}{a_nU+b_n^{\eta}} \cdot \frac{a_nU+b_n^{\eta}}{\sum_{j=1}^k \EE(M_n^{j})}=\frac{1}{k}.\]
By Lemma \ref{lem:mises-to-gumbel}\ref{sequences-gumbel}, $\{a_n\}_{n\in\NN}$ and $\{b_n^{\eta}\}_{n\in\NN}$ are scaling and shifting sequences, respectively, for $F$.
Therefore, by Theorem \ref{thm:leadbetter} we have 
\begin{align*}
\lim_{n\to \infty}\sum_{j=1}^{k} \PP(M_n^{j}>a_nU+b_n^{\eta})&= \lim_{n\to \infty}\sum_{j=1}^{k} \PP\left(\frac{M_n^{j}-b^{\eta}_n}{a_n}>U\right)\\
&=\sum_{j=1}^{k}\left(1-\exp\Big(- e^{-U}\Big)\sum_{s=0}^{j-1}\frac{ e^{-sU}}{s!}\right)\\
&=k-\exp\Big(-e^{-U}\Big)\sum_{j=1}^{k}\sum_{s=0}^{j-1}\frac{e^{-sU}}{s!},
\end{align*}
where the second equality follows from the fact that $F$ has extreme type Gumbel. Notice that the last term is non-negative for every $U$.
Furthermore, we get that 
\[\lim_{U\to \infty}\exp\Big(-e^{-U}\Big)\sum_{j=1}^{k}\sum_{s=0}^{j-1}\frac{ e^{-sU}}{s!}=\inf_{U\in \RR}\exp\Big(-e^{-U}\Big)\sum_{j=1}^{k}\sum_{s=0}^{j-1}\frac{ e^{-sU}}{s!}=0\]
since $\sum_{s=0}^{\infty}e^{-sU}/s!=\exp(-e^{-U})$.
We conclude that 
\[\sup_{U\in \RR}\lim_{n\to \infty} \frac{\EE \left(X \vert X > a_nU+b_n^{\eta} \right)}{a_nU+b_n^{\eta}} \cdot \frac{a_nU+b_n^{\eta}}{\sum_{j=1}^k \EE(M_n^{j})}\cdot \sum_{j=1}^{k} \PP(M_n^{j}>a_nU+b_n^{\eta})=\frac{1}{k}\cdot k=1,\]
and therefore $\apx_k(F)= 1$. 
That concludes the proof for the Gumbel family.
\end{proof}

