\begin{lemma}
\label{lem:frechet-eq}
Let $F$ be the Pareto distribution with parameter $\alpha=2$. Then, for every positive integer $k$ we have $\apx_k(F)=\varphi_k(2)$.
\end{lemma}
\begin{proof}

Consider a positive integer $k$ and let $T_n$ be an optimal solution of the problem \footnote{ Note that $T_n$ could be $\infty$ for some $n$.} 
\[
 \sup_{T \in \RR_+} \EE \left(X \vert X > T\right)\frac{\sum_{j=1}^{k} \PP(M_n^{j}>T)}{\sum_{j=1}^k \EE(M_n^{j})},
 \]
 and let $\{a_n\}_{n\in \NN}$ be the scaling sequence for $F$, which by Lemma~\ref{lem:fre-key} is equal to $a_n=\sqrt{n}$. 
 We will show that the sequence of positive real values $\{T_n/a_n\}_{n\in \NN}$ is bounded. Suppose this is not the case, that is, the sequence $\{T_n/a_n\}_{n \in \NN}$ is unbounded. 
 From the optimallity of $T_n$ together with equation \eqref{eqn:comp:ratio2:k}, we have  
 $\apx_k(F)=\liminf_{n\to \infty} A_n\cdot B_n$
 where 
 \begin{align*}
     A_n&=\frac{\EE \left(X \vert X > T_n\right)}{T_n}\cdot \frac{1}{\sum_{j=1}^k \EE(M_n^j/a_n)},\quad B_n=\sum_{j=1}^{k} \frac{T_n}{a_n} (1-G_{n,j}(T_n)),
 \end{align*}
and $G_{n,j}$ is the distribution of the $j$-th order statistic $M_n^j$.
 Notice that the sequence $\{A_n\}_{n\in \NN}$ converges to  $\Gamma(k)/\Gamma(k+1-1/2)$ when $n\to \infty$, thanks to Lemma~\ref{lem:fre-integral} together with the argument we have already seen in the proof of Lemma~\ref{lem:frechet-technical-2}. 
 On the other hand, for each $j \in \{ 1, \dots, k\}$, it holds that $1-G_{n,j}(T_n)$ is at most $1-G_{n,1}(T_n)=1-(1-1/T_n^2)^n$, by the definition of the CDF of the Pareto distribution with parameter $\alpha = 2$, and therefore 
 \[
 B_n \le \frac{T_n}{a_n} k \left( 1-\left(1-\frac{1}{T_n^2}\right)^n \right) \le \frac{T_n}{a_n} k \cdot \frac{n}{T^2_n} = k \frac{a_n}{T_n} \to 0,
 \]
where the second inequality follows using the Bernoulli's inequality, the fact that $a_n=\sqrt{n}$, and the limit holds since we are assuming that the sequence ${T_n/a_n}_{n\in \NN}$ is unbounded. 

 Therefore, putting all together we obtain that if the sequence $\{T_n/a_n \}_{n \in \NN}$ is unbounded, we get $\apx_k(F)=0$ for all positive integer $k$, which contradicts the optimality of the sequence $\{T_n\}_{n \in \NN}$. Then, the sequence $\{T_n/a_n\}_{n \in N}$ is bounded and therefore there exist a convergent subsequence, namely $\{U_n\}_{n \in \NN}$, and  $U \in \RR_+$ such that $\lim_{n \to \infty} U_n=U$.
Applying Lemma~\ref{lem:frechet-technical-2} to the sequence $\{U_n\}_{n \in \NN}$  we obtain that 
\[\apx_k(F)= \frac{\Gamma(k)}{\Gamma(k+1-1/2)} U \exp(- U^{-2}) \sum_{j=1}^k \sum_{s=j}^{\infty} \frac{U^{-s 2}}{s!}.\]
It remains to show that 
$U$ is a maximizer in the optimization problem \eqref{eq:phi-function} defining the value $\varphi_k(2)$.
By contradiction, suppose that there exist $\widetilde{U} \neq U$ such that 
\begin{equation}
\label{ineq:main:thm}
  \widetilde{U} \exp(-\widetilde{U}^{-2}) \sum_{j=1}^k \sum_{s=j}^{\infty} \frac{\widetilde{U}^{-s 2}}{s!} >  U \exp(-U^{-2}) \sum_{j=1}^k \sum_{s=j}^{\infty} \frac{U^{-s 2}}{s!}.   
\end{equation}
Consider the sequence $\{\widetilde{T}_n \}_{n\in \NN}$, where $\widetilde{T}_n=a_n \widetilde{U}$ for every positive integer $n$. Note that $\widetilde{T}_n \to \infty$ and $\widetilde{T}_n/a_n \to \widetilde{U}$, and thus, due to Lemma~\ref{lem:frechet-technical-2} together with the inequality \eqref{ineq:main:thm},  we have 
 \[
\lim_{n\to \infty}\EE \left(X \vert X > T_n\right)\frac{\sum_{j=1}^{k} \PP(M_n^{j}>T_n)}{\sum_{j=1}^k \EE(M_n^{j})} < \lim_{n\to \infty}\EE \left(X \vert X > \widetilde{T}_n\right)\frac{\sum_{j=1}^{k} \PP(M_n^{j}>\widetilde{T}_n)}{\sum_{j=1}^k \EE(M_n^{j})}.\]

The last inequality implies that there exists a positive integer $n_0$ such that for all $n>n_0$, 
 \[ 
 \EE \left(X \vert X > T_n\right)\frac{\sum_{j=1}^{k} \PP(M_n^{j}>T_n)}{\sum_{j=1}^k \EE(M_n^{j})} <  \EE \left(X \vert X > \widetilde{T}_n\right)\frac{\sum_{j=1}^{k} \PP(M_n^{j}>\widetilde{T}_n)}{\sum_{j=1}^k \EE(M_n^{j})},
 \]
 which is a contradiction since $T_n$ was taken optimally for each positive integer $n$. 
 Therefore we conclude that 
 $U$ is a maximizer in the optimization problem \eqref{eq:phi-function} defining the value $\varphi_k(2)$,
obtaining that $\apx_k(F)=\varphi_k(2)$. 
\end{proof}
\begin{lemma}
\label{lem:fechet-technical-1}
For every positive integer $k$, there exists a unique optimal solution $x_k$ for the optimization problem (\ref{eq:phi-function}) when $\alpha=2$, and furthermore we have that $(k+1)^{-1/2}\le x_k\le k^{-1/2}$.
In particular, we have
\[\varphi_k(2)=\frac{\Gamma(k)}{\Gamma(k+1-1/2)} \left(x_k^{-1}\calP\left(x_k^{-2},k-1\right)+kx_k\left(1-\calP\left(x_k^{-2},k\right)\right)\right).\]
\end{lemma}
To prove the lemma we use the following two propositions. 
\begin{proposition}
	\label{lem:inequalities}	
	For every positive integer $k$ the following holds:
	\begin{enumerate}[label=\normalfont(\roman*)] 
	\item For every value $y\in (0,\infty)$ we have that $y\calP(y,k-1)\le k\calP(y,k)$. \label{poisson-ineq-0}
	\item $\calP(k,k)+\calP(k,k-1)>1$. \label{poisson-ineq-1}
	\item $k(1-\calP(k+1,k))-(k+1)\calP(k+1,k-1)>0$. \label{poisson-ineq-2}
	\end{enumerate}
\end{proposition}

\begin{proof}
    Recall that $\calP(y,k)=\sum_{j=0}^k\frac{e^{-y}y^j}{j!} = \frac{\Gamma(k+1, y)}{\Gamma(k+1)}$.
	For every $y\in (0,\infty)$, the inequality in \ref{poisson-ineq-0} comes directly from the following chain:
	\begin{align*}
    y \calP(y,k-1) = y \frac{\Gamma(k, y)}{\Gamma(k)} = y \frac{\int_y^{\infty} x^{k-1} e^{-x} \dif y}{\Gamma(k)} \leq \frac{\int_y^{\infty} x^k e^{-x} \dif y}{\Gamma(k)} = \frac{\Gamma(k+1, y)}{\Gamma(k)} = k \frac{\Gamma(k+1, y)}{\Gamma(k+1)} = k \calP(y,k)
	\end{align*}
	% \begin{align*}
	% 	\calP(y,k-1)&=\sum_{j=0}^{k-1}\frac{e^{-y}y^j}{j!}=\sum_{j=1}^{k}\frac{e^{-y}y^{j-1}}{(j-1)!}=\frac{1}{y}\sum_{j=1}^{k}\frac{e^{-y}y^{j}j}{j!}\le \frac{k}{y}\sum_{j=1}^{k}\frac{e^{-y}y^{j}}{j!}=\frac{k}{y}\calP(y,k).
	% \end{align*}
	Next, we prove \ref{poisson-ineq-1}. 
	For every strictly positive integer $k$, let $\theta(k)$ be the value such that 
	\[\sum_{j=0}^{k-1}\frac{k^j}{j!}+\theta(k)\frac{k^k}{k!}=\frac{e^{k}}{2}.\]
	Therefore, we have that 
	\begin{align*}
	\calP(k,k)+\calP(k,k-1)&=\frac{e^{-k}k^k}{k!}+2\calP(k,k-1)\\
	                        &=\frac{e^{-k}k^k}{k!}+2\left(\frac{1}{2}-\theta(k)\frac{e^{-k}k^k}{k!}\right)=1+(1-2\theta(k))\frac{e^{-k}k^k}{k!}.
	\end{align*}
	Chow~\cite[Theorem 3]{choi1994medians} proved that for every $k$ we have that $1/3\le \theta(k)< 0.37$. 
	Therefore, we have that $\calP(k,k)+\calP(k,k-1)\ge 1+(1-2\cdot 0.37)\cdot e^{-k}k^k/k!>1$.

	Now we prove \ref{poisson-ineq-2}.
	By applying part \ref{poisson-ineq-0} with $y=k+1$ we get that $(k+1)\calP(k+1,k-1)\le k\calP(k+1,k)$.
	On the other hand, the median of a Poisson random variable of mean $k+1$ is at most $k+1$, and therefore $\calP(k+1,k)<1/2 \implies \calP(k+1,k)< 1-\calP(k+1,k)$.
	We conclude that $(k+1)\calP(k+1,k-1)\le k\calP(k+1,k)<k(1-\calP(k+1,k))$. 
\end{proof}

\begin{proposition}
\label{prop:unique-root}
Let $H$ and $L$ be two functions that are twice differentiable over $\RR_+$ and  satisfying the following conditions:
\begin{enumerate}[label=\normalfont(\alph*)] 
    \item $H(0)=L(0)$ and there exists $x\in (0,\infty)$ such that $H(x)=L(x)$.
%    \item $H$ and $L$ are both strictly increasing.
    \item $H''(y)>L''(y)$ for every $y\in (0,\infty)$.
\end{enumerate}
Then, $x$ is the unique solution in $(0,\infty)$ of the equation $H(y)=L(y)$.
\end{proposition}

\begin{proof}
Suppose that there is a value $\tilde x\ne x$ such that $H(\tilde x)=L(\tilde x)$ and assume without loss of generality that $x<\tilde x$.
Consider the function $\phi(y)=H(y)-L(y)$ over $\RR_+$.
Since $\phi(0)=H(0)-L(0)=0$ and $\phi(x)=H(x)-L(x)=0$, the mean value theorem guarantees the existence of a point $x_1\in (0,x)$ such that $\phi'(x_1)=0$, that is $H'(x_1)=L'(x_1)$.
On the other hand, since $\phi(\tilde x)=H(\tilde x)-L(\tilde x)=0=\phi(x)$, the mean value theorem guarantees the existence of a point $x_2\in (x,\tilde x)$ such that $\phi'(x_2)=0$, that is, $H'(x_2)=L'(x_2)$.
Then, we have that $x_1<x_2$ and $\phi'(x_1)=\phi'(x_2)$, and therefore the mean value theorem once more guarantees the existence of a point $x_3\in (x_1,x_2)$ such that $\phi''(x_3)=0$, that is, $H''(x_3)=L''(x_3)$, but this contradicts the condition $(b)$ satisfied by $H$ and $L$. 
\end{proof}

