\begin{proof}[Proof of Theorem \ref{thm:tightness}]
We first observe that thanks to Lemma~\ref{lem:frechet-eq}, showing Theorem~\ref{thm:tightness}  is equivalent to prove that if $F$ is the Pareto distribution with parameter $\alpha=2$, then  for every $\varepsilon>0$ there exists a positive integer $k_{\varepsilon}$ such that for every $k\ge k_{\varepsilon}$ it holds that $\varphi_k(2)\le 1-(1-\varepsilon)/\sqrt{2\pi k}$. In what follows, we prove the latter statement. 
Notice that thanks to Lemma \ref{lem:fechet-technical-1} we have that there exists an optimal solution $x_k\in [(k+1)^{-1/2},k^{-1/2}]$ such that
	\begin{align*}
		\varphi_k(2)&=\frac{\Gamma(k)}{\Gamma(k+1/2)}\left(\frac{1}{x_k}\calP_{k-1}(x_k^{-2})+kx_k(1-\calP_k(x_k^{-2}))\right)\\
		&=\frac{\Gamma(k)\sqrt{k-1}}{\Gamma(k+1/2)}\left(\frac{1}{x_k\sqrt{k-1}}\calP_{k-1}(x_k^{-2})+\frac{kx_k}{\sqrt{k-1}}(1-\calP_k(x_k^{-2}))\right).
	\end{align*}
	\begin{claim}
	\label{claim:gamma-upper}
	For every positive integer $k$ we have that $\displaystyle \frac{\Gamma(k)\sqrt{k-1}}{\Gamma(k+1/2)}\le 1$.
	\end{claim}
    \begin{proof}
    Thanks to the Gautschi inequality we have that $\frac{\Gamma(k+1)}{\Gamma(k+1/2)}\le \sqrt{k+1}$.
	Therefore, we have that 
	\[\frac{\Gamma(k)\sqrt{k-1}}{\Gamma(k+1/2)}=\frac{\Gamma(k+1)}{\Gamma(k+1/2)}\cdot \frac{\sqrt{k-1}}{k}\le \sqrt{k+1}\cdot \frac{\sqrt{k-1}}{k}=\frac{\sqrt{k^2-1}}{k}<1,\]
	which concludes the proof. 
    \end{proof}
	\noindent By using Claim \ref{claim:gamma-upper} we have that for every positive integer $k\ge 2$
	\begin{align*}
		\varphi_k(2)&\le\frac{1}{x_k\sqrt{k-1}}\calP_{k-1}(x_k^{-2})+\frac{kx_k}{\sqrt{k-1}}(1-\calP_k(x_k^{-2}))\\
		&\le \frac{\sqrt{k+1}}{\sqrt{k-1}}\calP_{k-1}(x_k^{-2})+\frac{\sqrt{k}}{\sqrt{k-1}}(1-\calP_k(x_k^{-2}))\\
		&\le \frac{\sqrt{k+1}}{\sqrt{k-1}}\Big(\calP_{k-1}(x_k^{-2})+1-\calP_k(x_k^{-2})\Big),
	\end{align*}
	where the second inequality follows thanks to Lemma \ref{lem:fechet-technical-1}.
	We recall that $\calP_k(x_k^{-2})$ is the probability that a Poisson random variable of mean $x_k^{-2}$ is at most $k$, and therefore we have that 
	\[\calP_{k-1}(x_k^{-2})+1-\calP_k(x_k^{-2})=1-\frac{e^{-x_k^{-2}}x_k^{-2k}}{k!},\]
	and this equality together with the above inequality imples that 
	\[\varphi_k(2)\le \left(\frac{k+1}{k-1}\right)^{1/2}\left(1-\frac{e^{-x_k^{-2}}x_k^{-2k}}{k!}\right).\]
	Then, we get that 
	\begin{equation*}
		(1-\varphi_k(2))\sqrt{2 k \pi}\ge \left(1-\left(\frac{k+1}{k-1}\right)^{1/2}\right)\sqrt{2 k \pi} +\left(\frac{k+1}{k-1}\right)^{1/2}\frac{e^{-x_k^{-2}}x_k^{-2k}}{k!}\sqrt{2 k \pi}.
	\end{equation*}
	Note that the function $e^{-y}y^k$ is decreasing in the interval $[k,\infty)$ and since $k\le x_k^{-2}\le k+1$ we have that $e^{-x_k^{-2}}x_k^{-2k}\ge e^{-(k+1)}(k+1)^k$.
	Therefore, we have that 
	\begin{align*}
		&(1-\varphi_k(2))\sqrt{2 k \pi}\\
		&\ge \left(1-\left(\frac{k+1}{k-1}\right)^{1/2}\right)\sqrt{2 k \pi} +\left(\frac{k+1}{k-1}\right)^{1/2}\frac{e^{-(k+1)}(k+1)^k}{k!}\sqrt{2 k \pi}\\
		&= \left(1-\left(\frac{k+1}{k-1}\right)^{1/2}\right)\sqrt{2 k \pi} +\left(\frac{k+1}{k-1}\right)^{1/2}\cdot \frac{e^{-k}k^k}{k!}\sqrt{2 k \pi}\cdot e^{-1}\cdot \left(1+\frac{1}{k}\right)^k.
	\end{align*}
	We conclude by observing that the following limits hold:
	\begin{align*}\lim_{k\to \infty}\left(1-\left(\frac{k+1}{k-1}\right)^{1/2}\right)\sqrt{2 k \pi}=0,&\quad \lim_{k\to \infty}\frac{e^{-k}k^k}{k!}\sqrt{2 k \pi}=1,\\
	\lim_{k\to \infty}\left(\frac{k+1}{k-1}\right)^{1/2}=1,&\quad\lim_{k\to \infty}\left(1+\frac{1}{k}\right)^k=e,
	\end{align*}
	where the second limit is given by the Stirling approximation.
\end{proof}


\section{Revenue Guarantees: Proof of Theorem \ref{thm:stability}}
\label{app:VVEV}

In the following, we prove Theorem~\ref{thm:stability}.
Recall that that a pair $(V,\eta)$ {\it smoothly represents} a distribution $F$ if $(V,\eta)$ is a Von Mises representation of $F$ and $\lim_{t \to \infty} \eta'(t)=0$ (see Lemma \ref{prop:Gumbel-prop}).
We first state the following simple lemma.
\begin{lemma}
\label{lem:nice-virtual}
Let $F$ be a distribution satisfying the extreme value condition. 
\begin{enumerate}[label=\normalfont(\roman*)]
	\item If $F$ has an extreme type Fr\'echet of parameter $\alpha\in (1,\infty)$ and it satisfies the asymptotic regularity condition, then $\lim_{t\to \infty}\phi_F(t)/t=1-1/\alpha.$\label{regular-a}
	\item If $F$ is a Von Mises function with auxiliary function $\aux$, then for every $t\in (\omega_0(F),\omega_1(F))$ we have that $\phi_F(t)=t-\aux(t)$.\label{regular-b} 
\end{enumerate}
\end{lemma}

\begin{proof}
If $F$ satisfies the asymptotic regularity condition it follows directly that
$\lim_{t\to \infty}\phi_F(t)/t=1-\lim_{t\to \infty}(1-F(t))/(tf(t))=1-1/\alpha.$
That proves \ref{regular-a}. 
Let $F$ be a Von Mises function with auxiliary function $\aux$ and $t\in (\omega_0(F),\omega_1(F))$. 
By the Von Mises representation~(\ref{V-M:repr}) we have that 
\[f(t)=\theta\exp\left( - \int\limits_{\omega_0(F)}^x \frac{1}{\aux(u)} \mathrm du  \right)\cdot \frac{1}{\aux(t)}=\frac{1-F(t)}{\aux(t)},\]
%\vlcom{Should $\eta$ above be $\theta$? Or $\eta^\star$? I think it definitely isn't $\eta$, since we use $\eta$ as a function $\eta(t)$.}
and therefore $\phi_F(t)=t-\aux(t)$.
That concludes \ref{regular-b}.
\end{proof}

