%To prove Theorem~\ref{thm:stability} we need a result from the extreme value theory stating that for distributions that exhibit the same tail behavior, if one of them has a certain extreme type, the other has an extreme type as well, and furthermore, it belongs to the same family. 
We say that two distributions $F$ and $G$ are {\it tail equivalent} if $\omega_1(F)=\omega_1(G)=\omega_1$ and there is a $\beta>0$ such that
$\lim_{x\to \omega_1}(1-G(x))/(1-F(x))=\beta.$
We call the value $\beta$ the {\it asymptotic tail ratio} between $F$ and $G$.
We state the following result from the extreme value theory literature.
\begin{theorem}[see, e.g., \cite{libroextremo}]
\label{thm:tail-behavior}
%(Proposition 1.19, p.67)
Let $F$ and $G$ be two tail equivalent distributions with asymptotic tail ratio $\beta$, and suppose that $F$ satisfies the extreme value condition.
Then, the following holds:
\begin{enumerate}[label=\normalfont(\alph*)] 
	\item If $F$ has extreme type Fr\'echet of parameter $\alpha\in (1,\infty)$, we have that $G$ has an extreme type distribution equal to $\Phi_{\alpha}(\beta^{-1/\alpha} t)$, where $\Phi_{\alpha}$ is the Fr\'echet distribution of parameter $\alpha$.\label{thm:tail-behavior-frechet}
	\item If $F$ has extreme type Gumbel, we have that $G$ has an extreme type distribution equal to $\Lambda(t-\ln(\beta))$, where $\Lambda$ is the Gumbel distribution. \label{thm:tail-behavior-gumbel}
\end{enumerate}
\end{theorem}
%\vvcom{hablar un poco de que son traslaciones, pero viven en la misma familia, etc}
%Given a valuation $v$ distributed according to $G$, we denote by $G_{\phi}$ the distribution of the virtual valuation $\phi(v)$.
The following lemma, together with Theorem~\ref{thm:tail-behavior} are the main tools to prove Theorem~\ref{thm:stability}.

\begin{lemma}
\label{lem:virtual-tail}
Let $F$ be a distribution that satisfies the extreme value condition. 
Then, the following holds.
\begin{enumerate}[label=\normalfont(\alph*)] 
	\item If $F$ has extreme type Fr\'echet of parameter $\alpha\in (1,\infty)$, and if its satisfies the asymptotic regularity condition, then $F$ and $F_{\phi}$ are tail equivalent with asymptotic tail ratio 
\begin{equation*}
\beta_{\alpha}=\lim_{t\to \infty}\frac{1-F_{\phi}(t)}{1-F(t)}=\left(1-\frac{1}{\alpha}\right)^{\alpha}.
\end{equation*}\label{virtual-tail-a}
	\item If $F$ has extreme type Gumbel, then $F$ and $F_{\phi}$ are tail equivalent with asymptotic tail ratio 
\begin{equation*}
\beta=\lim_{t\to \infty}\frac{1-F_{\phi}(t)}{1-V(t)}=\frac{\eta^{\star}}{e},
\end{equation*}
%\vlcom{Again, $\eta$ here should be $\eta^\star$, right?}
where $(V,\eta)$ is a Von Mises representation of $F$ according to \eqref{V-M:repr}.\label{virtual-tail-b}
\end{enumerate}
\end{lemma}
Observe that the asymptotic tail ratio for distributions with extreme type in the Fr\'echet family satisfies $\lim_{\alpha\to \infty}\beta_{\alpha}=1/e$.
Furthermore, if $F$ is a Von Mises function then the asymptotic tail ratio is equal to $1/e$ since we can always take the representation $(F,\mathsf{1}_{\RR})$.
\begin{comment}
To get more intuition about why these values hold, consider the Pareto distribution of parameter $\alpha\in (1,\infty)$.
In this case, observe that for every $t\in [1,\infty)$ we have that $\phi_{P_{\alpha}}(t)=t(\alpha-1)/\alpha$, since it satisfies the asymptotic regularity condition exactly.
In particular, for $G=P_{\alpha}$, we have that 
$1-G_{\phi}(t)=1-P_{\alpha}(\alpha t /(\alpha-1))=(1-1/\alpha)^{\alpha}t^{-\alpha}=(1-1/\alpha)^{\alpha}(1-P_{\alpha}(t)),$
for every $t\in [1,\infty)$.
Using the machinery we have from the Fr\'echet family we can show that the factor remains valid as long as a distribution has an extreme type of Fr\'echet parameter $\alpha\in (1,\infty)$.
For the Von Mises family, consider as example the exponential distribution of parameter $\lambda>0$.
In this case, we have that $\phi_G(t)=t-1/\lambda$ and therefore for every $t\ge 0$ it holds that $1-G_{\phi}(t)=e^{-\lambda(t+1/\lambda)}=\frac{1}{e}(1-G(t)).$\\
\end{comment}
We first show that the asymptotic tail ratio is preserved for Von Mises functions, and then we show how to extend for the Gumbel case.  
In the following we conclude Theorem~\ref{thm:stability} using Lemma~\ref{lem:virtual-tail}.

\begin{proof}[Proof of Theorem~\ref{thm:stability}]
Let $F$ be a distribution with extreme type Fr\'echet of parameter $\alpha\in (1,\infty)$.
By Lemma~\ref{lem:virtual-tail}, the distributions $F$ and $F_{\phi}$ are tail equivalent with asymptotic tail ratio equal to $\beta=((\alpha-1)/\alpha)^{\alpha}$.
By Theorem~\ref{thm:tail-behavior}\ref{thm:tail-behavior-frechet} we have that $F_{\phi}(t)=\Phi_{\alpha}(\beta^{-1/\alpha}t)=\Phi_{\alpha}(\alpha t/(\alpha-1))$. 
Now let $F$ be a distribution with extreme type Gumbel, and let $(V,\eta)$ a Von Mises representation according to Lemma~\ref{prop:Gumbel-prop}.
Thanks to Lemma~\ref{lem:virtual-tail}, we have that
%\vlcom{In many instances below, I think $\eta$ should be $\eta^\star$.}
\begin{align*}
    \lim_{t\to \infty}\frac{1-F_{\phi}(t)}{1-F(t)}&=\lim_{t\to \infty}\frac{1-F_{\phi}(t)}{1-V(t)}\cdot \frac{1-V(t)}{1-F(t)}=\lim_{t\to \infty}\frac{1-F_{\phi}(t)}{1-V(t)}\cdot \frac{1}{\eta(t)}=\frac{\eta^{\star}}{e}\cdot \frac{1}{\eta^{\star}}=\frac{1}{e},
\end{align*}
where the limits follows thanks to Lemma~\ref{lem:virtual-tail} and since $\lim_{t\to \infty}\eta(t)=\eta$.
Therefore, according to Theorem~\ref{thm:tail-behavior}\ref{thm:tail-behavior-gumbel} we have that that the virtual valuation has an extreme type with distribution $F_{\phi}(t)=\Lambda(t-\ln(1/e))=\Lambda(t+1)$.
To conclude the theorem, observe that for every $t\ge 0$ we have that $\PP(\phi_F(v)>t)=\PP(\phi_F^+(v)>t)$ and therefore $F_{\phi}$ and $F_{\phi}^+$ are tail equivalent. 
\end{proof}

Before proving Lemma~\ref{lem:virtual-tail} we need a few properties regarding the Von Mises representation and the corresponding auxiliary function. 

\begin{proposition}
\label{prop:asympt}
Let $F$ be a distribution with extreme type Gumbel that can be smoothly represented by a pair $(V,\eta)$ with auxiliary function $\aux:(z_0,\infty)\to \RR_+$.
Then, the following holds.
\begin{enumerate}[label=\normalfont(\roman*)] 
    \item For every $\delta>0$ there exists $t_{\delta}\in \RR_+$ such that for every $u>t\ge t_{\delta}$ we have $|\aux(u)-\aux(t)|\le \delta(u-t)$.\label{prop4a}
    \item For every $\delta>0$ there exists $t_{\delta}\in \RR_+$ such that for every $v\ge t_{\delta}$ we have that $\left|\frac{1-F(v)}{f(v)\aux(v)}-1\right|\le \delta$.\label{prop4b}
\end{enumerate}
\end{proposition}

\begin{proof}[Proof of Proposition~\ref{prop:asympt}]
Since $\lim_{t\to \infty}\aux'(t)=0$, there exists $t_{\delta}\in \RR_+$ such that for every $t\ge t_{\delta}$ we have $|\aux'(t)|\le \delta$.
In particular, we have that for every $u>t\ge t_{\delta}$, 
\begin{align*}
\aux(u)&=\aux(t)+\int_t^u \aux'(s)\mathrm ds\le \aux(t)+\delta(u-t),\\
\aux(u)&=\aux(t)+\int_t^u \aux'(s)\mathrm ds\ge \aux(t)-\delta(u-t),
\end{align*}
which concludes part \ref{prop4a}.
For part \ref{prop4b}, observe first from the Von Mises representation $(V,\eta)$ we have that there exists $t_0\in \RR_+$ such that for every $t\ge t_0$ we have $\aux(t)=(1-V(t))/V'(t)$. Since $1 - F(t) = \eta(t) \left(1 - V(t)\right)$ by Lemma~\ref{prop:Gumbel-prop}, we have that
\[
\frac{f(t)}{V'(t)} = \eta(t) - \eta'(t)\frac{1 - V(t)}{V'(t)} = \eta(t) - \eta'(t) \aux(t),
\]
and thus
\begin{equation*}
    \frac{1-F(t)}{f(t)\aux(t)}=\eta(t)\frac{V'(t)}{f(t)}=\frac{\eta(t)}{\eta(t)-\eta'(t)\aux(t)}.
\end{equation*}
Since $\lim_{t \to \omega_1(F)} \eta'(t)=0$ there exists $t_1\in \RR_+$ such that for every $t\ge t_1$, we have that $|\eta'(t)|\le 1/t$.
Therefore, for every $t\ge \max\{t_0,t_1\}$ we have that
\begin{equation*}
  \frac{\eta(t)}{\eta(t)+\frac{\aux(t)}{t}}\le  \frac{\eta(t)}{\eta(t)-\eta'(t)\aux(t)}\le \frac{\eta(t)}{\eta(t)-\frac{\aux(t)}{t}}.
\end{equation*}
Since $\lim_{t\to \infty}\aux(t)/t=0$ and $\eta^\star = \lim_{t \to \infty} \eta(t)$, we conclude the result.
%Thus, for every $t\ge t_0$, if $v-f(v)>t$ we have that 
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lem:virtual-tail}]
Consider first a valuation $v$ with extreme type Fr\'echet of parameter $\alpha$, with $\alpha\in (1,\infty)$, and satisfying the asymptotic regularity condition. 
Thanks to Lemma~\ref{lem:nice-virtual}\ref{regular-a}, for every $\varepsilon>0$ there exists $t_0\in \RR$ such that for every $x\ge t_0$ we have that
\begin{equation}
\label{eq:asympt}
\frac{\alpha-1}{\alpha}(1-\varepsilon)x\le \phi_F(x)\le \frac{\alpha-1}{\alpha}(1+\varepsilon)x.
\end{equation}
Therefore for every $t\ge t_0$, if we have $\phi_F(v)>t$ then $v>\frac{\alpha (1+\varepsilon)^{-1}t}{(\alpha-1)}$.
It follows on the one hand that
\begin{equation}
\label{eq:asym-ub}
1-F_{\phi}(t)=\PP(\phi_F(v)>t)\le \PP\left(v>\frac{\alpha (1+\varepsilon)^{-1}t}{(\alpha-1)}\right),
\end{equation}
and on the other hand, if $v>\frac{\alpha (1-\varepsilon)^{-1}t}{(\alpha-1)}$ then from (\ref{eq:asympt}) we have that $\phi_F(v)>t$.
Thus,
\begin{equation}
\label{eq:asym-lb}
1-F_{\phi}(t)=\PP(\phi_F(v)>t)\ge \PP\left(v>\frac{\alpha (1-\varepsilon)^{-1}t}{(\alpha-1)}\right).
\end{equation}
By Lemma~\ref{lem:fre-key}, there exists a slowly varying function $\ell_F$ such that $1-F(s)=s^{-\alpha}\ell_F(s)$ for every $s\in \RR_+$.
In particular, we have
\begin{align*}
\PP\left(v>\frac{\alpha (1+\varepsilon)^{-1}t}{(\alpha-1)}\right)&=t^{-\alpha}\left(1-\frac{1}{\alpha}\right)^{\alpha}\left(1+\varepsilon\right)^{\alpha}\ell_{F}\left(\frac{\alpha (1+\varepsilon)^{-1}t}{(\alpha-1)}\right)\\									&=(1-F(t))\left(1-\frac{1}{\alpha}\right)^{\alpha}\left(1+\varepsilon\right)^{\alpha}\ell_{F}\left(\frac{\alpha (1+\varepsilon)^{-1}t}{(\alpha-1)}\right)\frac{1}{\ell_F(t)},
\end{align*}
and furthermore we get
\begin{align*}
\PP\left(v>\frac{\alpha (1-\varepsilon)^{-1}t}{(\alpha-1)}\right)&=t^{-\alpha}\left(1-\frac{1}{\alpha}\right)^{\alpha}\left(1-\varepsilon\right)^{\alpha}\ell_{F}\left(\frac{\alpha (1-\varepsilon)^{-1}t}{(\alpha-1)}\right)\\
	&=(1-F(t))\left(1-\frac{1}{\alpha}\right)^{\alpha}\left(1-\varepsilon\right)^{\alpha}\ell_{F}\left(\frac{\alpha (1-\varepsilon)^{-1}t}{(\alpha-1)}\right)\frac{1}{\ell_F(t)}.
\end{align*}
Since $\ell_F$ is slowly varying, there exists $t_1\in \RR_+$ such that for every $t\ge t_1$ we have that 
\begin{equation*}
1-\varepsilon\le \ell_{F}\left(\frac{\alpha (1+\varepsilon)^{-1}t}{(\alpha-1)}\right)\frac{1}{\ell_F(t)}\le 1+\varepsilon,
\end{equation*}
\begin{equation*}
1-\varepsilon\le \ell_{F}\left(\frac{\alpha (1-\varepsilon)^{-1}t}{(\alpha-1)}\right)\frac{1}{\ell_F(t)}\le 1+\varepsilon.
\end{equation*}
Then, from inequalities (\ref{eq:asym-ub})-(\ref{eq:asym-lb}) together with the inequalities above we get that for every $t\ge \max\{t_0,t_1\}$, we have
\begin{equation*}
\left(1-\frac{1}{\alpha}\right)^{\alpha}(1-\varepsilon)^{\alpha+1}\le \frac{1-F_{\phi}(t)}{1-F(t)}\le \left(1-\frac{1}{\alpha}\right)^{\alpha}(1+\varepsilon)^{\alpha+1},
\end{equation*}
from where we obtain that 
$\lim_{t\to \infty}(1-F_{\phi}(t))/(1-F(t))=(1-1/\alpha)^{\alpha}.$
That concludes part \ref{virtual-tail-a}.  

Now let $F$ be a distribution with extreme type Gumbel and consider a Von Mises representation $(V,\eta)$, with auxiliary function $\aux:(z_0,\infty)\to \RR_+$ and $z_0>\omega_0(F)$.
By Lemma~\ref{lem:nice-virtual}\ref{regular-b}, for every $t\in (z_0,\infty)$ we have that $\phi_V(t)=t-\aux(t)$ and then $1-V_{\phi}(t)=\PP(\phi_V(v)>t)=\PP(v-\aux(v)>t)$.
\noindent Thus, using Proposition~\ref{prop:asympt} we have that for every $\varepsilon\in (0,1/3)$ there exists $t_0\in \RR_+$ such that for every $v\ge t\ge t_0$ we have that $(1-F(v))/f(v)\ge (1-\varepsilon)\aux(v)$ and $\aux(v)\ge \aux(t)+\varepsilon(v-t).$
Therefore, if $\phi_F(v)>t$ we have 
\begin{align*}
v>\frac{1-F(v)}{f(v)}+t&\ge (1-\varepsilon)\aux(v)+t\\
            &\ge (1-\varepsilon)(\aux(t)-\varepsilon(v-t))+t\\
            &=(1-\varepsilon)\aux(t)-(\varepsilon-\varepsilon^2) v+(1-\varepsilon^2+\varepsilon)t\\
            &=(1-\varepsilon)\aux(t)+t-(\varepsilon-\varepsilon^2) (v-t) \hfill \iff \\
(v-t)(1+\varepsilon-\varepsilon^2) &\geq (1-\varepsilon)\aux(t) \hfill \iff \\
v &\geq t + \frac{1-\varepsilon}{1+\varepsilon-\varepsilon^2} \aux(t),
\end{align*}
where the third inequality holds by the positivity of $\mu$ and the fact that $v>(1-\varepsilon)\aux(v)+t\ge t\ge t_0$. Let $\xi(\varepsilon)=(1-\varepsilon)/(1-\varepsilon^2+\varepsilon)$. Then, from the inequality above we get
\begin{align}
\label{eq:lower-von}
\PP(\phi_F(v)>t)&\le \PP\left(v>t+\xi(\varepsilon)\aux(t)\right)=1-F\left(t+\xi(\varepsilon)\aux(t)\right).
\end{align}
On the other hand, by Proposition~\ref{prop:asympt} there exists $t_1\in \RR_+$ such that for every $v\ge t\ge t_1$ we have $(1-F(v))/f(v)\le (1+\varepsilon)\aux(v)$ and $\aux(t)\ge \aux(v)-\varepsilon^2(v-t)$. 
Then, for every $t\ge \max\{t_0,t_1\}$, if $v>t+(1+2\varepsilon)\aux(t)$ and $v\le t+\frac{1}{\varepsilon(1+\varepsilon)}\aux(t)$ we have
\begin{align*}
v&> t+\varepsilon \aux(t)+(1+\varepsilon)\aux(t)\\
			&\ge t+\varepsilon \aux(t)+(1+\varepsilon)(\aux(v)-\varepsilon^2(v-t))\\
			&= t+(1+\varepsilon)\aux(v)+(1+\varepsilon)\varepsilon^2\left(t+\frac{1}{\varepsilon(1+\varepsilon)}\aux(t)-v\right)\ge t+\frac{1-F(v)}{f(v)}.
\end{align*}
Therefore, for every $t\ge \max\{t_0,t_1\}$ we have
\begin{align*}
\PP(\phi_F(v)>t)&\ge \PP\left(t+\frac{1}{\varepsilon(1+\varepsilon)}\aux(t)\ge v>t+(1+2\varepsilon)\aux(t)\right) \\
				&=1-F(t+(1+2\varepsilon)\aux(t))-\left(1-F\left(t+\chi(\varepsilon)\aux(t)\right)\right),
\end{align*}
where $\chi(\varepsilon)=1/(\varepsilon(1+\varepsilon))$.
In what follows we show that the previous upper and lower bounds on (\ref{eq:lower-von}) imply the tail equivalence between $V$ and $F_{\phi}$.
By applying repeatedly Lemma~\ref{lem:von-mises-prop} and the same argument used in the proof of Lemma~\ref{lem:mises-to-gumbel} for $b_n = t$ and $t = \xi(\varepsilon), (1+2\varepsilon)$ and $\chi(\varepsilon)$, respectively, we have that the following holds,
 \begin{align*}
\lim_{t\to \infty}\frac{1-F\left(t+\xi(\varepsilon)\aux(t)\right)}{1-V(t)}&=\lim_{t\to \infty}\eta(t+\xi(\varepsilon)\aux(t))\cdot \frac{1-V\left(t+\xi(\varepsilon)\aux(t)\right)}{1-V(t)}\\
&=\eta^\star e^{-\xi(\varepsilon)},\\
\lim_{t\to \infty}\frac{1-F\left(t+(1+2\varepsilon)\aux(t)\right)}{1-V(t)}&=\lim_{t\to \infty}\eta(t+(1+2\varepsilon)\aux(t))\cdot \frac{1-V\left(t+(1+2\varepsilon)\aux(t)\right)}{1-V(t)}\\
&=\eta^\star e^{-(1+2\varepsilon)},\\
\lim_{t\to \infty}\frac{1-F\left(t+\chi(\varepsilon)\aux(t)\right)}{1-V(t)}&=\lim_{t\to \infty}\eta(t+\chi(\varepsilon)\aux(t))\cdot \frac{1-V\left(t+\chi(\varepsilon)\aux(t)\right)}{1-V(t)}\\
&=\eta^\star e^{-\chi(\varepsilon)}.
\end{align*}

\noindent Since the above holds for every $\varepsilon\in (0,1/3)$, and observing that the function $\xi(\varepsilon)$ is increasing in the interval $(0,1/3)$ we conclude that 
\begin{align*}
\limsup_{t\to \infty}\frac{\PP(\phi_F(v)>t)}{1-V(t)}&\le \eta^{\star} \inf_{\varepsilon\in (0,1/3)}\exp\left(-\frac{1-\varepsilon}{1-\varepsilon^2+\varepsilon}\right)=\frac{\eta^{\star}}{e},\\
\liminf_{t\to \infty}\frac{\PP(\phi_F(v)>t)}{1-V(t)}&\ge \eta^{\star} \inf_{\varepsilon\in (0,1/3)}\left\{\exp\left(-(1+2\varepsilon)\right)-\exp\left(-\frac{1}{\varepsilon(1+\varepsilon)}\right)\right\}=\frac{\eta^{\star}}{e},
\end{align*}
that in turn implies that the claimed limit exists and its value is equal to
\begin{equation*}
\lim_{t\to \infty}\frac{1-F_{\phi}(t)}{1-V(t)}=\lim_{t\to \infty}\frac{\PP(\phi_F(v)>t)}{1-V(t)}=\frac{\eta^{\star}}{e}.
\end{equation*}
This concludes that $V$ and $F_{\phi}$ are tail equivalent with an asymptotic tail ratio equal to $\eta/e$.
\end{proof}






\section{Competition Complexity Guarantees: Proof of Theorem \ref{thm:comp-complexity-evt}}\label{sec:analysis-competition}
In this section, we prove Theorem~\ref{thm:comp-complexity-evt} about the large market competition complexity of distributions satisfying the extreme value condition. 
We start by obtaining a very useful quantile characterization of the expected value of the optimal policy; the quantile depends only on $\gamma$ and $n$. Afterward, we use this characterization and jointly with a set of lemmas on the order statistics to show our main result. 
%Finally, we show that if a distribution is MHR, its domain of attraction must lie in some range, yielding tighter results on the competition complexity of MHR distributions.
We start by providing a simple proposition about the optimal policy. Recall that $\{G_n(F)\}_{n\in \NN}$ satisfies the following recurrence: $G_0(F)=0$, $G_1(F)=\EE(X)$, and $G_{n+1}(F)=\EE(\max(X,G_n(F)))$, where $X$ is distributed according to $F$.
\begin{lemma}\label{lem:opt-dp}
For every $n \in \N$, and every distribution $F$, the following holds:
\begin{enumerate}[label=\normalfont(\roman*)]    
    \item $\Gmax{n+1} = \Gmax{n} + \int^{\omega_1(F)}_{\Gmax{n}} (1 - F(u))\dif u$.\label{lem:opt-dp-g}
    \item $\Gmax{n+1} = \Gmax{n} F(\Gmax{n}) + \int^{1 - F(\Gmax{n})}_0 {F^{\inv}(1-u)}\dif u$.\label{lem:opt-dp-inv}
\end{enumerate}    
\end{lemma}

\begin{proof}
Part \ref{lem:opt-dp-g} is obtained directly as
\begin{align*}
G_{n+1}(F)&=\EE(\max(X,G_n(F)))\\
&=G_n(F)+\EE(\max(0,G_n(F)-X))=\int^{\omega_1(F)}_{\Gmax{n}} {\prn{1 - F(u)} \dif u}.
\end{align*}
Part \ref{lem:opt-dp-inv} is obtained by taking the equality \ref{lem:opt-dp-g}, changing variables, and integrating by parts:
\begin{align*}
G_{n+1}(F) &= G_n(F) - G_n(F) \prn{1 - F(G_n(F))} + \int^{1 - F(G_n(F))}_0 {F^{-1}(1-u) \dif u} \\
&= G_n(F) F(G_n(F)) + \int^{1 - F(G_n(F))}_0 {F^{-1}(1-u) \dif u}.\qedhere
\end{align*}
\end{proof}

Our analysis relies heavily on the theory of \emph{regularly varying functions}, originally developed by Karamata. Regularly varying functions are, roughly speaking, functions that behave asymptotically like power functions. 
We briefly define them here; for more information on the topic, see e.g., \cite{libroextremo,bingham-rv,dehaan-ferreira-evt}.
\begin{definition}\label{def:reg-var}
Let $f: \Rp \to \Rp$ be a Lebesgue measurable function. 
We say that $f$ is regularly varying if, for some $\alpha \in \R$ and every $x > 0$, we have
$\lim_{t \to \infty} f(tx)/f(t) = x^\alpha.$
In this case, we indicate this as $f \in \rva{\alpha}$.
\end{definition}
In the above definition, $\alpha$ is called the \emph{index} of regular variation, and whenever $\alpha = 0$, we say that $f$ is \emph{slowly varying}. Furthermore, we say that $f(x)$ is regularly varying at $0$ if and only if $f(1/x)$ is regularly varying at infinity. If $f \in \rva{\alpha}$, then $L(x) = f(x)/x^\alpha \in \rva{0}$. 
One can represent any $f \in \rva{\alpha}$ as $f(x) = x^\alpha L(x)$, where $L$ is a slowly varying function.
The main tool from the theory of regular variation that we use to analyze the competition complexity is Karamata's Theorem (see, e.g., \cite[Theorem B.1.5]{dehaan-ferreira-evt}), which enables us to simplify the integrals in Lemma~\ref{lem:opt-dp}\ref{lem:opt-dp-inv} and obtain approximation recurrences for the optimal policy when $n$ is large.

We use the notation $a(n) \approx b(n)$ when $\lim_{n \to \infty} (a(n) - b(n)) = 0$. We also extend this notation for functions $f(x)\approx g(x)$ whenever $\lim_{x\to \infty}(f(x)-g(x))=0$. In what follows, for notation simplicity, we denote $\EE(\textstyle\max\{X_1,X_2,\ldots,X_n\})$ by $E_n(F)$. Recall that $\gamma$ partitions the space of all distributions with extreme value into the equivalence classes $D_{\gamma}$ with $\gamma \in \RR$: For $\gamma > 0$, we recover the Fr\'{e}chet family of distributions, for $\gamma = 0$, we get the Gumbel family, and for $\gamma < 0$, we obtain the Reverse Weibull family. We also say that a distribution $F$ is in $D_\gamma$ if it has extreme value index $\gamma$. In other words, $F$ is in $D_\gamma$ for $\gamma > 0$ implies that $F$ has extreme in the Fr\'{e}chet family with parameter $\alpha = 1/\gamma$, $F$ is in $D_\gamma$ for $\gamma = 0$ implies that $F$ has extreme Gumbel, and $F$ is in $D_\gamma$ for $\gamma < 0$ implies that $F$ has extreme in the Reverse Weibull family with parameter $\alpha = -1/\gamma$. Thus, from the extreme value theorem, it follows that $F \in D_\gamma$ implies that there exist sequences $\{a_n\}_{n\in \NN}, \{b_n\}_{n\in \NN}$ such that
\begin{equation}\label{eq:gnedenko-mu-approx-max}
\lim_{n \to \infty} F^n(a_n x + b_n) = G_\gamma(x)= \begin{cases}
\exp\prn{-\prn{1+\gamma x}^{-\f{1}{\gamma}}}, & \text{if } \gamma \neq 0, \\
\exp\prn{-\exp\prn{-x}}, & \text{if } \gamma = 0.
\end{cases}
\end{equation}

%%%%%%%%%%%%%%5
\begin{comment}
\begin{lemma}[{\cite[Theorem 5.3.1]{first-course-order-statistics}}.]\label{lem:mu-recurrence}
For every $i \in \set{1, \dots,n-1}$, we have
$i \mu_{i+1:n} + (n-i) \mu_{i:n} = n \mu_{i:n-1}$.
\end{lemma}
\end{comment}
\begin{restatable}{lemma}{muApprox}\label{lem:mu-approx}
For $\gamma\in \RR$ and every $F\in D_{\gamma}$ the following holds:
\[
E_n(F)\approx \begin{cases}
\Gamma(1 - \gamma) F^{\inv}(1-1/n) & \text{for } \gamma \in (0,1), \\
F^{\inv}\prn{1 - \frac{\exp({-\gamma^\star})}{n}} & \text{for } \gamma = 0, \\
\omega_1(F) - \Gamma(1 - \gamma) \prn{\omega_1(F) - F^{\inv}(1-1/n)} & \text{for } \gamma < 0,
\end{cases}
\]
where $\gamma^\star \approx 0.577$ is the Euler-Mascheroni constant.
\end{restatable}
Before proving the lemma, we recall a useful fact from extreme value theory.
For $M_n^1 = \max\set{X_1, \dots, X_n}$ and $U(x)=F^{-1}(1-x)$, when \eqref{eq:gnedenko-mu-approx-max} is satisfied, we can take the following sequences (see, e.g., \cite[Corollary 1.2.4]{dehaan-ferreira-evt}):
\begin{enumerate}
    \item $a_n = U(1/n)$ and $b_n = 0$, if $\gamma \in (0,1)$,
    \item $b_n = U(1/n)$ and appropriately chosen $a_n$ if $\gamma = 0$, and
    \item $a_n = \omega_1(F) - U(1/n)$ and $b_n = \omega_1(F)$, if $\gamma < 0$,
\end{enumerate}
Let $Y_n = (M_n^1 - b_n)/a_n$. 
The above implies that the sequence $\{Y_n\}_{n\in \NN}$ converges in distribution to a random variable $Z$ distributed according to $G_\gamma$. Notice that for $\gamma\in (0,1)$ we have $\E[Z] = \Gamma(1 - \gamma)$, for $\gamma = 0$ we have $\E[Z] = \gamma^{\star}$, and for $\gamma < 0$ we have $\E[Z] = - \Gamma(1 - \gamma)$; see, e.g., \cite[Theorem 5.3.1]{dehaan-ferreira-evt}.
Now we have all the ingredients to prove Lemma \ref{lem:mu-approx}.
\begin{proof}[Proof of Lemma \ref{lem:mu-approx}]
For large enough $n$ and $\gamma \in (0,1)$ we have
$\E(Y_n) \approx \Gamma(1 - \gamma)$ if and only if $E_n(F) \approx \Gamma(1 - \gamma) a_n = \Gamma(1 - \gamma) F^{\inv}\prn{1 - {1}/{n}}.$
For $\gamma = 0$, we have $\E(Y_n) \approx \gamma^{\star}$ if and only if
\begin{equation}\label{eq:mu-approx-max-1}
E_n(F) \approx a_n \gamma^{\star} + b_n = a_n \gamma^{\star} + U\prn{{1}/{n}} = a_n \gamma^{\star} + F^{\inv}\prn{1 - {1}/{n}}.
\end{equation}
Also, for $\gamma = 0$, by \cite[Theorem 1.1.6]{dehaan-ferreira-evt}, we have that, for any $x > 1$
\begin{equation}\label{eq:mu-approx-max-2}
a_n \approx \frac{U\prn{{1}/{(x n)}} - U\prn{{1}/{n}}}{\log{x}} = \frac{F^{\inv}\prn{1 - {1}/{(x n)}} - F^{\inv}\prn{1 - {1}/{n}}}{\log{x}}.
\end{equation}
Combining \eqref{eq:mu-approx-max-1} and \eqref{eq:mu-approx-max-2}, we get
\[
E_n(F) \approx \frac{\gamma^{\star}}{\log{x}} F^{\inv}(1-1/(xn)) + \prn{1 - \frac{\gamma^{\star}}{\log{x}}} F^{\inv}(1-1/n),
\]
and setting $x = e^{\gamma^{\star}}$ yields
$E_n(F) \approx F^{\inv}\prn{1 - {e^{-\gamma^{\star}}}/{n}}.$
Finally, for $\gamma < 0$, we have $\E(Y_n) \approx -\Gamma(1 - \gamma)$ if and only if $E_n(F) \approx -\Gamma(1 - \gamma) a_n  + b_n = \omega_1(F) - \Gamma(1 - \gamma) \prn{\omega_1(F) - F^{\inv}(1-1/n)}.$
\end{proof}

\begin{restatable}{lemma}{multQApprox}\label{lem:mult-quantile-approx}
For $\gamma\in (-\infty,1)$, $F\in D_{\gamma}$, and $c > 0$, the following holds:
\begin{enumerate}[label=\normalfont(\roman*)]  
\item For $\gamma \in (0,1)$, we have $F^{\inv}\prn{1 - {c}/{n}} \approx c^{-\gamma} F^{\inv}\prn{1 - {1}/{n}}$.
\item For $\gamma \in (0,1)$, we have $F^{\inv}\prn{1 - \frac{1}{n-c}} \approx \prn{\frac{n}{n-c}}^{-\gamma} F^{\inv}\prn{1 - {1}/{n}}$.
\item For $\gamma < 0$, we have $\omega_1(F) - F^{\inv}\prn{1 - {c}/{n}} \approx c^{-\gamma} \prn{\omega_1(F) - F^{\inv}\prn{1 - {1}/{n}}}$.
\item For $\gamma < 0$, we have $\omega_1(F) - F^{\inv}\prn{1 - \frac{1}{n-c}} \approx \prn{\frac{n}{n-c}}^{-\gamma} \prn{\omega_1(F) - F^{\inv}\prn{1 - {1}/{n}}}$.
\end{enumerate}
\end{restatable}

\begin{proof}
(i). Let $\gamma \in (0,1)$. Since $F \in D_\gamma$, we have $U\circ \f{1}{x} \in \text{RV}_{\gamma}$; see, e.g., \cite[Corollary 1.2.10]{dehaan-ferreira-evt}. In particular, we have
\[
\lim_{n \to \infty} {\frac{F^{\inv}(1-1/(xn))}{F^{\inv}(1-1/n)}}=\lim_{n \to \infty} \frac{U({1}/{(x n)})}{U({1}/{n})} = x^{\gamma},
\]
for all $x > 0$. 
In particular, for $x = {1}/{c}$ we get
$F^{\inv}(1-c/n) \approx c^{-\gamma} F^{\inv}(1-1/n)$.

(ii). Next, by the Potter bounds on regularly varying functions (see, e.g., \cite[Theorem 1.5.6]{bingham-rv}), since $U\circ \f{1}{x} \in \text{RV}_{\gamma}$, we have that for every $\delta_1, \delta_2 > 0$ and every $x,y > 0$, there exists a $x_0 = x_0(\delta_1, \delta_2) > 0$ such that for all $x,y \geq x_0$,
\[
(1- \delta_1) \prn{\frac{x}{y}}^{\gamma - \delta_2} \leq \frac{U(1/x)}{U(1/y)} \leq (1+\delta_1) \prn{\frac{x}{y}}^{\gamma + \delta_2},
\]
which implies that
\[
\limsup_{\delta_1, \delta_2} (1- \delta_1) \prn{\frac{n-c}{n}}^{\gamma - \delta_2} \leq \lim_{n \to \infty} \frac{U\prn{\frac{1}{n-c}}}{U\prn{\frac{1}{n}}} \leq \liminf_{\delta_1, \delta_2} (1+\delta_1) \prn{\frac{n-c}{n}}^{\gamma + \delta_2},
\]
and thus
\[
\lim_{n \to \infty} \frac{U\prn{\frac{1}{n-c}}}{U\prn{\frac{1}{n}}} = \prn{\frac{n}{n-c}}^{-\gamma},
\]
yielding $F^{\inv}\prn{1 - \frac{1}{n-c}} \approx \prn{\frac{n}{n-c}}^{-\gamma} F^{\inv}\prn{1 - {1}/{n}}$.

(iii). Next, let $\gamma < 0$. 
Since $F \in D_\gamma$, we have $\omega_1(F) - U\circ \f{1}{x}\in \text{RV}_{\gamma}$: see, e.g., \cite[Corollary 1.2.10]{dehaan-ferreira-evt}. In particular, we have
\[
\lim_{n \to \infty} {\frac{\omega_1(F) - F^{\inv}(1-1/(xn))}{\omega_1(F) - F^{\inv}(1-1/n)}}=\lim_{n \to \infty} \frac{\omega_1(F) - U(1/(xn))}{\omega_1(F) - U(1/n)} =x^{\gamma},
\]
for all $x > 0$. 
In particular, for $x = {1}/{c}$ we get
$x^{\star} - F^{\inv}(1-c/n) \approx c^{-\gamma} \prn{x^{\star} - F^{\inv}(1-1/n)}$.

(iv). Finally, by the Potter bounds on regularly varying functions (see, e.g., \cite[Theorem 1.5.6]{bingham-rv}), since $\omega_1(F) - U\circ \f{1}{x} \in \text{RV}_{\gamma}$, we have that for every $\delta_1, \delta_2 > 0$ and every $x,y > 0$, there exists a $x_0 = x_0(\delta_1, \delta_2) > 0$ such that for all $x,y \geq x_0$,
\[
(1- \delta_1) \prn{\frac{x}{y}}^{\gamma - \delta_2} \leq \frac{\omega_1(F) - U(1/x)}{\omega_1(F) - U(1/y)} \leq (1+\delta_1) \prn{\frac{x}{y}}^{\gamma + \delta_2},
\]
which implies that
\[
\limsup_{\delta_1, \delta_2} (1- \delta_1) \prn{\frac{n-c}{n}}^{\gamma - \delta_2} \leq \lim_{n \to \infty} \frac{\omega_1(F) - U\prn{\frac{1}{n-c}}}{\omega_1(F) - U\prn{\frac{1}{n}}} \leq \liminf_{\delta_1, \delta_2} (1+\delta_1) \prn{\frac{n-c}{n}}^{\gamma + \delta_2},
\]
and thus
\[
\lim_{n \to \infty} \frac{\omega_1(F) - U\prn{\frac{1}{n-c}}}{\omega_1(F) - U\prn{\frac{1}{n}}} = \prn{\frac{n}{n-c}}^{-\gamma},
\]
yielding $\omega_1(F) - F^{\inv}\prn{1 - \frac{1}{n-c}} \approx \prn{\frac{n}{n-c}}^{-\gamma} \prn{\omega_1(F) - F^{\inv}\prn{1 - {1}/{n}}}$.
\end{proof}


Next, we use Lemmas~\ref{lem:mu-approx} and~\ref{lem:mult-quantile-approx} to characterize the ratio of the prophet's expected value for $n-1$ and $n$ as $n \to \infty$. 
\begin{restatable}{lemma}{muRatioApprox}\label{lem:mu-ratio-approx}
For $\gamma\in (-\infty,1)$ and $F\in D_{\gamma}$, the following holds:
\begin{enumerate}[label=\normalfont(\roman*)]  
\item For $\gamma \in (0,1)$, we have $E_{n-1}(F)/E_{n}(F) = 1 - \gamma/n + o({1}/{n})$.
\item For $\gamma < 0$, we have ${(\omega_1(F) - E_{n-1}(F))}/{(\omega_1(F) - E_{n}(F))} = 1 - \gamma/n + o(1/n)$.
\end{enumerate}
\end{restatable}

\begin{proof}
Let $\gamma \in (0,1)$. 
By Lemma~\ref{lem:mu-approx} we have $E_{n-1}(F) \approx \Gamma(1 - \gamma) F^{\inv}(1-1/(n-1))$, and using Lemma~\ref{lem:mult-quantile-approx}, we get
\[
E_{n-1}(F) \approx \Gamma(1 - \gamma) \prn{1+\frac{1}{n-1}}^{-\gamma} F^{\inv}(1-1/n).
\]
Again by Lemma~\ref{lem:mu-approx}, we have
$E_{n}(F) \approx \Gamma(1 - \gamma) F^{\inv}(1-1/n)$
and thus
\[
\frac{E_{n-1}(F)}{E_{n}(F)} \approx \prn{1+\frac{1}{n-1}}^{-\gamma} = 1 - {\gamma}/{n} + o(1/n).
\]
Similarly, for $\gamma < 0$, by Lemma~\ref{lem:mu-approx} we have $\omega_1(F) - E_{n-1}(F) \approx \Gamma(1 - \gamma) F^{\inv}(1-1/(n-1))$ and using Lemma~\ref{lem:mult-quantile-approx}, we get
\[
x^{\star} - E_{n-1}(F) \approx \Gamma(1 - \gamma) \prn{1 +\frac{1}{n-1}}^{-\gamma} F^{\inv}(1-1/n).
\]
By Lemma~\ref{lem:mu-approx}, we have
$\omega_1(F) - E_{n}(F) \approx \Gamma(1 - \gamma) F^{\inv}(1-1/n),$
and thus
\[
\frac{\omega_1(F) - E_{n-1}(F)}{\omega_1(F) - E_{n}(F)} \approx \prn{1+\frac{1}{n-1}}^{-\gamma} = 1 - {\gamma}/{n} + o(1/n).\qedhere
\]
\end{proof}
%%%%%%%%%%%%%%%%%%%%%%

\begin{lemma}\label{lem:gn-done}
When $\gamma<1$, for every $F\in D_\gamma$ we have
$\Gmax{n+1} \approx \Gmax{n} \prn{1 + \frac{\gamma}{1 - \gamma} \prn{1 - F(\Gmax{n})}}.$
\end{lemma}

\begin{proof}
By Karamata's theorem (see, e.g., \cite[Theorem B.1.5]{dehaan-ferreira-evt}), when $\gamma <1$ we have
$\int^x_0 {F^{\inv}(1-u) \dif u} \approx {x F^{\inv}(1-x)}/{(1 - \gamma)}.$
In particular, this implies that
\begin{align*}
\int^{1 - F(\Gmax{n})}_0 {F^{\inv}(1 -u) \dif u} &\approx \frac{\prn{1 - F(\Gmax{n})}F^{\inv}\prn{1 - (1 - F(\Gmax{n}))}}{1-\gamma}\\
&= \frac{\Gmax{n}\prn{1 - F(\Gmax{n})}}{1-\gamma}.
\end{align*}
Thus, by Lemma~\ref{lem:opt-dp}\ref{lem:opt-dp-inv},
\begin{align*}
\Gmax{n+1} &\approx \Gmax{n} \prn{F(\Gmax{n}) + \frac{1 - F(\Gmax{n})}{1-\gamma}}= \Gmax{n} \prn{1 + \frac{\gamma}{1 - \gamma} \: \: \prn{1 - F(\Gmax{n})}}.\qedhere
\end{align*}
\end{proof}
In the following lemma, we provide an explicit approximation of $\Gmax{n}$ with respect to the quantile function of the distribution and the value $\gamma$.
\begin{lemma}\label{lem:alg-quantile}
When $\gamma < 1$, for every $F \in D_\gamma$ we have
$\Gmax{n} \approx F^{\inv}\prn{1 - {(1 - \gamma)}/{(n+1)}}.$
\end{lemma}

\begin{proof}
From \cite{KK91}, we know that the competitive ratio of the prophet inequality for distributions with extreme value is equal to a non-zero constant, which implies that
${\Gmax{n+1}}/{E_{n+1}(F)} - {\Gmax{n}}/{E_{n}(F)} \approx 0.$
Thus, for $\gamma \in (0,1)$, we obtain
\begin{align*}
& \frac{\Gmax{n+1}}{E_{n+1}(F)} - \frac{\Gmax{n}}{E_{n}(F)} \approx 0 \\
&\iff \frac{\Gmax{n}}{E_{n}(F)} \prn{\frac{E_{n}(F)}{E_{n+1}(F)} \prn{1 + \frac{\gamma}{1 - \gamma} \prn{1 - F(\Gmax{n})}} - 1} \approx 0 \\
&\iff \prn{1 - \frac{\gamma}{n+1} + o\left(\frac{1}{n+1}\right)} \prn{1 + \frac{\gamma}{1 - \gamma} \prn{1 - F(\Gmax{n})}} - 1 \approx 0 \\
&\iff \prn{1 - F(\Gmax{n})} \frac{\gamma}{1 - \gamma} \approx \frac{\gamma}{n+1} \\
&\iff 1 - F(\Gmax{n}) \approx \frac{1 - \gamma}{n+1}\iff \Gmax{n} \approx F^{\inv}\prn{1 - \frac{1 - \gamma}{n+1}},
\end{align*}
where the first equivalence follows from Lemma~\ref{lem:gn-done}, the second equivalence follows from Lemma~\ref{lem:mu-ratio-approx} and the third equivalence follows by ignoring lower-order terms.
%%%%%%%%%%%%%%%%%%%%%%%%%%%
For $\gamma = 0$, we need the following claim.
\begin{claim}\label{clm:g-approx-for-zero}
For $F \in D_0$ we have
$\int^{1 - F(\Gmax{n})}_0 {F^{\inv}\prn{1-u} \dif u} \approx F^{\inv}\prn{1 - \frac{1}{n+1}} \prn{1 - F(\Gmax{n})}.$
\end{claim}
\begin{proof}
The claim follows directly from \cite[Corollary 1.2.15]{dehaan-ferreira-evt} for $t = e/{(1 - F(\Gmax{n}))}$.
\end{proof}
Combining Claim~\ref{clm:g-approx-for-zero} with Lemma~\ref{lem:opt-dp}\ref{lem:opt-dp-inv} and Lemma~\ref{lem:gn-done}, we get
\[
\Gmax{n}\prn{1 - F(\Gmax{n})} \approx F^{\inv}\prn{1 - \frac{1}{n+1}} \prn{1 - F(\Gmax{n})} \iff \Gmax{n} \approx F^{\inv}\prn{1 - \frac{1}{n+1}}.
\]
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
When $\gamma<0$, we necessarily have $\omega_1(F) < \infty$. 
The analysis follows similarly to the $\gamma \in (0,1)$ case, but for the value $\omega_1(F) - \Gmax{n}$ instead of $\Gmax{n}$.
Notice that, by Lemma~\ref{lem:opt-dp}\ref{lem:opt-dp-g} we have
\begin{align*}
%\Gmax{n+1} &= \Gmax{n} + \int^{x^{\star}}_{\Gmax{n}} {\prn{1 - F(u)} \dif u} \\
%&= \Gmax{n} + x^{\star} - \Gmax{n} - \int^{x^{\star}}_{\Gmax{n}} F(u) \dif u \iff \\
\omega_1(F) - \Gmax{n+1} &= \int^{\omega_1(F)}_{\Gmax{n}} {F(u) \dif u}.
\end{align*}
%Next, we analyze the integral on the right-hand side.
\begin{claim}\label{lem:max-neg-g-int}
For $\gamma < 0$  we have
$\int^{\omega_1(F)}_{\Gmax{n}} {F(u) \dif u} \approx \prn{1 + \frac{\gamma}{1-\gamma} \prn{1 - F(\Gmax{n})} } \prn{\omega_1(F) - \Gmax{n}}.$
\end{claim}
\begin{proof}
Let $y = 1 - F(u)$, which implies that $\dif u = \prn{F^{\inv}\prn{1-y}}' \dif y$. Then,
\begin{align*}
\int^{\omega_1(F)}_{\Gmax{n}} {F(u) \dif u} 
%= \int^0_{1 - F(\Gmax{n})} {(1 - y) \prn{F^{\inv}\prn{1-y}}' \dif y} \\
%&= \brk{(1 - y) F^{\inv}\prn{1-y}}^0_{1 - F(\Gmax{n})} + \int^0_{1 - F(\Gmax{n})} {F^{\inv}\prn{1-y} \dif y} \\
&= \omega_1(F) - \Gmax{n} F(\Gmax{n}) - \int^{1 - F(\Gmax{n})}_0 {F^{\inv}\prn{1-y} \dif y} \\
%&= x^{\star} - \Gmax{n} F(\Gmax{n}) + \int^{1 - F(\Gmax{n})}_0 {\prn{x^{\star} - x^{\star}} \dif y} - \\
%&\qquad - \int^{1 - F(\Gmax{n})}_0 {F^{\inv}\prn{1-y} \dif y} \\
&= F(\Gmax{n}) \prn{\omega_1(F) - \Gmax{n}} + \int^{1 - F(\Gmax{n})}_0 {\prn{\omega_1(F) - F^{\inv}\prn{1-y}} \dif y}.
\end{align*}
Next, let $z = {1}/{y}$, which implies $\dif y = -z^{-2} \dif z$, and thus
\begin{align*}
\int^{\omega_1(F)}_{\Gmax{n}} {F(u) \dif u} &=  F(\Gmax{n}) \prn{\omega_1(F) - \Gmax{n}} + \int^\infty_{{1}/{(1 - F(\Gmax{n}))}} {z^{-2} \prn{\omega_1(F) - F^{\inv}\prn{1-{1}/{z}}} \dif z}.
\end{align*}
For $\gamma < 0$, the function $g(z) = \omega_1(F) - F^{\inv}\prn{1-{1}/{z}} \in \text{RV}_\gamma$ by \cite[Corollary 1.2.10]{dehaan-ferreira-evt} and $1+\gamma < 1$ which, by the general form of Karamata's theorem \cite[Theorem 1.5.11]{bingham-rv} for $\sigma = -2$ implies that
\[
\int^\infty_{{1}/{(1 - F(\Gmax{n}))}} {z^{-2} \prn{\omega_1(F) - F^{\inv}\prn{1 - {1}/{z}}} \dif z} \approx \frac{1 - F(\Gmax{n})}{1 - \gamma} \prn{\omega_1(F) - \Gmax{n}}.
\]
Therefore,
\begin{align*}
\int^{\omega_1(F)}_{\Gmax{n}} {F(u) \dif u} &\approx \prn{F(\Gmax{n}) + \frac{1 - F(\Gmax{n})}{1 - \gamma}} \prn{\omega_1(F) - \Gmax{n}} \\
&= \prn{1 - \prn{1 - F(\Gmax{n})} + \frac{1 - F(\Gmax{n})}{1 - \gamma}} \prn{\omega_1(F) - \Gmax{n}} \\
&= \prn{1 - \prn{1 - F(\Gmax{n})} \prn{1 - \frac{1}{1 - \gamma}}} \prn{\omega_1(F) - \Gmax{n}} \\
&= \prn{1 + \frac{\gamma}{1-\gamma} \prn{1 - F(\Gmax{n})} } \prn{\omega_1(F) - \Gmax{n}}.\qedhere
\end{align*}
\end{proof}
Thus,
\[
\frac{\omega_1(F) - \Gmax{n+1}}{\omega_1(F) - \Gmax{n}} \approx 1 + \frac{\gamma}{1-\gamma} \prn{1 - F(\Gmax{n})}.
\]
However, notice that
\begin{align*}
\frac{\omega_1(F) - \Gmax{n+1}}{\omega_1(F) - \Gmax{n}} &= \frac{\omega_1(F) - \Gmax{n+1}}{\omega_1(F) - E_{n+1}(F)} \cdot \frac{\omega_1(F) - E_{n}(F)}{\omega_1(F) - \Gmax{n}} \cdot \frac{\omega_1(F) - E_{n+1}(F)}{\omega_1(F) - E_{n}(F)}\\
&\approx \frac{\omega_1(F) - E_{n+1}(F)}{\omega_1(F) - E_{n}(F)},
\end{align*}
where the last asymptotic equality follows from the fact that the competitive ratio of the prophet inequality converges asymptotically to a non-zero constant \cite{KK91}. By Lemma~\ref{lem:mu-ratio-approx}, we have
$${(\omega_1(F) - E_{n+1}(F))}/{(\omega_1(F) - E_{n}(F))} \approx 1 - {\gamma}/{(n+1)} + o(1/n),$$
and thus, ignoring lower-order terms, we obtain
\[
1 + \frac{\gamma}{1-\gamma} \prn{1 - F(\Gmax{n})} \approx 1 - \frac{\gamma}{n+1},
\]
which implies that $\Gmax{n} \approx F^{\inv}\prn{1 - \frac{1-\gamma}{n+1}}$.
\end{proof}
We are now ready to prove Theorem~\ref{thm:comp-complexity-evt}.
\begin{proof}[Proof of Theorem \ref{thm:comp-complexity-evt}]
First, let $\gamma > 0$. For every $c>0$ we have
\[
\Gmax{cn} \approx F^{\inv}\prn{1 - \frac{1-\gamma}{c \: n+1}} \approx F^{\inv}\prn{1 - \frac{1-\gamma}{c \: n}} \approx \prn{\frac{1-\gamma}{c}}^{-\gamma} F^{\inv}(1-1/n),
\]
where the first asymptotic equality follows from Lemma~\ref{lem:alg-quantile}, and the second one follows from Lemma~\ref{lem:mult-quantile-approx}. 
From Lemma~\ref{lem:mu-approx} we have
$E_{n}(F) \approx \Gamma(1-\gamma) F^{\inv}(1-1/n)$and observe that
${((1-\gamma)/{c})}^{-\gamma} \geq \Gamma(1-\gamma)$ if and only if $c \geq (1-\gamma) \prn{\Gamma(1-\gamma)}^{\f{1}{\gamma}}$ and thus,
$$\ACCMmax = \inf\set{c>0 :\prn{\frac{1-\gamma}{c}}^{-\gamma} \geq \Gamma(1-\gamma)} = (1-\gamma) \prn{\Gamma(1-\gamma)}^{\f{1}{\gamma}}.$$
Next, let $\gamma = 0$. We have
$\Gmax{cn} \approx F^{\inv}\prn{1 - {1}/{(cn+1)}} \approx F^{\inv}\prn{1 - {1}/{(cn)}}$,
where the first asymptotic equality follows from Lemma~\ref{lem:alg-quantile}. 
From Lemma~\ref{lem:mu-approx} we have
$E_{n}(F) \approx F^{\inv}\prn{1 - {e^{-\gamma^\star}}/{n}},$
where $\gamma^\star \approx 0.577$ is the Euler-Mascheroni constant. Notice that since $F$ is a monotonically increasing function, we have
$F^{\inv}\prn{1 - {1}/{(cn)}} \geq F^{\inv}\prn{1 - {e^{-\gamma^\star}}/{n}}$ if and only if $c \geq e^{\gamma^{\star}}$.
Thus,
$\ACCMmax = e^{\gamma^{\star}}.$
%Also notice that $\lim_{\gamma \to 0} {(1-\gamma) \prn{\Gamma(1-\gamma)}^{\f{1}{\gamma}}} = e^{\gamma^\star}$.
Finally, let $\gamma < 0$ and recall that, in this case, $\omega_1(F) < \infty$.
We have
$\Gmax{cn} \approx F^{\inv}\prn{1 - {(1-\gamma)}/{(cn+1)}} \approx F^{\inv}\prn{1 - {(1-\gamma)}/{(cn)}}.$
From Lemma~\ref{lem:mu-approx}, we know that
$E_{n}(F) \approx \omega_1(F) - \Gamma(1-\gamma) \prn{\omega_1(F) - F^{\inv}(1-1/n)}$, and therefore, by Lemma~\ref{lem:alg-quantile}, $\Gmax{cn} \geq E_{n}(F)$ if and only if
\begin{align*}
\prn{\frac{1-\gamma}{c}}^{-\gamma} \prn{\omega_1(F) -  F^{\inv}(1-1/n)} &\leq \Gamma(1-\gamma) \prn{\omega_1(F) - F^{\inv}(1-1/n)}.
\end{align*} 
We conclude that
$\ACCMmax = \inf\set{c>0 : \prn{\frac{1-\gamma}{c}}^{-\gamma} \geq \Gamma(1-\gamma)} = (1-\gamma) \prn{\Gamma(1-\gamma)}^{\f{1}{\gamma}}.$
\end{proof}

