In this section, we show that for the special case of MHR distributions, $\gamma \leq 0$.
\begin{lemma}\label{lem:mhr-gammas}
For every MHR distribution $\cD$ with CDF $F$, the following holds:
If $\cD \in D_\gamma$ for maxima, then $\gamma \leq 0$.
\end{lemma}

\begin{proof}
Since $\cD$ is MHR, we know $h(x) = \frac{f(x)}{1 - F(x)}$ is monotonically increasing. This implies that
\[
\int_0^x {h(u) \dif u} = \int_0^x {\frac{f(u)}{1 - F(u)} \dif u} = \int_0^x {\prn{-\log\prn{1 - F(u)}}' \dif u} = -\log\prn{1 - F(x)} = \bigOm{x}.
\]
The above implies that there exist constants $c, x_0 \in \Rp$ such that
\begin{equation}\label{eq:asymptotic-log-f}
-\log\prn{1 - F(x)} \geq c x, \qquad \forall x \geq x_0.
\end{equation}
Let $y_1 = 1 - F(x) \iff x = F^{\inv}(1 - y_1)$ and $y_2 = F(x) \iff x = F^{\inv}(y_2)$. As $x \to x^{\star}$, we have $y_1 \to 0^+$ and $y_2 \to 1^-$, i.e. $\f{1}{y_1}$ and $y_2$ are increasing. By~\eqref{eq:asymptotic-log-f}, we have
\[
\log{y_1} \leq - c  F^{\inv}(1-y_1), \qquad \forall y \leq y_{1,0},
\]
where $y_{1,0} = 1 - F(x_0)$. Let $z = \f{1}{y_1}$. Then,
\[
-\log{z} \leq - c F^{\inv}(1 - \f{1}{z}) \qquad \forall z \geq z_0,
\]
where $z_0 = \f{1}{y_{1,0}}$. Thus
\begin{equation}\label{eq:mhr-1}
F^{\inv}\prn{1 - \f{1}{z}} \leq \frac{\log{z}}{c} = \bigO{\log{z}}.
\end{equation}
Furthermore, by~\eqref{eq:asymptotic-log-f}, we have
\[
\log\prn{1 - y_2} \leq -c F^{\inv}(y_2) \qquad \forall y \geq y_{2,0},
\]
where $y_{2,0} = F(x_0)$. Thus
\begin{equation}\label{eq:mhr-2}
F^{\inv}(y_2) \leq \frac{-\log\prn{1 - y_2}}{c} = \bigO{-\log{1 - y_2}}.
\end{equation}
By~\eqref{eq:mhr-1} and~\eqref{eq:mhr-2}, we have
\[
\lim_{t \to +\infty} {\frac{F^{\inv}\prn{1 - \f{1}{tx}}}{F^{\inv}\prn{1 - \f{1}{t}}}} \leq \lim_{t \to +\infty} {\frac{\log(tx)}{\log{t}}} = 1,
\]
and 
\[
\lim_{t \to 0^+} {\frac{F^{\inv}(tx)}{F^{\inv}(t)}} \leq \lim_{t \to 0^+} {\frac{-\log(1 - tx)}{-\log(1 - t)}} = x.
\]
However, by Lemma~\ref{lem:rv-hazard}, we have
\[
\lim_{t \to +\infty} {\frac{F^{\inv}\prn{1 - \f{1}{tx}}}{F^{\inv}\prn{1 - \f{1}{t}}}} = x^\gamma \qquad \forall x > 0,
\]
which implies that $\gamma \leq 0$ if $\cD \in D_\gamma$ for maxima, and 
\[
\lim_{t \to 0^+} {\frac{F^{\inv}(tx)}{F^{\inv}(t)}} = x^{-\gamma}, \qquad \forall x > 0,
\]
which implies that $-\gamma \leq 1 \iff \gamma \geq -1$ if $\cD \in D_\gamma$ for minima.
\end{proof}
