\]
so that $x_d \in [x_k - \frac{1}{2} \Delta x,\, x_k + \frac{1}{2} \Delta x)$ and $\xi = (x_d - x_k)/\Delta x \in [-\frac{1}{2},\frac{1}{2})$. Then, for $\xi \in [-\frac{1}{2},0]$, the interpolation becomes:
\begin{align}\label{eq:SL_k_intepolation}
f^{*,n+1/2}_{i,j} = f^n_j(x_d) &\approx f^n_{k,j} + \left(-\frac{1}{6} f^n_{k-2,j} + f^n_{k-1,j} - \frac{1}{2} f^n_{k,j} - \frac{1}{3} f^n_{k+1,j} \right) \xi \nonumber \\
&\quad + \left( \frac{1}{2} f^n_{k-1,j} - f^n_{k,j} + \frac{1}{2} f^n_{k+1,j} \right) \xi^2 \nonumber \\
&\quad + \left( \frac{1}{6} f^n_{k-2,j} - \frac{1}{2} f^n_{k-1,j} + \frac{1}{2} f^n_{k,j} - \frac{1}{6} f^n_{k+1,j} \right) \xi^3,
\end{align}}

\noindent for $\xi \in (0,\frac{1}{2})$, the stincel shifts be one to the right.  
To build an upwind WENO reconstruction, we rewrite the upwind polynomial as
\begin{equation}\label{eq:SL_update}
  f^{*,n+1/2}_{i,j} = f^n_{k,j} - \xi \left( \hat{f}^n_{k+1/2,j}(\xi) - \hat{f}^n_{k-1/2,j}(\xi) \right), 
\end{equation}
where $\hat{f}^n_{k+1/2,j}(\xi)$ and $\hat{f}^n_{k-1/2,j}(\xi)$ are in the form of fluxes. 
The fluxes $\hat{f}^n$ are determined by $f^n$ and depend on order of the scheme and the nonlinear WENO weights. 
{For the linear weights and $\xi \in [-\frac{1}{2},0]$, \eqref{eq:SL_update} must exactly match \eqref{eq:SL_k_intepolation}. For the remaining case $\xi \in (0,\frac{1}{2})$, corresponding to $x_d \in (x_k, x_k + \frac{1}{2}\Delta x)$, the upwind stencils are shifted one index to the right; see Figure \ref{fig:SLdespcription} for a visualization of stencil choices.}
In particular, the flux function $\hat{f}^n_{k-1/2,j}(\xi)$ will be expressed as:
\begin{equation*}
    \hat{f}^n_{k-1/2,j}(\xi) = 
    \begin{cases}
        (f^n_{k-2,j},f^n_{k-1,j},f^n_{k,j}) \, C^L_3 \, (1, |\xi|, \xi^2)^{\mathrm{T}}, \quad \xi \in [-\frac{1}{2},0]\\
        (f^n_{k-1,j},f^n_{k,j},f^n_{k+1,j}) \, C^L_3 \,(1, |\xi|, \xi^2)^{\mathrm{T}}, \quad \xi \in (0,\frac{1}{2}).
    \end{cases}
\end{equation*}
Here, the linear coefficient matrix $C^L_3$ is given by
\begin{equation}\label{eq:SL_linearmatrix}
    C^L_3 = \begin{bmatrix} -\frac{1}{6} & 0 & \frac{1}{6} \\ \frac{5}{6} & \frac{1}{2} & -\frac{1}{3} \\ \frac{1}{3} & -\frac{1}{2} & \frac{1}{6} \end{bmatrix} = \begin{bmatrix} -\frac{1}{2}\omega_1 & 0 & \frac{1}{6} \\ \frac{3}{2}\omega_1 + \frac{1}{2}\omega_2 & \frac{1}{2} & -\frac{1}{3} \\ \frac{1}{2}\omega_2 & -\frac{1}{2} & \frac{1}{6} \end{bmatrix}, 
\end{equation}
with linear weights $\omega_1 = \frac{1}{3}, \, \omega_2 = 1-\omega_1$. 
We now replace $C^L_3$ with a WENO-type nonlinear weights matrix $\tilde{C}^L_3$.  In the SL WENO context, it is important to note that it is sufficient to only apply WENO to the leading order term in the polynomial reconstruction.
Similar to the standard WENO scheme, we compute the smoothness indicators based on the chosen stencils:
 \[
\beta_1 = (f^n_{k-1,j}-f^n_{k-2,j})^2, \quad \beta_2 = (f^n_{k-1,j}-f^n_{k,j})^2.
\]
We define the nonlinear weights as ${\omega}'_1 = \omega_1\frac{1}{(\varepsilon+\beta_1)^2}$, ${\omega}'_2 = \omega_2 \frac{1}{(\varepsilon+\beta_2)^2}$. Then, we normalize them
\[
\tilde{\omega}_1 = \frac{{\omega}'_1}{{\omega}'_1+{\omega}'_2}, \quad \tilde{\omega}_2 = \frac{{\omega}'_2}{{\omega}'_1+{\omega}'_2},
\]
and substitute into \eqref{eq:SL_linearmatrix} to construct the WENO-type weights matrix $\tilde{C}^L_3$.
{We have now constructed the third-order SL WENO scheme for positive velocity $v_j > 0$. Similarly, for negative velocity $v_j < 0$, the third-order SL WENO scheme is constructed by a symmetric flip of the points used in the approximation for $v_j > 0$.}

In this paper, we use the fifth-order conservative SL WENO scheme to solve equations \eqref{eq:split_adv1}; the fifth order spatial accuracy significantly mitigates numerical diffusion with relatively coarse computational meshes \cite{gucclu2014arbitrarily}. 
