\begin{remark}
The computational cost of the above ACA-SVD procedure is mainly due to two procedures: (1) adaptive sampling of matrix entries, and (2) the SVD-based truncation. Assume that accessing each matrix entry requires \(\mathcal{O}(1)\),  the total cost of ACA sampling up to final rank \(r\) is \(\mathcal{O}(Nr)\),
where \(N = \max\{N_x, N_v\}\). 
The SVD based truncation incurs \(\mathcal{O}(Nr^2 + r^3)\) complexity, accounting for two QR factorizations of size \(N \times r\) and one SVD on the reduced \(r \times r\) core. These lead to a total computational complexity that scales linearly with \(N\), provided that the numerical rank \(r\) remains moderate and is independent of $N$.
\end{remark}

\begin{remark}
The initial sample size \(p\) used in {Phase I} of ACA is a user-defined parameter. Larger values of \(p\) typically improve the robustness and accuracy of the ACA procedure. In our implementation, we set \(p = 12\). The refinement strategy also differs from the classical ACA formulation in~\cite[Algorithm 2]{dolgov2020parallel}: we do not impose the rook pivoting condition, which would require selecting the global maximum within both the corresponding row and column. Such a condition is computationally prohibitive in our setting, as accessing individual matrix entries requires invoking local numerical PDE solvers. In practice, we find that searching a pivot along a column, followed by a row yields stable and accurate results.
\end{remark}




\subsubsection{New adaptive-rank Wigner–Poisson solver}
\label{subsec:NewLR_WP}

We now integrate all previously introduced components to construct the adaptive-rank Wigner–Poisson solver, which is presented in Algorithm~\ref{alg:LR-WP solver}. 
The method is built upon the full-rank solver presented in Section~\ref{subsec:SSmethod} (Algorithm~\ref{alg:fullrank-WP solver}), but reformulates each substep into an adaptive-rank framework by applying the ACA-SVD compression strategy introduced in Section~\ref{sec:ACA-SVD}. The numerical solution is represented in SVD form $\mathbf{F}^l = U^l \Sigma^l (V^l)^\mathrm{T}$ for $l \in \{(*,n+1/2), (*,n+1),n,n+1\}$, where $\Sigma^l$ is diagonal. 
In addition, a structure-preserving modification is incorporated into the ACA stage of the Fourier update to ensure real-valued solutions, \Cref{subsec:structure-preserving}. 

Below we highlight essential components of Algorithm~\ref{alg:LR-WP solver}:
\begin{enumerate}
   % \item \sout{The same spatial and velocity discretizations are used as in Algorithm~\ref{alg:fullrank-WP solver}. At each time step, the numerical solution is represented in SVD form $\mathbf{F}^l = U^l \Sigma^l (V^l)^\mathrm{T}$ for $l \in \{(*,n+1/2), (*,n+1),n,n+1\}$, where $\Sigma^l$ is diagonal. An additional superscript $C$ (e.g., $\mathbf{F}^{n+1,C}$) indicates mass-conservative solutions after Lagrange correction.}\JQ{i move part of this up... and suggest to remove this item.}
    \item \textbf{Step 1} combines the full rank SL WENO scheme with the ACA-SVD compression. The function handle to access the matrix entry is defined by evaluating the WENO update formula~\eqref{eqn:SL_matrix} at the corresponding characteristic trace back point. The ACA-SVD algorithm described in Section~\ref{sec:ACA-SVD} is applied to obtain $\mathbf{F}^{*,n+1/2} = U^{*,n+1/2} \Sigma^{*,n+1/2} (V^{*,n+1/2})^\mathrm{T}$ in a low rank decomposition format. 

    \item \textbf{Step 2} solves the Poisson equation using the same method as in Algorithm~\ref{alg:fullrank-WP solver}, but with the source term computed with low rank complexity from the SVD representation $\mathbf{F}^{*,n+1/2}$.

    \item \textbf{Step 3} performs the Fourier update under adaptive rank framework. First, the FFT is applied column-wise to the right singular factor $V^{*,n+1/2}$, yielding $\tilde{\mathbf{F}}^{*,n+1/2} = U^{*,n+1/2} \Sigma^{*,n+1/2} \left( \mathcal{F}(V^{*,n+1/2}) \right)^{\mathrm{T}}$.
    The function handle to access the matrix is defined using  ~\eqref{eqn:FFT_matrix}.
    Then the ACA-SVD algorithm is applied to obtain the Fourier update $\tilde{\mathbf{F}}^{*,n+1} = U^{*,n+1} \Sigma^{*,n+1} \left(\tilde{V}^{*,n+1} \right)^{\mathrm{T}}$.
   % with a sampling modification. %formula~\eqref{eqn:FFT_matrix} using this transformed factor.
    To preserve conjugate symmetry, the procedure of the ACA column selection is modified: for each selected column index $j$, its symmetric counterpart
    \begin{equation}\label{eq:symmetric_column_pair}
    j_{\text{opp}} = \mod((N_v + 1 - j), N_v) + 1    
    \end{equation}
    is also included. This guarantees that the resulting CUR approximation respects conjugate symmetry, as proven in Theorem~\ref{thm:structure-preserving}. 
    %\SG{Denote $\tilde{\mathbf{F}}^{*,n+1} = U^{*,n+1} \Sigma^{*,n+1} \left(\tilde{V}^{*,n+1} \right)^{\mathrm{T}}$. 
    After we construct $\tilde{\mathbf{F}}^{*,n+1}$, the inverse FFT is applied column-wise to the right singular factor $\tilde{V}^{*,n+1}$, giving the  
    %obtain a 
    real-valued representation $\mathbf{F}^{*,n+1}$ (up to machine precision):
    \[
    \mathbf{F}^{*,n+1} = U^{*,n+1} \Sigma^{*,n+1} \left( \mathcal{F}^{-1}(\tilde{V}^{*,n+1}) \right)^{\mathrm{T}}.
    \]
    \item \textbf{Step 4} applies another ACA-SVD semi-Lagrangian update, starting from $\mathbf{F}^{*,n+1}$ to compute $\mathbf{F}^{n+1} = U^{n+1} \Sigma^{n+1} (V^{n+1})^{\mathrm{T}}$. The total mass is directly computed from its SVD factors:
    \begin{equation}\label{eq:total_mass_low_rank}
    L^{n+1,*} = \sum_{k=1}^{r} \Sigma(k,k) \left( \sum_{i=1}^{N_x} U(i,k) \Delta x \right) \left( \sum_{j=1}^{N_v} V(j,k) \Delta v \right).
    \end{equation}

    \item \textbf{Step 5} applies a Lagrange multiplier correction to enforce mass conservation:
    \[
    \mathbf{F}^{n+1,C} = U^{n+1} \left( \Sigma^{n+1} \cdot \frac{L_x}{L^{n+1,*}} \right) (V^{n+1})^\mathrm{T}.
    \]
\end{enumerate}

\begin{algorithm}
\caption{Algorithm: Adaptive-Rank Wigner–Poisson Solver with ACA-SVD Compression}
\label{alg:LR-WP solver}
\begin{algorithmic}[1]
\Require Spatial discretization \eqref{eqn:spatial_dis}, velocity discretization \eqref{eqn:velocity_dis}, and initial condition represented as SVD form $\mathbf{F}^{0,C} = U^0 \Sigma^0 (V^0)^\mathrm{T}$ (default SVD tolerance $\varepsilon_s=10^{-3}$). {$\Phi^{n+1/2}_i$ represents the potential approximation at $(x_i,(n+1/2)\Delta t)$.} 
\While{$t < T$}
    \State \textbf{Step 1: Semi-Lagrangian with ACA-SVD.} Use~\eqref{eqn:SL_matrix} as function handle; apply ACA-SVD to obtain $\mathbf{F}^{*,n+1/2}$.
    \State \textbf{Step 2: Solve $\Phi^{n+1/2}$ from the Poisson.} Compute density from $\mathbf{F}^{*,n+1/2}$ by summation; solve Poisson equation to obtain $\Phi^{n+1/2}$. 
    \State \textbf{Step 3: Fourier Update with Modified ACA-SVD.} 
    \State Apply FFT column-wise to $V^{*,n+1/2}$ to obtain $\tilde{\mathbf{F}}^{*,n+1/2}$. 
    \State Apply ACA-SVD to \eqref{eqn:FFT_matrix} with symmetric column pairing \eqref{eq:symmetric_column_pair} to obtain $\tilde{\mathbf{F}}^{*,n+1} = U^{*,n+1} \Sigma^{*,n+1} \left(\tilde{V}^{*,n+1} \right)^{\mathrm{T}}$.
    \State {Apply inverse FFT column-wise to the right singular factor $\tilde{V}^{*,n+1}$ to recover real-valued $\mathbf{F}^{*,n+1}$.}
    \State \textbf{Step 4: Second Semi-Lagrangian with ACA-SVD.} 
    \State Repeat Step 1 starting from $\mathbf{F}^{*,n+1}$ to obtain $\mathbf{F}^{n+1} = U^{n+1} \Sigma^{n+1} (V^{n+1})^\mathrm{T}$.
    \State Compute total mass $L^{n+1,*}$ of  $\mathbf{F}^{n+1}$ as defined in~\eqref{eq:total_mass_low_rank}.

    \State \textbf{Step 5: Density Correction.} Apply Lagrange correction:
    \[
    \mathbf{F}^{n+1,C} = U^{n+1} \left( \Sigma^{n+1} \cdot \frac{L_x}{L^{n+1,*}} \right) (V^{n+1})^\mathrm{T}.
    \]
    \State $t \gets t + \Delta t$
\EndWhile
\end{algorithmic}
\end{algorithm}



