To generate one set of re-scaled data samples for augmentation, the procedure is applied to the series in the dataset with a fixed value of $s$. Algorithm~\ref{alg:amda} summarizes the \texttt{AMDA} method.

\begin{algorithm}[t]
\small
\caption{Appliance-Modulated Data Augmentation (\texttt{AMDA})}
\begin{algorithmic}[1]
\Procedure{\texttt{AMDA}}{Dataset, $s$}
    \For{each appliance \( i \) in Dataset}
        \State Compute \( p_{i} \leftarrow \dfrac{P_{\text{total},i}}{P_{\text{total}}} \) \Comment{Relative contribution}
        \State Compute \( S_i \leftarrow s \cdot (1 - p_{i}) \) \Comment{Scaling factor}
        \State Scale signal \( \tilde{x}_{i,t} \leftarrow S_i \cdot x_{i,t} \)
    \EndFor
    \State Merge all \( \tilde{x}_{i,t} \) to form augmented aggregate signal
    \State Combine augmented signals with the original dataset 
\EndProcedure
\end{algorithmic}
\label{alg:amda}
\end{algorithm}

