    \subfloat[\label{fig2a}Noisy data $f$]{\includegraphics[width=0.31\textwidth]{data_noise}}
    \quad
    \subfloat[\label{fig2b}True function $\Re e(u^*)$]{\includegraphics[width=0.31\textwidth]{real_true}}
    \quad
    \subfloat[\label{fig2c}Reconstructed function $\Re e(u)$]{\includegraphics[width=0.31\textwidth]{real_phase}}

    \subfloat[\label{fig2d}True function $\Im m(u^*)$]{\includegraphics[width=0.32\textwidth]{imag_true}}
    \quad
