 \begin{algorithm}[H]
   \caption{Error-free transformation for the summation of two floating-point numbers.}
   \label[algorithm]{alg:TwoSum}
    \SetKwProg{Fn}{Function}{}{}
    \KwIn{$a,b$ are two floating-point numbers.}
    \KwOut{$r,s$ are the result and the error, resp.}
    \Fn{$[r, s]$ = \rm\texttt{twosum}\,($a, b$)} {
      $r \becomes a + b$\\
      $z \becomes r - a$\\
      $s \becomes (a - (r - z)) + (b - z)$
    }
 \end{algorithm}
