        \begin{align}
        \pi_{2} & = 1 - \left( 1- \frac{\lambda}{r (\gamma \bar{\ee} + \mu \ee)} \pi_{1}  \right)^{\frac{1}{d}}.     \end{align}
        Similarly, for $i\geq 2$, by expanding the expression for $\bar{\pi}_i^d$ in \eqref{eq:FP_eq2} we obtain \eqref{eq:eqm-solution-flows}.

        Next, we show that the equilibrium state that we found satisfies $\sum_{i\geq 1}\pi_i<\infty$. It suffices to show that $\pi_i\leq \pi^*_i$ by induction on $i \ge 1$, where $(\pi^*,\ee^*)$ is the equilibrium state of the mean-field when $d=1$, and $\pi^*=(\pi^*_i,i\geq 0)$. Furthermore, it can be checked that $\sum_{i\geq 1}\pi^*_i=\frac{\rho}{1-\rho}$ where $\rho=\frac{\lambda}{r(\gamma\bar{\ee}+\mu\ee)}$. Observe that $1-p^{\frac{1}{d}}\leq 1-p$ for any $p \in [0, 1]$ and $d \in \bb{N}$. For the base case, we get
        \begin{align}
            \pi_{1} & = 1 - \left( 1- \frac{\lambda}{r (\gamma \bar{\ee} + \mu \ee)
            }  \right)^{\frac{1}{d}}\\
            & \leq 1 - \left( 1- \frac{\lambda}{r (\gamma \bar{\ee} + \mu \ee)}   \right)\\
            & = \frac{\lambda}{r (\gamma \bar{\ee} + \mu \ee)}=\pi^*_1.
        \end{align}
        For the inductive step, we can rewrite \eqref{eq:eqm-solution-flows} and get
        \begin{align}
            \pi_{i+1} & = 1 - \left( 1- \frac{\lambda}{r (\gamma \bar{\ee} + \mu \ee)} \pi_i \right)^{\frac{1}{d}}\\
            & \leq 1 - \left( 1- \frac{\lambda}{r (\gamma \bar{\ee} + \mu \ee)}\pi_i \right)\\
            & \leq \frac{\lambda}{r (\gamma \bar{\ee} + \mu \ee)}\pi^*_i = \pi^*_{i+1}.
        \end{align}
        Thus, $\pi_{i+1} \le \pi_{i+1}^{*}$ whenever $\pi_{i} \le \pi_{i}^{*}$ as desired.
\end{proof}


