\end{figure}
Now, we consider the following random dynamical system:
\begin{align}\label{eq:random_system}
    \begin{cases}
        E_h \partial_t \y_R(\boldsymbol{\omega}, t) + R_{rb}(\boldsymbol{\omega}, t)\y_R(\boldsymbol{\omega},t) = \f_h, & t \in (0,T), \\
        E_h \y_R(0) =  \y^0_h,
    \end{cases}
\end{align}
where $\y^0_h$ and $\f_h$ are the same initial condition and source term as in \eqref{eq:fem_system}, respectively.

Following \cite{MR4433122}, we can prove that $\y_R(\boldsymbol{\omega}, t)$ approximates the solution $\y_h$ of equation \eqref{eq:fem_system} in expectation as $\delta \to 0$. Specifically, setting
\begin{align}\label{eq:def_var_A}
\text{Var}[ R_{rb}] := \sum_{i=1}^{2^M} \left( \left\|R_h - \sum_{m \in S_i} \frac{R_{h,m}}{\pi_m} \right\|^2 p_i \right),
\end{align}
where $\|\cdot\|$ denotes the $l^2$-norm, the following theorem holds:

\begin{theorem}\label{Th:RBM_1}
Let $\y_h$ and $\y_R$ denote the solutions of \eqref{eq:fem_system} and \eqref{eq:random_system}, respectively. Then, for every $t \in (0,T)$, we have  
\begin{align}\label{eq:estimation_2}
    \mathbb{E}\left[\|\y_h(t) - \y_R(t)\|^2\right]\leq \left(\|E_h^{-1}R_h\|T^2 + 2T)(\| E_h^{-1}\y^0_h\| +\|E_h^{-1}\f_h\|_{L^1(0,T;\mathbb{R}^N)}\right)^2 {\frac{\text{Var}[ R_{rb}]}{\lambda_{min}^2(E_h)}} \,\delta,
\end{align}
where $\lambda_{min}(E_h)$ denotes the minimum eigenvalues of $E_h$.
\end{theorem}

\bigbreak
\begin{remark}\label{remark:mass_matrix} 
Regarding the previous theorem, the following comments are in order:
\begin{enumerate}
\item[1.] 
     In \cite[Theorem 1]{MR4433122}, the matrix $E_h$ is considered as the identity matrix. However, since $E_h$ is invertible, by multiplying \eqref{eq:random_system} by $E_h^{-1}$, and considering that $\|E_h^{-1}\|=(\lambda_{\min}(E_h))^{-1}$, estimation \eqref{eq:estimation_2} follows.



\item[2.] In this approach, we choose to keep the matrix $E_h$ in \eqref{eq:fem_system} instead of multiplying the system by $E^{-1}_h$, which would yield an equivalent system with the dynamics matrix $E^{-1}_h R_h$. Therefore, \Cref{Th:RBM_1} could be applied in this setting as well. However, note that, in the first case, namely, in the setting we have chosen, the matrix to be decomposed is $R_h$, whereas in the second one, it would be $E^{-1}_h R_h$. Our primary motivation for the first choice, decomposing $R_h$, is to keep the analogy with the RBM for PDEs on graphs. When dealing with the discretization of PDEs on graphs, both $R_h$ and $E_h$ exhibit a block diagonal structure, each block corresponding to the dynamics on a subgraph (see \Cref{subsec:numerics_equation}). Therefore, leveraging domain decomposition, a natural decomposition of $R_h$ can be achieved by utilizing submatrices associated to each block. In contrast, when we chose the second approach, due to the presence of the matrix $E^{-1}_h R_h$, it results in a dense matrix that lacks any block-diagonal structure or clear domain-based interpretation.  Moreover, as described in \Cref{remark:computational_efficiency}, in our approach, decomposing $R_h$ leads to an algorithm in which it is only necessary to solve a PDE on a subgraph at each RBM step.


    \item[3.] According to \cite[Theorem 2]{MR4433122}, \Cref{Th:RBM_1} still holds when we replace ${\f_h}$ with a random counterpart $\f_{rb}(\bomega)$ in the random system \eqref{eq:fem_system}, provided that $\E[\f_{rb} ]= \f_h$.

\end{enumerate}
\end{remark}
In \cite{MR4433122}, the Random Batch Method (RBM) was also adapted to address optimal control problems.

Specifically, let $Q,\,D \in \R^{N\times N}$ be two symmetric and positive definite matrices, and let $\y_d\in \R^N$ be a given target. Denote by $\| \boldsymbol{v} \|_{Q}^2 := \langle \boldsymbol{v}, Q \boldsymbol{v} \rangle$ and $\|\boldsymbol{v}\|_D^2 := \langle \boldsymbol{v}, D \boldsymbol{v} \rangle$ for $\boldsymbol{v} \in \R^N$, and consider the optimal control problem
\begin{align}\label{eq:dis_optimal_control}
    \min_{{\f_h} \in L^2(0,T;\mathbb{R}^N)} \left\{ J_{D,Q}({\f_h})= \frac{1}{2} \int_0^T \left( \| {\f_h}(t)\|^2_{D} + \|\y_h(t) - \y_d\|^2_{Q} \right) dt\right\},
\end{align}
where $\y_h$ is the solution of \eqref{eq:fem_system} with the right-hand side ${\f_h}$. A unique optimal pair $(\y_h,{\f_h})$ solving \eqref{eq:dis_optimal_control} exists (\cite[Section 1.4]{MR2583281}). 

Additionally, consider the $\bomega$-dependent optimal control problem
\begin{align}\label{eq:random_optimal_control}
    \min_{{\f_R}(\bomega) \in L^2(0,T;\mathbb{R}^N)} \left\{ J^R_{D,Q}({\f_R}(\bomega))= \frac{1}{2} \int_0^T \left( \| {\f_R}(t)\|^2_{D} + \|\y_R(t) - \y_d\|^2_{Q} \right) dt\right\},
\end{align}
where $\y_R$ is the solution of the random dynamics \eqref{eq:random_system} with the right-hand side given by ${\f_R}(\bomega)$. For each realization of $\bomega$, a unique optimal pair $(\y_R(\bomega),\f_R(\bomega))$ exists.

 From \cite[Theorem 4]{MR4433122}, the following holds:
\begin{theorem}\label{th:rbm_optimal_control}
Let $(\y_h, {\f_h})$ and $(\y_R, {\f_R})$ denote the optimal pairs of the optimal control problems \eqref{eq:dis_optimal_control} and \eqref{eq:random_optimal_control}, respectively. Then, the following inequality holds:
\begin{align}\label{eq:estimation_oc_fin}
   \E[ \|{\f_h}(t) - {\f_R}(t)\|^2] + \E[\|\y_h(t) - \y_R(t)\|^2]\leq C_{oc}(1+\|E^{-1}_h\|^2T) {\frac{\text{Var}[ R_{rb}]}{\lambda_{min}^2(D)\lambda_{min}^2(E_h)} }\delta,
\end{align}
for every $t \in (0,T)$, where $ \lambda_{min}(D)$ and $\lambda_{min}(E_h)$ denotes the smaller eigenvalues of $D$ and $E_h$ respectively. The constant $C_{oc}>0$ in \eqref{eq:estimation_oc_fin} (whose subscript $oc$ refers to ``optimal control") is given by 
\begin{align}\label{eq:constant_C_oc}
    C_{oc}= 2\|D\|^2  \left((1+T)(\|E^{-1}_h \y^0\| + \|E^{-1}_h \f_h\|)^2 + \|\y_d\|^2 \right)\|E^{-1}_h\|^2
    (\|E^{-1}_hR_h\|T^2+2T).
\end{align}
\end{theorem}
Here, the constant $C_{oc}$ in \eqref{eq:constant_C_oc} is obtained after carefully tracking the proofs in \cite{MR4433122}.

\section{Approximation by the Random Batch Method}\label{sec:main_results}

\subsection{Approximation of the Heat Equation via the RBM}
Let us consider the basis functions $\{\phi_j\}_{j=1}^N$ of the space $V_{h}$ introduced in \Cref{section_FEM}. Let $\y_R(\bomega, t) \in \R^N$ be the solution of \eqref{eq:random_system}, and denote by
\begin{align}\label{eq:definition_yR}
y_R(x,t,\bomega) := \sum_{j=1}^N(\y_R)_j(\bomega,t)\phi_j(x),
\end{align}
where $(\y_R)_j$ denotes the $j$-th coordinate of $\y_R(\bomega, t)$ on the basis of $V_{h}$. 

In the following, to simplify the presentation,  we assume that the matrices $\{R_{h,m}\}_{m=1}^M$ are such that $R_{h,m} = R_m / h$ for all $m \in \{1, \dots, M\}$, where each $R_m$ is an $N \times N$ matrix whose entries are independent of $h$. This is the structure of the matrix $R_h$ itself. In this setting, the following result holds: 

\begin{theorem}\label{th:convergence_RBM_FE}
Let $y_R$ be as in \eqref{eq:definition_yR} and let $y$ be the solution of \eqref{eq:heat_eq} with initial condition $y^0 \in H^1_0(0,L)$ and $f \in L^2(0,T;L^2(0,L))$. Then, for $h < \sqrt{6T}$ given, we have
\begin{align}\label{eq:estim_app_heat}
\E[\|y_R(t) - y(t)\|_{L^2(0,L)}^2] \leq C\left(h^4 + \frac{\delta}{h^7}C(M)\right),
\end{align}
for every $t \in (0,T)$, where $C$ and $C(M)$ are two positive constants independent of $h$ and $\delta$, with $C(M)$ depending on the chosen decomposition and $\delta$ being the RBM parameter introduced in \Cref{sec:rbm}.
\end{theorem}
\begin{remark}
    To ensure the convergence of the error in \eqref{eq:estim_app_heat}, it is sufficient for $\delta$ to be small relative to $h$. In particular, taking $\delta = h^{7+\alpha}$, for some $\alpha>0$, we deduce a convergence of order $h^\alpha$. This is illustrated in \Cref{sec:overlapping_dec}.
\end{remark}


\begin{proof}
Given  that $R_h=R/h$ and $R_{h,m} = R_m / h$ with $R$ and $R_m$ being $N \times N$ matrices with entries independent of $h$, we have
\begin{align}\label{eq:estimation_var_a}
    \text{Var}[ R_{rb}]=\sum_{i=1}^{2^M} \left( \left\|R_h - \sum_{m \in S_i} \frac{R_{h,m}}{\pi_m} \right\|^2 p_i \right) \leq \frac{1}{h^2} \sum_{i=1}^{2^M} \left( \left\|R - \sum_{m \in S_i} \frac{R_m}{\pi_m} \right\|^2 p_i \right) = \frac{C(M)}{h^2},
\end{align}
where the constant $C(M)$ is independent of $h$. On the other hand, since $E_h$ is a tridiagonal Toeplitz matrix, its spectrum can be computed explicitly and, according to \cite{tridiagonal}, its smallest eigenvalue is given by 
\begin{align}\label{eq:min_eigen_E}
    \lambda_{\min}(E_h) = h\left(\frac{2}{3} + \frac{1}{3}\cos\left(\frac{N\pi}{N+1}\right)\right) > \frac{h}{3}.
\end{align}
Now observe that, since $(\f_h)_j = (f, \phi_j)_{L^2(0,L)}$, we have 
\begin{align*}
    \|\f_h\| &= \left(\sum_{j=1}^N |(f,\phi_j)_{L^2(0,L)}|^2\right)^{1/2}\leq \|f\|_{L^2(0,L)} \left( \sum_{j=1}^N \|\phi_j\|_{L^2(0,L)}^2 \right)^{1/2} \leq \|f\|_{L^2(0,L)} \left(\frac{2}{3}(L-h) \right)^{1/2}.
\end{align*}
Here, we have used that $\|\phi_j\|_{L^2(0,L)}^2 = 2h/3$ for every $j \in \{1,\dots,N\}$ and that $Nh=L-h$. Since $h < L$ and $\|E_h^{-1}\|=1/\lambda_{\min}(E_h)$, we obtain 
\begin{align}\label{eq:estimation_Ef}
    \|E_h^{-1} \f_h\| \leq  \frac{3L^{1/2}\|f\|_{L^2(0,L)}}{h},
\end{align}
and, similarly, 
\begin{align}\label{eq:estimation_y0}\|E_h^{-1}\y^0_h\| \leq \frac{3L^{1/2}\|y^0\|_{L^2(0,L)}}{h}.
\end{align}
Moreover, since  $\|R_h\| \leq 4/h$ and $h < \sqrt{6T}$, we obtain 
\begin{align}\label{eq:estimation_Ah_T}
(\|E^{-1}_hR_h\|T^2 + 2T) \leq \frac{24T^2}{h^2}.
\end{align}
Estimate \eqref{eq:estim_app_heat} can now be established with the aid of  $y_h$, solution of   \eqref{eq:def_yh_fem}. Applying \Cref{th:fin_elem1}, we deduce that
\begin{align}\label{eq:estimation_teo32}
\nonumber \|y_R(t,\bomega) - y(t)\|_{L^2(0,L)}^2 &\leq 2\left(\|y_R(t,\bomega) - y_h(t)\|_{L^2(0,L)}^2 + \|y_h(t) - y(t)\|_{L^2(0,L)}^2 \right)\\
     & \leq \frac{4h}{3} \|\y_R(t,\bomega) - \y_h(t)\|^2  + Ch^4.
\end{align}
Taking the expectation in \eqref{eq:estimation_teo32},  applying \Cref{Th:RBM_1} and  estimates \eqref{eq:estimation_var_a}, \eqref{eq:min_eigen_E},  \eqref{eq:estimation_Ef}, \eqref{eq:estimation_y0}, and \eqref{eq:estimation_Ah_T} the proof is concluded.
\end{proof}



\begin{remark}\label{remark:conv_ht_hx}
Several remarks are in order:
\begin{enumerate}
    \item[1.] The factor $h^7$ dividing in \eqref{eq:estim_app_heat} arises due to the fact that the right-hand side of \eqref{eq:estimation_2} depends on the $l^2$-norm of the matrices $R_h$ and $E_h^{-1}$, and $1/\lambda_{\min}(E_h)$, where each is of the order $1/h$. Also $Var[R_{rb}]$ depends on $1/h^2$. This leads us to the dividing factor $h^7$.


    \item[2.] Note that when $h$ approaches zero, the discretized PDE becomes closer to the original PDE; however, if $\delta$ is fixed and $h$ decreases, the RBM departs from the discretized PDE since the size of the problem increases. The condition $\delta=O(h^7)$ is needed to ensure that the RBM remains close to the discretized PDE and, therefore, to the original PDE when $h$ approaches zero.

    \item[3.] The multiplicative constant $C(M)$ in \eqref{eq:estimation_var_a} plays a relevant role in the error estimate  \eqref{eq:estim_app_heat}, since it amplifies the error term   $\delta/h^7$. Consequently, minimizing $C(M)$ is a relevant objective in our setting, as it directly impacts the overall efficiency of the method. Moreover, the value of $C(M)$ is closely linked to the way the matrix $R_h$ is decomposed -- an aspect we further elaborate on in \Cref{sec:c_and_o}. In particular, when $M = 1$, the RBM reduces to the standard FEM approximation, and in this case we have $C(M) = 0$.

    \item[4.] By Theorem \ref{th:convergence_RBM_FE} we have that the variance 
    \begin{align*}
        \mathbb{V}[\|y_R(t)-y(t)\|]:=\mathbb{E}[\|y_R(t)-y(t)\|^2] -\left(\mathbb{E}[\|y_R(t)-y(t)\|]\right)^2\leq C\left(h^4 + \frac{\delta}{h^7}C(M)\right).
    \end{align*}
    Moreover, Markov’s inequality yields, for any $\varepsilon>0$,
    \begin{align*}
        \mathbb{P}(\|y_R(t)-y(t)\|^2>\varepsilon)\leq \frac{C}{\varepsilon}\left(h^4 + \frac{\delta}{h^7}C(M)\right).
    \end{align*}
    Therefore, whenever $C\left(h^4 + \delta/h^7C(M)\right)$ is small, not only the mean‐square error but also the variance and the probability of large deviations are uniformly small. In this regime, a single realization of the scheme suffices to approximate the expected error with high probability.



    \item[5.] The analysis in Theorems \ref{th:convergence_RBM_FE} and \ref{th:conver_optimal_control} (below) can be adapted and applied to the finite difference method (FDM). However, obtaining estimates similar to \eqref{eq:estimation_finite_elements} with the FDM, requires smoother data to ensure that $y \in L^2(0,T;C^4(0,L))$ (see, for instance,  \cite[Theorem 16.5]{MR2478556}, where the convergence error for the FDM depends on $\|\partial_x^4 y\|_{L^2(0,T;C(0,L))}$).
\end{enumerate}
\end{remark}


\subsection{Application to Optimal Control}\label{eq:discrete_ocp}
In this section, we prove the convergence of the RBM in the context of optimal control for the heat equation; we employ a discrete approach. Namely, we first discretize the PDE to later apply the RBM. Let $y_d \in H_0^1(0,L)$ be a given target, and consider the optimal control problem 
\begin{align}\label{eq:optimal_control}
      \min_{f \in L^2(0,T;L^2(0,L))} \left\{ J(f)= \frac{1}{2} \int_0^T \left( \|f(t)\|^2_{L^2(0,L)} + \|y(t) - y_d\|_{L^2(0,L)}^2 \right) dt\right\},
\end{align}
where  $y$ is the solution of \eqref{eq:heat_eq} with right-hand side $f$. According to \cite[Chapter 3]{MR2583281}, there exists a unique optimal pair $(y, f)$ for \eqref{eq:optimal_control}. To approximate the optimal control problem \eqref{eq:optimal_control}, we can consider the finite-dimensional problem 
\begin{align}\label{eq:finite_dim_ffunctional}
  \min_{f_h\in L^2(0,T;L^2(0,L))} \left\{ J_h(f_h)= \int_0^T \left(\|f_h(t)\|^2_{L^2(0,L)}+\|y_h(t)-y_d \|^2_{L^2(0,L)} \right) dt \right\},
\end{align}
where $y_h$ is the solution of \eqref{eq:variational_fem} with right-hand side $f_h$. The convergence of the FEM in this context, is assured by the following result in \cite{MR1119274}.

\begin{theorem}\label{th:conver_optimal_control} 
    Let $(y,f)$ denote the optimal pair of \eqref{eq:optimal_control} with $y^0,\,y_d\in H_0^1(0,L)$, and let $(y_h,f_h)$ denote the optimal pair of \eqref{eq:finite_dim_ffunctional}. Then, there exists a constant $C>0$, independent of $h>0$, such that 
    \begin{align*}
        \|y_h(t)-y(t)\|_{L^2(0,L)}^2 + \|f_h(t)-f(t)\|_{L^2(0,L)}^2 \leq C h^4 \left(\frac{T}{t(T-t)} + \ln\left(\frac{1}{h}\right)\right)^2,
    \end{align*}
    for every $t \in (0,T)$.
\end{theorem}
Denote by $(\y_h, \f_h)$ the vectors of coefficients of $(y_h, f_h)$. Observe that 
\begin{align}\label{eq:characterization_norm_l2}
    \|y_h(t)\|^2_{L^2(0,L)} = \left\|\sum_{j=1}^N y_j(t) \phi_j\right\|^2_{L^2(0,L)} = \|\y_h\|^2_{E_h} = \langle E_h \y_h, \y_h \rangle,
\end{align}
where $E_h$ corresponds to the mass matrix introduced in \eqref{eq:stiffness_mass_matrices}. Therefore, when $D = Q = E_h$, then $(\y_h, \f_h)$ corresponds to the optimal pair of the finite-dimensional problem \eqref{eq:dis_optimal_control} restricted to the system \eqref{eq:fem_system}, with $\y_d$ taken as the vector of coefficients of the projection of $y_d$ onto $V_h$. 

Let us denote by $(\y_R, \f_R)$ the optimal pair of the random optimal control problem \eqref{eq:random_optimal_control} restricted to \eqref{eq:random_system}, and denote by $(y_R, f_R)$ its projection onto $V_h$. Then, we have the following theorem.
\begin{theorem}\label{th:op_random_approximation}
    Let $(y, f)$ denote the optimal pair of \eqref{eq:optimal_control} with $y^0,\,y_d \in H_0^1(0,L)$, and let $(y_R, f_R)$ be as given above. Then, there exists a constant $C > 0$, independent of $h$ and $\delta$, such that 
    \begin{align}\label{eq:estim_opt_control_heat_rand}
        \E\left[\|y_R(t) - y(t)\|_{L^2(0,L)}^2\right] + \E\left[\|f_R(t) - f(t)\|_{L^2(0,L)}^2\right] \leq
        C\left(\frac{\delta}{h^{11}} C(M) + h^4 \left(\frac{T}{t(T-t)} + \ln\left(\frac{1}{h}\right)\right)^2\right),
    \end{align}
    for every $t \in (0,T)$, where $C(M)$ is the same constant as in \Cref{th:convergence_RBM_FE}.
\end{theorem}

\begin{proof}
    Applying \Cref{th:conver_optimal_control} and using the fact that $\|\phi_j\|_{L^2(0,L)}^2 = 2h/3   $, we obtain
    \begin{align*}
        \E\left[\|y_R(t) - y(t)\|_{L^2(0,L)}^2\right] &\leq \E\left[\|y_R(t) - y_h(t)\|_{L^2(0,L)}^2\right] + \E\left[\|y_h(t) - y(t)\|_{L^2(0,L)}^2\right] \\
        &\leq \E\left[\sum_{j=1}^N \|(\y_R)_j(t) - (\y_h)_j(t)\|^2\right] \|\phi_j\|_{L^2(0,L)}^2 + Ch^4 \left(\frac{T}{t(T-t)} + \ln\left(\frac{1}{h}\right)\right)^2 \\
        &\leq \E\left[\|\y_R(t) - \y_h(t)\|^2\right] \frac{3h}{2} + Ch^4 \left(\frac{T}{t(T-t)} + \ln\left(\frac{1}{h}\right)\right)^2 .
    \end{align*}

    To estimate the first term on the right-hand side, we will use \Cref{th:rbm_optimal_control}. Recall that $D = E_h$, $\|E_h^{-1}\| = 1/\lambda_{\min}(E_h)$, and the estimations \eqref{eq:min_eigen_E}, \eqref{eq:estimation_Ef}, and \eqref{eq:estimation_y0}. Then, we deduce that the constant $C_{oc}$ from \eqref{eq:constant_C_oc} is bounded by
    \begin{align}\label{estima_1_oc}
        C_{oc} \leq C h^2 \left( (1 + T) \left(\frac{1}{h^2} + \frac{1}{h^2} + 1 \right) \frac{1}{h^2} \left(\frac{T^2}{h^2} + 2T\right) \right) \leq \frac{C_1}{h^4},
    \end{align}
    where $C_1$ is independent of $h$ and the decomposition of $R_h$. Analogous to \eqref{eq:estimation_var_a}, we have that
    \begin{align}\label{estima_2_oc}
        (1 + \|E_h^{-1}\|^2 T) \frac{\text{Var}[R_{rb}]}{\lambda_{\min}^4(E_h)} \leq \frac{C(M)}{h^8},
    \end{align}
    where $C(M)$ is defined as in \eqref{eq:estimation_var_a}. Then, by combining \Cref{th:rbm_optimal_control} with the estimates \eqref{estima_1_oc} and \eqref{estima_2_oc}, we deduce \eqref{eq:estim_opt_control_heat_rand}
    \begin{align}\label{eq:all_contrant_h11}
        \E[\|\y_h(t) - \y_R(t)\|^2] \frac{3h}{2}\leq C_{oc}(1+\|E^{-1}_h\|^2T) \frac{\text{Var}[ R_{rb}]}{\lambda_{min}^4(E_h)} \delta\leq\frac{C_1C(M)\delta}{h^{11}}.
    \end{align}
Performing an analogous computation for the expectation of the differences in the optimal controls yields the same upper bound.
\end{proof}

\begin{remark} 
    Note the following:
    \begin{enumerate}
       \item[1.] Whereas \Cref{th:convergence_RBM_FE} yields a denominator of order $h^{7}$, \Cref{th:op_random_approximation} leads to a higher-order term of $h^{11}$. This additional factor originates from \Cref{th:rbm_optimal_control}, which -- unlike \eqref{eq:estimation_2} -- introduces extra constants of order $h^{-1}$. When these contributions are propagated through the estimates in \eqref{estima_1_oc} and \eqref{estima_2_oc}, they accumulate, resulting in the overall $h^{11}$ dependence in the denominator, as demonstrated in \eqref{eq:all_contrant_h11}.

        \item[2.] Similar to \Cref{remark:conv_ht_hx}, by taking $\delta = h^{11+\varepsilon}$, we guarantee a convergence rate $h^{\varepsilon}$.
        \item[3.] The logarithmic factor in Theorem~\ref{th:op_random_approximation} arises from our reliance on Theorem~\ref{th:conver_optimal_control} (originally from \cite{MR1119274}) as an intermediate estimate. In that result, the authors show that the semigroup error satisfies
\begin{align}
\|\mathcal{T}(t)-\mathcal{T}_h(t)P_h\|_{\mathcal{L}(L^2(0,1))}
&\le c_1,e^{c_2,(t-s)},(t-s)^{-1},
\quad 0 \le s < t \le T,
\end{align}
where $\mathcal{T}(t)$ and $\mathcal{T}_h(t)$ denote the infinite- and finite-dimensional semigroups, respectively, $P_h$ is the orthogonal projection, and $c_1, c_2 > 0$ are constants.

To bound the error in the optimal state, Duhamel's formula is applied. When the resulting time integral is split appropriately, the singularity in the integrand -- represented by the factor $(t-s)^{-1}$ -- gives rise to a logarithmic contribution, namely $-\ln(h) = \ln(1/h)$. This term then propagates to the final error estimate for the optimal control.

We remark that even in more recent and generalized results (see \cite{MR4879947} and references therein), the same logarithmic factor $\ln(1/h)$ persists.
    \end{enumerate}
\end{remark}


\section{The RBM for the Heat Equation on Networks}\label{sec:numerical}
In this section, we present the heat equation on graphs and discuss its discretization and the application of the RBM.


\subsection{The Heat Equation on Graphs}\label{subsec:numerics_equation}
Let $\mathcal{G} := (\mathcal{E}, \mathcal{V})$ be an oriented and connected metric graph with vertices $v \in \mathcal{V}$ and edges $e \in \mathcal{E}$. In the following, to simplify the presentation, we will focus on the graph $\mathcal{G}$ illustrated in \Cref{fig:graph_and_dec}. Nonetheless, the methodology developed herein is applicable to any connected metric graph. The graph $\mathcal{G}$ is composed by the edges and vertices:
\begin{align*}
    \mathcal{E} = \{e_i\}_{i=1}^{10},\quad \text{and} \quad \mathcal{V} = \mathcal{V}_0 \cup \mathcal{V}_b=\{v_i\}_{i=1}^3\cup  \{v_i\}_{i=4}^{11},
\end{align*}
where $\mathcal{V}_0$ and $\mathcal{V}_b$ denote the interior and boundary vertices, respectively. Here, the orientation of the graph is used merely to identify each edge $e \in \mathcal{E}$ with an interval $(0, l_e)$ for $l_e > 0$, without ambiguity, where $0$ and $l_e$ represent the incoming and outgoing vertices of $e$, respectively. For simplicity, we also assume that $l_e = L > 0$ for all $e \in \mathcal{E}$.



On each edge $e_i$ with $i \in \{1, \dots, 10\}$, we consider the heat equation
\begin{align}\label{eq:heat_net}
\begin{cases}
\pt y^{e_i} - \pxx y^{e_i} = f^{e_i},\quad &(x,t) \in (0,L) \times (0,T),\\
y^{e_i}(x,0) = y_{e_i}^0(x),&x \in (0,L),
\end{cases}
\end{align}
where $y_{e_i}^0$ is the initial condition and $f^{e_i}$ is the source term, both defined for every $i \in \{1, \dots, 10\}$. System \eqref{eq:heat_net} is complemented with boundary and coupling conditions:
\begin{align}\label{eq:heat_bc}
\begin{cases}
y^e(v,t) = 0, \quad & v \in \mathcal{V}_b,\, e \in \mathcal{E}(v),\\
y^{e'}(v,t) = y^{e''}(v,t),& v \in \mathcal{V}_0,\, e', e'' \in \mathcal{E}(v),\\
\displaystyle\sum_{e \in \mathcal{E}(v)} \px y^e(v,t) n_e(v) = 0, & v \in \mathcal{V}_0,
\end{cases}
\end{align}
over the time interval $(0,T)$. Here, $n_e(v)$ denotes the incidence vector of the directed graph, and $\mathcal{E}(v)$ denotes the set of edges incident to the vertex $v$. The first equation in \eqref{eq:heat_bc} corresponds to a natural extension of the null Dirichlet boundary condition. The second and third conditions of \eqref{eq:heat_bc} are coupling conditions for the interior vertices of the graph. In the following, we denote by $f$ and $y^0$ the sets of functions $\{f^{e_i}\}_{i=1}^{10}$ and $\{y_{e_i}^0\}_{i=1}^{10}$, respectively. We assume that $f \in L^2(0,T;L^2(\mathcal{E}))$ and $y^0 \in H^1_0(\mathcal{E})$ (see \cite[Chapter 3]{MR3243602} for an introduction to Lebesgue and Sobolev spaces on graphs).  The well-posedness of the system \eqref{eq:heat_net}-\eqref{eq:heat_bc} has been studied in \cite{Egger}, ensuring the existence of a unique solution $y \in C(0,T;L^2(\mathcal{E})) \cap L^2(0,T;H^1_0(\mathcal{E}))$.
\smallbreak

 In the following, we consider the initial condition $y^0$ and the source term $f$ as specified in \Cref{tab:expressions_ei}. The exact solution of \eqref{eq:heat_net}–\eqref{eq:heat_bc}, associated with this data, is also given in \Cref{tab:expressions_ei}. The sequence of coefficients \( \{p_{e_i}\}_{i=1}^{10} \), defined in \Cref{tab:coefficients_pe}, is carefully chosen so that $y^e$ satisfies \eqref{eq:heat_net}–\eqref{eq:heat_bc} with the corresponding data. This construction follows the method of manufactured solutions, as described in \cite[Chapter 12]{MR3931345}. That is, we begin by prescribing a smooth candidate function $y^e$ as the exact solution and then define $f$ and $y^0$ accordingly, ensuring that the equation and boundary conditions are satisfied. This approach allows for a controlled setting in which the numerical error can be precisely assessed.



