    \label{fig:non_overlapping_illustration}
\end{figure}

Then, similar to \eqref{eq:decomposition_matrix_Ah_by_blocks}, we introduce a decomposition of the matrix $\boldsymbol{R}_h = \boldsymbol{R}_1 + \boldsymbol{R}_2 + \boldsymbol{R}_3$ using the blocks $\bf{B_i}$ introduced in \eqref{B_nonoverlapping}. Furthermore, we decompose $\F_h$ as

\begin{align*}
    \F_h = (\F_1, 0, 0)^{\top} + (0, \F_2, 0)^{\top} + (0, 0, \F_3)^{\top},
\end{align*}

where

\begin{align}\label{eq:decom_f_nonooverlap}
    \F_1 &= \left( \f_h^{e_1}, \f_h^{e_2}, \f_h^{e_3}, [\f_h^{e_4}]_{I_1} \right)^{\top}, \,
    \F_2 = \left( [\f_h^{e_4}]_{I_2}, \f_h^{e_5}, \f_h^{e_6}, \f_h^{e_7}, [\f_h^{e_8}]_{I_1} \right)^{\top}, \,
    \F_3 = \left( [\f_h^{e_8}]_{I_2}, \f_h^{e_9}, \f_h^{e_{10}} \right)^{\top}.
\end{align}

Here, $I_1 = \{0, \dots, \overline{N}\}$ and $I_2 = \{\overline{N}, \dots, N\}$. Using \eqref{eq:decom_f_nonooverlap}, we define $\F_{rb}$ according to \eqref{eq:def_finction_f_rand_net}, and $\boldsymbol{R}_{rb}$ as in \eqref{eq:definition_matrix_R_rb}. Then, we introduce the system \eqref{eq:random_network_fem}.

For the numerical simulation, we consider $N = 300$ elements for spatial discretization on each edge. To solve the ODEs, we use an implicit Euler scheme with $\zeta = 201$ time collocation points. To compute the expected value, we run 30 realizations. The numerical results are illustrated in \Cref{fig:non_overlapping_comparation}. Observe that the average approximates the solution on every edge, while the variance remains small. However, the \textit{overlapping scheme} seems to be more accurate, at less on edges $e_4$ and $e_8$.

