\section{Proofs of Theoretical Results} \label{appendix:proofs}

\subsection{Proof of Theorem~\ref{thm:blockSLQ}} \label{appendix:blockSLQ}
\begin{proof}
We first prove unbiasedness. Since the columns of \(V\) are orthonormal and drawn from the Haar measure on the Stiefel manifold, we have
\[
\mathbb{E}[VV^T] = \frac{b}{n}I_n.
\]
Therefore,
\[
\mathbb{E}\Bigl[\operatorname{tr}\bigl(V^T f(A)V\bigr)\Bigr]
=\operatorname{tr}\Bigl(f(A)\,\mathbb{E}[VV^T]\Bigr)
=\frac{b}{n}\operatorname{tr}\bigl(f(A)\bigr).
\]
Defining
\[
X(V)=\frac{n}{b}\operatorname{tr}\bigl(V^T f(A)V\bigr),
\]
it follows immediately that
\[
\mathbb{E}[X(V)] = \operatorname{tr}\bigl(f(A)\bigr).
\]
In the extreme case \(b=n\), any orthonormal \(V\) is orthogonal (i.e. \(VV^T=I_n\)) so that
\[
\operatorname{tr}\bigl(V^T f(A)V\bigr)=\operatorname{tr}\bigl(f(A)\bigr),
\]
and hence \(X(V)\) is deterministic with zero variance.

Next, we derive the variance. Write the columns of \(V\) as \(v_1, v_2, \dots, v_b\), so that
\[
\operatorname{tr}\Bigl(V^T f(A)V\Bigr)=\sum_{r=1}^{b} v_r^T f(A)v_r.
\]
For a single scalar unit vector \(v\) uniformly distributed on the sphere in \(\mathbb{R}^n\), we express \(v\) in the eigenbasis of \(A\) by writing \(A=Q\Lambda Q^T\) with \(\Lambda = \mathrm{diag}(\lambda_1,\dots,\lambda_n)\) and \(v = Qz\). Then,
\[
v^T f(A)v = z^T f(\Lambda) z = \sum_{i=1}^n f(\lambda_i) z_i^2.
\]
Because \(z\) is uniformly distributed on the unit sphere, the moments of its components are:
\[
\mathbb{E}[z_i^2] = \frac{1}{n},\quad \mathbb{E}[z_i^4] = \frac{3}{n(n+2)},\quad \mathbb{E}[z_i^2 z_j^2] = \frac{1}{n(n+2)} \quad (i\neq j).
\]
Thus,
\[
\begin{aligned}
\mathbb{E}\Bigl[\Bigl(v^T f(A)v\Bigr)^2\Bigr]
&=\sum_{i=1}^n f(\lambda_i)^2\,\mathbb{E}[z_i^4]
+\sum_{i\neq j} f(\lambda_i)f(\lambda_j)\,\mathbb{E}[z_i^2z_j^2]\\[1mm]
&=\frac{3}{n(n+2)}\sum_{i=1}^n f(\lambda_i)^2
+\frac{1}{n(n+2)}\left[\left(\sum_{i=1}^n f(\lambda_i)\right)^2-\sum_{i=1}^n f(\lambda_i)^2\right]\\[1mm]
&=\frac{2}{n(n+2)}\sum_{i=1}^n f(\lambda_i)^2
+\frac{1}{n(n+2)}\left(\sum_{i=1}^n f(\lambda_i)\right)^2.
\end{aligned}
\]

Therefore, the variance of a scalar quadratic form is

\[
\begin{aligned}
\operatorname{Var}\bigl[v^T f(A)v\bigr]
&=\mathbb{E}\Bigl[\bigl(v^T f(A)v\bigr)^2\Bigr]
-\Bigl(\frac{1}{n}\sum_{i=1}^n f(\lambda_i)\Bigr)^2\\[3pt]
&=\frac{2}{n(n+2)}\sum_{i=1}^n f(\lambda_i)^2
-\frac{2}{n^2(n+2)}\Bigl(\sum_{i=1}^n f(\lambda_i)\Bigr)^2.
\end{aligned}
\]

Now, consider the block estimator. Define
\[
S = \sum_{r=1}^b v_r^T f(A)v_r.
\]
If the \(b\) vectors were independent, we would have 
\[
\operatorname{Var}(S)= b\,\operatorname{Var}\bigl[v^T f(A)v\bigr].
\]
However, because the columns of \(V\) are orthonormal, for any \(i \neq j\) we have
\[
\operatorname{Cov}\Bigl(v_i^T f(A)v_i,\, v_j^T f(A)v_j\Bigr)
=-\frac{1}{n-1}\,\operatorname{Var}\Bigl(v^T f(A)v\Bigr).
\]
Thus,
\[
\begin{aligned}
\operatorname{Var}(S)
&=\sum_{r=1}^b \operatorname{Var}\bigl[v^T f(A)v\bigr] + \sum_{r\neq s}\operatorname{Cov}\Bigl(v_r^T f(A)v_r,\, v_s^T f(A)v_s\Bigr)\\[1mm]
&= b\,\operatorname{Var}\bigl[v^T f(A)v\bigr] - \frac{b(b-1)}{n-1}\,\operatorname{Var}\bigl[v^T f(A)v\bigr]\\[1mm]
&=\operatorname{Var}\bigl[v^T f(A)v\bigr]\left(b-\frac{b(b-1)}{n-1}\right).
\end{aligned}
\]
We call this the {\em self-averaging effect}. Since 
\[
X(V)=\frac{n}{b}S,
\]
we obtain
\[
\operatorname{Var}\bigl[X(V)\bigr] = \left(\frac{n}{b}\right)^2 \operatorname{Var}(S)
=\left(\frac{n}{b}\right)^2 \operatorname{Var}\bigl[v^T f(A)v\bigr]\left(b-\frac{b(b-1)}{n-1}\right).
\]
Substituting the expression for \(\operatorname{Var}\bigl[v^T f(A)v\bigr]\) yields
\[
\operatorname{Var}\bigl[X(V)\bigr] = \left(\frac{n}{b}\right)^2 \frac{2}{n(n+2)}\left(\sum_{i=1}^n f(\lambda_i)^2-\frac{1}{n}\Bigl(\operatorname{tr}(f(A))\Bigr)^2\right)\left(b-\frac{b(b-1)}{n-1}\right).
\]
Simplifying, we note that
\[
\left(\frac{n}{b}\right)^2 \frac{2}{n(n+2)} = \frac{2n}{b^2(n+2)}.
\]
Thus, 
\[
\operatorname{Var}\bigl[X(V)\bigr] = \frac{2n}{b^2(n+2)}\left(b-\frac{b(b-1)}{n-1}\right)
\left(\sum_{i=1}^n f(\lambda_i)^2-\frac{1}{n}\Bigl(\operatorname{tr}(f(A))\Bigr)^2\right).
\]
We can factor a \(b\) from the term in parentheses:
\[
b-\frac{b(b-1)}{n-1} = b\left(1-\frac{b-1}{n-1}\right),
\]
so that
\[
\operatorname{Var}\bigl[X(V)\bigr] = \frac{2n}{b^2(n+2)}\,b\left(1-\frac{b-1}{n-1}\right)
\left(\sum_{i=1}^n f(\lambda_i)^2-\frac{1}{n}\Bigl(\operatorname{tr}(f(A))\Bigr)^2\right).
\]
Cancel one \(b\) to obtain
\[
\operatorname{Var}\bigl[X(V)\bigr] = \frac{2n}{b(n+2)}\left(1-\frac{b-1}{n-1}\right)
\left(\sum_{i=1}^n f(\lambda_i)^2-\frac{1}{n}\Bigl(\operatorname{tr}(f(A))\Bigr)^2\right). 
\]

Where, 
\[
\frac{2n}{b(n+2)}\Bigl(1-\frac{b-1}{n-1}\Bigr)
\;=\;
-\frac{2n}{(n+2)(n-1)}
\;+\;\frac{2n^2}{(n+2)(n-1)}\,\frac{1}{b}
\;+\;0\cdot\frac{1}{b^2}
\;+\;\mathcal{O}\!\bigl(b^{-3}\bigr)
\;=\;
\mathcal{O}\bigl(b^{-1}\bigr)
\]


Averaging over \(q\) independent probes gives
\[
\operatorname{Var}[\widehat{T}] = \frac{1}{q}\operatorname{Var}\bigl[X(V)\bigr].
\]

Therefore the variance decays like $\mathcal{O}\bigl(\frac{1}{qb}\bigr)$. 

Finally, since each \(X(V)\) is almost surely contained in \([\ell_{\min},\ell_{\max}]\), Hoeffding's inequality implies that for any \(\varepsilon>0\)
\[
\mathbb{P}\!\Biggl(\Bigl|\widehat{T}-\operatorname{tr}(f(A))\Bigr|\ge\varepsilon\Biggr)
\le 2\exp\!\Biggl(-\frac{2q\,\varepsilon^2}{(\ell_{\max}-\ell_{\min})^2}\Biggr).
\]
Equivalently, with probability at least \(1-\delta\),
\[
\Bigl|\widehat{T}-\operatorname{tr}(f(A))\Bigr|\le (\ell_{\max}-\ell_{\min})\sqrt{\frac{\ln(2/\delta)}{2q}}.
\]
\end{proof}

