\subsection{Proof of Lemma~\ref{lem:matvecbudget}} \label{appendix:matvecbudget}
\begin{proof}
We begin by diagonalizing \(B\).  Since \(B\) is symmetric, write
\[
B = Q\,\mathrm{diag}\bigl(f(\lambda_1),\dots,f(\lambda_n)\bigr)\,Q^T,
\]
and set \(\widetilde V = Q^T V\).  Then \(\widetilde V\in\mathbb{R}^{n\times b}\) still satisfies \(\widetilde V^T\widetilde V=I_b\), and
\[
\tr(V^T B\,V)
=\tr\bigl(\widetilde V^T\,\mathrm{diag}(f(\lambda_i))\,\widetilde V\bigr)
=\sum_{i=1}^n f(\lambda_i)\,\widetilde V_{i,*}\cdot\widetilde V_{i,*}^T
=\sum_{i=1}^n f(\lambda_i)\,P_{ii},
\]
where \(P = \widetilde V\,\widetilde V^T\) is an orthogonal projector of rank \(b\).  Hence
\[
\widehat T_{\rm block}
=\frac{n}{b}\sum_{i=1}^n f(\lambda_i)\,P_{ii}.
\]
Define the weights \(\alpha_i = P_{ii}/b\).  Since \(\sum_i P_{ii}=\tr(P)=b\), it follows that
\[
\sum_{i=1}^n\alpha_i =1
\quad\text{and}\quad
\sum_{i=1}^n\Bigl(\alpha_i-\tfrac1n\Bigr)=0.
\]
Writing \(\delta_i=\alpha_i-\tfrac1n\), we obtain
\[
\widehat T_{\rm block}-T
= n\sum_{i=1}^n\delta_i\,f(\lambda_i).
\]
Because the \(\delta_i\) sum to zero, the maximal shift in weighted average from the smallest to the largest eigenvalue gives
\[
\bigl|\widehat T_{\rm block}-T\bigr|
\;\le\;
n\bigl(\max_i f(\lambda_i)-\min_i f(\lambda_i)\bigr)\,\max_i|\delta_i|.
\]
Noting that \(0\le P_{ii}\le1\) implies \(0\le\alpha_i\le1/b\), and since \(1/n\le1/b\), we have \(\max_i|\delta_i|\le1/b\).  Therefore
\[
\bigl|\widehat T_{\rm block}-T\bigr|
\;\le\;
\frac{n}{b}\,\bigl(\max_i f(\lambda_i)-\min_i f(\lambda_i)\bigr).
\]
Set
\[
\Delta_{\rm scalar}
=n\bigl(\max_i f(\lambda_i)-\min_i f(\lambda_i)\bigr),
\quad
C_0
=\frac{\Delta_{\rm scalar}}{T},
\]
so that algebraically
\[
\Delta_{\rm scalar}=C_0\,T,
\quad
\Delta_{\rm block}
=\frac{\Delta_{\rm scalar}}{b}
=\frac{C_0\,T}{b}.
\]
Thus every single block probe lies in an interval of length \(\Delta_{\rm block}\).  Similarly, each normalized Rademacher probe \(v^T B\,v\) lies in an interval of length \(\Delta_{\rm scalar}\).  

We now apply Hoeffding’s inequality.  If \(X_1,\dots,X_q\) are i.i.d.\ in an interval of length \(\Delta\), then  
\[
\Pr\Bigl(\bigl|\tfrac1q\sum_{k=1}^qX_k -\mathbb{E}[X_1]\bigr|\ge t\Bigr)
\le2\exp\!\Bigl(-\frac{2q\,t^2}{\Delta^2}\Bigr).
\]

1. Block SLQ: one probe (\(q=1\)) of length \(\Delta_{\rm block}=C_0T/b\).  Since \(b=\lfloor N_{\rm mv}/2\rfloor\), deterministically
\[
\bigl|\widehat T_{\rm block}-T\bigr|
\le\Delta_{\rm block}
=O\!\Bigl(\tfrac1b\Bigr)
=O\!\Bigl(\tfrac1{N_{\rm mv}}\Bigr),
\]
i.e.\ \(O(N_{\rm mv}^{-1})\) error with probability 1.

2. Scalar SLQ: \(q=\lfloor N_{\rm mv}/2\rfloor\) probes each of length \(\Delta_{\rm scalar}=C_0T\).  Hoeffding gives, with probability \(\ge1-\delta\),
\[
\bigl|\widehat T_{\rm scalar}-T\bigr|
\le
\Delta_{\rm scalar}\sqrt{\frac{\ln(2/\delta)}{2q}}
=O\!\Bigl(q^{-1/2}\Bigr)
=O\!\Bigl(N_{\rm mv}^{-1/2}\Bigr).
\]

Combining these two cases completes the proof of the \(O(N_{\rm mv}^{-1})\) versus \(O(N_{\rm mv}^{-1/2})\) high‐probability error‐decay rates.

\medskip

For the asymptotic high‐probability bound, we write
\[
V\in\R^{n\times n},\quad V^TV=I_n,
\]
where \(V\) is drawn uniformly from the Stiefel manifold \(\mathrm{St}(n,n)\), i.e., the space of orthogonal \(n\times n\) matrices. Define the rotated probe
\[
\widetilde V = Q^T V = [\,\widetilde V_1\;\bigm|\;\widetilde V_2\,],
\]
with \(\widetilde V_1\in\R^{n\times b}\), and observe that
\[
\widetilde V^T D\,\widetilde V \;\stackrel{\rm dist}=\; V^T B\,V,
\]
by rotational invariance. The true trace is then
\[
T = \tr\bigl(\widetilde V^T D\,\widetilde V\bigr)
  = \sum_{i=1}^n D_i.
\]

Introduce the selector matrix
\[
P_s = \begin{bmatrix} I_b \\[4pt] 0_{(n-b)\times b}\end{bmatrix}\in\R^{n\times b},
\]
so that
\[
P_s^T\,\widetilde V^T D\,\widetilde V\,P_s = \widetilde V_1^T\,D\,\widetilde V_1.
\]
By Lemma~\ref{thm:fullrank} (subblock Wishart sampling with \(m=b\) and covariance \(\Sigma = P_s^T D P_s = \diag(D_1,\dots,D_b)\)), the \(b\times b\) matrix \(\widetilde V_1^T D\,\widetilde V_1\sim W_b(\diag(D_1,\dots,D_b),b)\).  Hence its trace admits the chi‐square expansion
\[
\tr\!\bigl(\widetilde V_1^T D\,\widetilde V_1\bigr)
= \sum_{i=1}^b D_i\,\chi_i^2,
\qquad
\chi_i^2\sim\chi^2_1 \text{ indep.}
\]
Thus the block‐SLQ estimator is
\[
\widehat T_{\mathrm{block}}
= \frac{n}{b}\,\tr\!\bigl(\widetilde V_1^T D\,\widetilde V_1\bigr)
= \frac{n}{b}\sum_{i=1}^b D_i\,\chi_i^2,
\]
and
\[
\widehat T_{\mathrm{block}} - T
= \frac{n}{b}\sum_{i=1}^b D_i\,\chi_i^2
  - \sum_{i=1}^n D_i.
\]

Let
\[
\bar D = \frac1b\sum_{j=1}^b D_j,
\qquad
\delta_i = D_i - \bar D,
\]
so that under the mild assumption \(\delta_i = O(1/n)\) for \(1\le i\le b\),
\[
\frac{n}{b}\sum_{i=1}^b D_i - \sum_{i=1}^n D_i
= n\bar D - \sum_{i=1}^n D_i
= O\!\bigl(\tfrac1b\bigr).
\]
Moreover,
\[
\frac{n}{b}\sum_{i=1}^b D_i\,\chi_i^2
- \frac{n}{b}\sum_{i=1}^b D_i
= \frac{n}{b}\sum_{i=1}^b D_i(\chi_i^2-1)
= \frac{n}{b}\sum_{i=1}^b (\chi_i^2-1)\,(\bar D + \delta_i).
\]
The \(\bar D\)–term cancels up to \(O(1/b)\), leaving
\[
\widehat T_{\mathrm{block}} - T
= \frac{n}{b}\sum_{i=1}^b (\chi_i^2-1)\,\delta_i
  + O\!\bigl(\tfrac1b\bigr).
\]
Set
\[
X_i = (\chi_i^2-1)\,\delta_i,
\qquad
Y_i = \frac{n}{b}\,X_i,
\]
so that \(\E[X_i]=0\) and \(\Var(X_i)=2\,\delta_i^2\).  Hence
\[
\sigma^2
= \sum_{i=1}^b\Var(Y_i)
= 2\Bigl(\frac{n}{b}\Bigr)^2 \sum_{i=1}^b\delta_i^2
= O\!\bigl(\tfrac1b\bigr).
\]

\smallskip
Define
\begin{equation}\label{eq:SiYi}
S = \sum_{i=1}^b Y_i,
\quad
Y_i = \frac{n}{b}\,\delta_i(\chi_i^2-1),
\quad
\delta_i = \tilde D_i - \frac1b\sum_{j=1}^b \tilde D_j,
\end{equation}
so \(\E[S]=0\).  Since each \(\chi_i^2-1\) is sub‐exponential with
\(\|\chi_i^2-1\|_{\psi_1}\le4\) and \(|\delta_i|=O(1/n)\), the sub‐exponential norm satisfies
\[
\|Y_i\|_{\psi_1}
= \frac{n}{b}\,|\delta_i|\,
  \|\chi_i^2-1\|_{\psi_1}
= O\!\bigl(\tfrac1b\bigr).
\]
Set
\[
\beta = \max_i \|Y_i\|_{\psi_1} = O\!\bigl(\tfrac1b\bigr).
\]

\noindent
By the Bernstein mgf condition, for \(|\lambda|<\beta^{-1}\),
\[
\E\exp\!\bigl(\lambda Y_i\bigr)
\;\le\;
\exp\!\Bigl(\frac{\lambda^2\sigma^2}{2(1-\beta|\lambda|)}\Bigr),
\]
which yields the tail bound, for all \(t>0\),
\begin{equation}\label{eq:bern}
\Pr\bigl(|S|\ge t\bigr)
\le 2\exp\!\Bigl(-\frac{t^2}{2(\sigma^2 + \beta\,t)}\Bigr).
\end{equation}

Take
\[
t = c\,\sigma^2
= c\,\Bigl(\frac{n}{b}\Bigr)^2 \sum_{i=1}^b \delta_i^2
= O\!\bigl(\tfrac1b\bigr),
\]
and note \(\beta\,t = O(b^{-2})\ll\sigma^2=O(b^{-1})\).  Therefore
\[
\sigma^2 + \beta\,t = \sigma^2\bigl(1+O(b^{-1})\bigr),
\]
and substitution into \eqref{eq:bern} gives
\[
-\frac{t^2}{2(\sigma^2+\beta\,t)}
= -\frac{c^2\,\sigma^4}{2(\sigma^2+\beta\,t)}
= -\frac{c^2\,\sigma^2}{2}\bigl(1+O(b^{-1})\bigr)
= -\frac{c^2C}{2b}\bigl(1+O(b^{-1})\bigr),
\]
where \(C=2\sum_i\delta_i^2=O(1)\).  Hence
\(\Pr(|S|\ge t)\le2\exp(-\Omega(b))\), so \(S=O_p(1/b)\).  Combining with \(|\Delta|=O(1/b)\) yields
\[
\widehat T_{\mathrm{block}} - T 
= S + \Delta 
= O_p\!\bigl(\tfrac1b\bigr),
\]
and since \(N_{\rm mv}=2b\) this is equivalent to
\(\bigl|\widehat T_{\mathrm{block}}-T\bigr|=O(N_{\rm mv}^{-1})\),
as claimed.

\end{proof}


