\subsection{Proof of Lemma~\ref{lem:unbiasedsubblockbound}} \label{appendix:unbiasedsubblockbound}
\begin{proof}
First, for any \(i\in\{1,\dots,n\}\), \(\Pr(i\in S)=s/n\), so
\[
\mathbb{E}[\tr(f(A)_S)]
=\sum_{i=1}^n \Pr(i\in S)\,f(A)_{ii}
=\tfrac{s}{n}\,\tr(f(A)),
\]
and hence \(\mathbb{E}[X(S)]=\tr(f(A))\).

Next, since \(f(A)\succeq0\) and \(f\) is nondecreasing, for the coordinate projector \(P_S\) we have the Loewner ordering
\[
P_S\,f(A)\,P_S \;\preceq\; f(A).
\]
Taking traces—which preserves semidefinite inequalities—gives
\(\tr(f(A)_S)=\tr(P_S f(A)P_S)\le\tr(f(A))\),
so each block‐trace is a lower bound.

Finally, by Full Coverage via Block Sampling, if 
\(\;t\ge\frac{n}{s}\log(n/\varepsilon)\), 
then with probability \(1-\varepsilon\) the union \(U\) of the \(S_i\) equals \(\{1,\dots,n\}\).  For the corresponding projector \(P_U=I\), we have
\[
P_U\,f(A)\,P_U = f(A)
\;\Longrightarrow\;
\tr(f(A)_U)=\tr(f(A)),
\]
completing the proof.
\end{proof}



