\section{Algorithms} \label{appendix:unified_block_slq}

\subsection{Stochastic Lanczos Quadrature (SLQ)}

\begin{algorithm}[h]
\caption{Stochastic Lanczos Quadrature (SLQ) Estimator for the KL Divergence}
\label{algo}
\begin{algorithmic}[1]
\STATE \textbf{Input:} Covariance operator \(\Sigma\), Cholesky factor \(L\), number of probes \(q\), Lanczos steps \(k\).
\STATE Define \(\mathcal{A}(v) = L^T[\Sigma(Lv)]\).
\FOR{\(i = 1, \dots, q\)}
    \STATE Generate \(z_i \in \{-1,1\}^n\), normalize \(v_i = z_i/\|z_i\|\).
    \STATE Run Lanczos with \(\mathcal{A}\) starting from \(v_i\), obtain tridiagonal \(T_i\).
    \STATE Diagonalize \(T_i = U_i \operatorname{diag}(\mu_{i1}, \dots, \mu_{ik}) U_i^T\).
    \STATE Set weights \(w_{ij} = (U_i(1,j))^2\) and compute \(\eta_i = \sum_{j=1}^{k} w_{ij} f(\mu_{ij})\), where \(f(\lambda) = \lambda - \ln\lambda - 1\).
\ENDFOR
\STATE Estimate the trace: \(\widehat{\operatorname{tr}}(f(\mathcal{A})) = \frac{n}{q} \sum_{i=1}^{q} \eta_i\).
\STATE \textbf{Output:} Estimated KL divergence \(\widehat{D}_{\mathrm{KL}} = \frac{1}{2} \widehat{\operatorname{tr}}(f(\mathcal{A}))\).
\end{algorithmic}
\end{algorithm}

