%\end{align}
$ \langle I^0 f, I^1 f \rangle$ 
via the relations
\begin{equation}\label{eq:gk-Ik}
	\begin{aligned}
		v^0 \lvert_{\Sigma_{+}}(\zeta,\theta) &=  I^0f  \lvert_{\Sigma_{+}}(\zeta,\theta),  &&\\ %\mbox {for }(x,\btheta)\in\Gam_+,\\
		v^1 \lvert_{\Sigma_{+}} (\zeta, \theta) &= (\zeta \cdot \theta) v^{0} \lvert_{\Sigma_{+}}(\zeta,\theta) - I^1f  \lvert_{\Sigma_{+}}(\zeta, \theta), &&
	\end{aligned}
\end{equation}	
see \cite[Proposition 2.1.]{fujiwaraOmogbheSadiqTamasan23}.

