\begin{proposition}\label{prop1}
	%   	\cite[Proposition B.1.]{fujiwaraOmogbheSadiqTamasan23} 
	\label{prop_Bukhgeimpompeiu}
	Let $\Omega$ be a bounded convex domain,  $\B$ and $\BT$ be the operators in  \eqref{BukhgeimCauchyFormula}, respectively,
	\eqref{T_Formula}, and $\bw \in  C(\ol\OM; l^1)$.
	If $\bv \in C^1(\OM; l^1)\cap C(\ol\OM; l^1)$ solves \eqref{BukhBeltsimple1}.
	Then $\B [\bv \lvert_{\Gam}] \in C(\ol\OM; l_\INF)$, $\BT \bw \in C(\ol\OM; l_{\INF})$, and 
	\begin{align} \label{BP_Formula_vk}
		\bv(z) &= 
		\B [\bv \lvert_{\Gam}](z) +	(\BT \bw)(z), %	\quad z \in \OM,
	\end{align}
	holds component-wise for every $z \in \OM$.
	Moreover, 
%	\begin{align}\label{limit_Bukhgeimpompeiu}
%		\underset{\OM \ni z \to z_{0} \in \del \OM }{\lim} \bv(z) &= 	\B [\bv \lvert_{\Gam}](z_0) + \frac{1}{2}\bv(z_0)+	(\BT \bw)(z_0),
%	\end{align}
%	or in 
