	for each $n\geq 0$:
	\begin{equation}
		\begin{aligned}\label{limit_BP1}
			\underset{\OM \ni z \to z_{0} \in \del \OM }{\lim} v_{-n}(z)
			&= 	
			\frac{1}{2\pi i} \int_{\del \OM}
			\frac{ v_{-n}(\zeta)}{\zeta-z_0}d\zeta  +\frac{1}{2} v_{-n}(z_0) 
			\\ &\qquad 
			+ \frac{1}{2\pi i}\sum_{j=1}^{\infty}  \int_{\del \OM} \left \{ \frac{d\zeta}{\zeta-z_0}-\frac{d \ol{\zeta}}{\ol{\zeta}-\ol{z_0}} \right \} 
			v_{-n-2j}(\zeta)
			\left( \frac{\ol{\zeta}-\ol{z_0}}{\zeta-z_0} \right) ^{j} \\
			& \qquad  -\frac{1}{ \pi } \sum_{j=0}^{\infty} \iint_{\OM}    \frac{w_{-n-2j} (\zeta)  }{\zeta-z_0} \left( \frac{\ol{\zeta}-\ol{z_0}}{\zeta-z_0} \right) ^{j}d\xi d\eta, \qquad \zeta = \xi +i \eta.
			%			,   \quad z_0 \in \del \OM.
		\end{aligned}
	\end{equation}

\end{proposition}
\begin{proof}
	The regularity of $\B [\bv \lvert_{\Gam}] $  follows directly from its  definition \eqref{BukhgeimCauchyFormula}, as shown in \cite[Theorem 3.1]{sadiqTamasan01}. 

	The formula \eqref{BP_Formula_vk} is shown in  	\cite[Proposition B.1.]{fujiwaraOmogbheSadiqTamasan23}. The fact that $$ \displaystyle  		\underset{\OM \ni z \to z_{0} \in \del \OM }{\lim} 	\B [\bv \lvert_{\Gam}](z) = 	\B [\bv \lvert_{\Gam}](z_0) + \frac{1}{2}\bv(z_0)$$ follows from the Sokhotski-Plemelj formula (e.g \cite{muskhellishvili}) and   \cite[Proposition 2.2]{sadiqTamasan01}.

	To justify the continuity upto the boundary of $\BT \bw$, we work in polar coordinates. Let $\zeta (z,\varphi) = z+\rho e^{i \varphi}$, $ 0 \leq \varphi \leq 2 \pi$ and $0 \leq \rho \leq L(z, \varphi)$, where $L(z,\varphi)$ is the length of the ray emanating from $z$ in the direction $\varphi$, then 
	%   	the components of $\BT \bw$ become
	\begin{align}\label{T_polar}
		\displaystyle 	(\BT \bw)_{-n}(z) 
		& = -\frac{1}{\pi}\sum_{j=0}^\infty\int_0^{2\pi}\int_0^{L(z,\varphi) } w_{-n-2j} (z+\rho e^{i\varphi})e^{-i(2j+1)\varphi} d \rho d\varphi.
	\end{align} 
	Since $L(z,\varphi)$ is uniformly continuous in $ \ol\OM\times [0,2\pi]$ % uniformly in $\varphi$ for  $ 0 \leq \varphi \leq 2 \pi$,
	as shown in \cite[Proposition 2.2]{sadiqTamasan01} and $\bw \in  C(\ol\OM; l^1)$, 
	the regularity of $\BT \bw \in C(\ol\OM; l_{\infty})$  follows. Moreover, 	for each $n \geq 0$, 
	$$\ds \lim_{\OM \ni z \rightarrow z_0 \in \del\OM}	(\BT \bw)_{-n}(z) = 	(\BT \bw)_{-n}(z_0).$$







\end{proof}

