\section{Reconstruction Algorithm}\label{sec:Alg}
This section presents a numerical algorithm 
based on the reconstruction method above.

Let $\{ \zeta(\omega) \:;\: \alpha_{0} < \omega < \alpha_{K} \}$ be
 a smooth parametrization of  $\Lambda$ with $s=\zeta(\alpha_{0})$ and $-s=\zeta(\alpha_{K})$. The arc is further divided into $K$ sub-arcs associated with the partition $\alpha_{0} < \alpha_{1} < \dots < \alpha_{K}$. For $1 \leq k \leq K$, let  $\Delta\omega_k = \alpha_{k} - \alpha_{k-1}$ denote the interval width.
At the midpoint $\omega_k = (\alpha_{k-1} + \alpha_{k})/2$ of each interval,
we write $\zeta_k = \zeta(\omega_k)$ and $\zeta'_k = \zeta'(\omega_k)$.
Let $\Delta\varphi = \dfrac{2\pi}{N}$,  $\varphi_n = \left(n-\dfrac{1}{2}\right)\Delta\varphi$ for $1 \leq n \leq N$, and $\theta_n = (\cos \varphi_n, \sin \varphi_n)$.

The data is sampled on $\Lambda$ with respect to the outgoing direction; more specifically, our measurement data consists of
\begin{align*}
	&\bigl\{ I^0f(\zeta_k, \theta_n) \:;\: 1 \leq k \leq K, 1 \leq n \leq N, (\zeta_k,\theta_n) \in \Sigma_{+}\bigr\}
	\intertext{and}
	&\bigl\{ I^1f(\zeta_k, \theta_n) \:;\: 1 \leq k \leq K, 1 \leq n \leq N, (\zeta_k,\theta_n) \in \Sigma_{+}\bigr\}.
\end{align*}

Let $M$ be a positive integer to truncate the occurring Fourier series.
For a positive integer $J$, we write $\Delta x = \dfrac{2s}{J}$ and
equi-spaced points on $L=(-s,s)$ by $x_j = -s + \left(j-\dfrac{1}{2}\right)\Delta x$,
$1 \leq j \leq J$.
Let 
\begin{equation*}%\label{eq:innerprod_fThetaM}
	\ds G =
	\begin{cases} 
		\ds  \{ G_{m}(\zeta_k),G_{m-2}(\zeta_k),\dots,G_{-2M}(\zeta_k) \:;\: 1 \leq k \leq K \}, & \text{if } m \text{ is even}, \\
		\ds\{ G_{m}(\zeta_k),G_{m-2}(\zeta_k),\dots,G_{-2M+1}(\zeta_k) \:;\: 1 \leq k \leq K \}, & \text{if } m \text{ is odd},
	\end{cases}
\end{equation*}
and 
\begin{equation*}%\label{eq:innerprod_fThetaM}
	\ds V_L =
	\begin{cases} 
		\ds  \{ V_{m}(x_j),V_{m-2}(x_j),\dots,V_{-2M}(x_j) \:;\: 1 \leq j \leq J \}, & \text{if } m  \text{ is even}, \\
		\ds\{ V_{m}(x_j),V_{m-2}(x_j),\dots,V_{-2M+1}(x_j) \:;\: 1 \leq j \leq J \}, & \text{if } m \text{ is odd}.
	\end{cases}
\end{equation*}

%The proposed algorithms are described with discretization of the operators in \eqref{F1nc} and \eqref{BukhgeimCauchyFormula} for $-1 \ge m \ge -2M$:

The proposed algorithms are described with operators for $-1 \ge m \ge -2M$:
\begin{multline*}
	\mathcal{F}_{m}\bigl[ G \bigr](x)
	= -\dfrac{1}{\pi i}\sum_{k=1}^K \dfrac{G_m(\zeta_k)}{x-\zeta_k}\zeta'_k\Delta\omega_k
	\\
	+ \dfrac{2}{\pi} \sum_{k=1}^{K}
	\left\{\sum_{m-2 \ge m-2j \ge -2M} G_{m-2j}(\zeta_k)\left(\dfrac{\overline{\zeta_k}-x}{\zeta_k-x}\right)^j\right\}
	\Impart\left(\dfrac{\zeta'_k}{\zeta_k-x}\right)\Delta\omega_k,
	\quad x \in L,
\end{multline*}
%and 
and   the discretization of the $\mathcal{B}$ operator in  \eqref{BukhgeimCauchyFormula}  for $-1 \ge m \ge -2M$:
\begin{multline} \label{eq:opB}
	\mathcal{B}_{m}\bigl[ V_L, G \bigr](c)
	= \dfrac{1}{2\pi i}\sum_{\ell=1}^{J} \dfrac{V_m(x_\ell)}{x_\ell - c}\Delta x
	+ \dfrac{1}{2\pi i}\sum_{k=1}^{K} \dfrac{G_{m}(\zeta_k)}{\zeta_k-c}\zeta_k'\Delta\omega_k
	\\
	+ \dfrac{1}{2\pi i}\sum_{\ell=1}^{J} \left\{\sum_{m-2\ge m-2j \ge -2M} V_{m-2j}(x_\ell)\left(\dfrac{x_\ell-\overline{c}}{x_\ell-c}\right)^j\right\}\left(\dfrac{1}{x_\ell-c}-\dfrac{1}{x_\ell-\overline{c}}\right)\Delta x
	\\
	+ \dfrac{1}{\pi}\sum_{k=1}^{K} \left\{\sum_{m-2\ge m-2j \ge -2M} G_{m-2j}(\zeta_k)\left(\dfrac{\overline{\zeta_k}-\overline{c}}{\zeta_k-c}\right)^j\right\}\Impart\left(\dfrac{\zeta_k'}{\zeta_k-c}\right)\Delta\omega_k,
	\quad c \in \Omega^{+}.
\end{multline}
