\begin{step}\label{step:triangulation}
	Introduce an inscribed polygonal domain $\Omega^{+}_\Delta \approx \Omega^{+}$
	whose closure includes $L$.
	We also take a triangulation $\{ \tau_s \:;\: 1 \leq s \leq S \}$ of $\Omega^{+}_\Delta$,
	i.e.\ each $\tau_s$ is a triangular domain, 
	$\tau_s \cap \tau_t = \emptyset$ if $s\neq t$,
	and $\overline{\Omega^{+}_\Delta} = \displaystyle\overline{\bigcup_{1 \leq s \leq S} \tau_s}$.
	We denote by $c_s = (c_{s,x},c_{s,y})$ the centroid of the triangle $\tau_s$.
\end{step}

\begin{step}\label{step:nbr}[Preparation of regularized differentiation in \Cref{step:numdiff} below.]
