		\mathcal{T}_{m}\bigl[ V^0_{\Omega^{+},\text{even}} \bigr](x_j)
		&= -\dfrac{1}{\pi}\sum_{s=1}^{T}\sum_{m-1 \ge m-2j-1 \ge -2M} V^0_{m-2j-1}(c_s) \Psi(x_j;\tau_s)
		\quad 1 \leq j \leq J,
		%
		\intertext{and}
		%
		\mathcal{T}_{m}\bigl[ V^0_{\Omega^{+},\text{even}} \bigr](c_t)
		&= -\dfrac{1}{\pi}\sum_{s=1}^{T}\sum_{m-1 \ge m-2j-1 \ge -2M} V^0_{m-2j-1}(c_s) \Psi(c_t;\tau_s)
		\quad 1 \leq t \leq S,
	\end{align*}
	where $V^0_{\Omega^{+},\text{even}} = \{ V^0_{m-1}(c_s),V^0_{m-3}(c_s),\dots,V^0_{-2M}(c_s)\:;\:1\leq s \leq S\}$.
	Note that $\mathcal{T}_m$ always appears with the odd suffix $m$.
\end{step}

\begin{step}\label{step:datag0}[Discretization of the data $g^0$ in  \eqref{trace:vgk1}.]
		Let for $1 \leq k \leq K$ and $1 \leq n \leq N$
	\[
	g^0(\zeta_k,\theta_n) = \begin{cases}
		I^0f(\zeta_k,\theta_n), \quad & (\zeta_k,\theta_n) \in \Sigma_{+};\\
		0, \quad & \text{otherwise}.
	\end{cases}
	\]
	Then compute for $1 \leq k \leq K$ and $m=-2,-4,\dots,-2M$
	\[
	G^0_m(\zeta_k)
	= \dfrac{1}{2\pi} \sum_{n=1}^{N} g^0(\zeta_k,\theta_n)e^{-im\varphi_n}\Delta\varphi.
	%= \dfrac{1}{N} \sum_{n=0}^{N-1} G^0(\zeta_k,\theta_n)e^{-im\theta_n}.
	\]
\end{step}

\begin{step} \label{step:linear1}[Discretization of the  singular integral equation \eqref{Pminus_v0n}.]
	Find $V^0_{L,\text{even}} = \{ V^0_m(x_j) \:;\: m=-2,-4,\dots,-2M, 1 \leq j \leq J \}$
	by solving the discretized version of \eqref{Pminus_v0n}:
%	system of the linear equations
	\begin{align}\label{Pminus_v0n_discretized}
	V^0_m(x_j) - \dfrac{i}{\pi}\sum_{\ell\neq j}\dfrac{V^0_m(x_\ell)}{x_j - x_\ell}\Delta x
	= \mathcal{F}_{m}\bigl[G^0_\text{even}\bigr](x_j).
	\end{align}
\end{step}

\begin{step}\label{step:BCV02}[Determining the modes inside $\OM^+$ by discretization of the equation \eqref{uzero_mODD_B}.]
%	
%	By Bukhgeim-Cauchy formula \eqref{BukhgeimCauchyFormula}, we extend $\LL\bv^0$ from the boundary $\Lambda\cup L$ to $\OM^+$:
%	\begin{align}\label{uzero_mODD_B}
%	
	Compute for $m=-2,-4,\dots,-2M$ and $1 \leq s \leq S$
	\[
	V^0_m(c_s) = \mathcal{B}_{m}\bigl[V^0_{L,\text{even}},G^0_{\text{even}}\bigr](c_s).
	\]
	We set $V^0_{\Omega^{+},\text{even}} = \{ V^0_{-2}(c_s),\dots,V^0_{-2M}(c_s)\:;\:1\leq s \leq S \}$.
\end{step}

\begin{step}\label{step:datag1}[Discretization of the data $g^1$ in  \eqref{trace:vgk1}.]
	Let for $1 \leq k \leq K$ and $1 \leq n \leq N$
	\[
	g^1(\zeta_k,\theta_n) = \begin{cases}
		(\zeta_k\cdot\theta_n) I^0f(\zeta_k,\theta_n) - I^1f(\zeta_k,\theta_n), \quad & (\zeta_k,\theta_n) \in \Sigma_{+};\\
		0, \quad & \text{otherwise},
	\end{cases}
	\]
	Then for $1 \leq k \leq K$ and $m=-1,-3,\dots,-2M+1$, compute
	\[
	G^1_m(\zeta_k)
	= \dfrac{1}{2\pi} \sum_{n=1}^{N} g^1(\zeta_k,\theta_n)e^{-im\varphi_n}\Delta\varphi.
	%= \dfrac{1}{N} \sum_{n=0}^{N-1} G^0(\zeta_k,\theta_n)e^{-im\theta_n}.
	\]
	We set $G^1_{\text{odd}} = \{ G^1_m(\zeta_k)\:;\: m=-1,-3,\dots,-2M+1, 1 \leq k \leq K\}$.
\end{step}

\begin{step} \label{step:linear2} [Discretization of the  singular integral equation \eqref{Pminus_un4}.]
	Find $V^1_{L,\text{odd}} = \{ V^1_m(x_j) \:;\: m=-1,-3,\dots,-2M+1, 1 \leq j \leq J \}$
	by solving the discretized version of \eqref{Pminus_un4}:
	%	system of the linear equations
	\[
	V^1_m(x_j) - \dfrac{i}{\pi}\sum_{\ell\neq j}\dfrac{V^1_m(x_\ell)}{x_j - x_\ell}\Delta x
	= \mathcal{F}_{m}\bigl[G^1_{\text{odd}}\bigr](x_j) + 2\mathcal{T}_{m}\bigl[V^0_{\text{even}}\bigr](x_j).
	\]
\end{step}


\begin{step}\label{step:BPV1}
[Determining the modes inside $\OM^+$  by discretization of the equation \eqref{bv1}.]
		Compute for $1 \leq s \leq S$
	\[
	V^1_{-1}(c_s)
	= \mathcal{B}_{-1}\bigl[V^1_{L,\text{odd}}, G^1_{\text{odd}}\bigr](c_s)
	+ \mathcal{T}_{-1}\bigl[V^0_{\Omega^{+},\text{even}}\bigr](c_s).
	\]
\end{step}

%\begin{step}\label{step:nbr}
%	For each triangle $\tau_s$, determine sets of triangles $\mathcal{N}_s$ and $\mathcal{N}_s$
%	which is used in numerical differentiation in \Cref{step:numdiff}.
%	We call $\mathcal{N}_s$ \textit{a neighborhood} of $\tau_s$ for the sake of clarity.
