\begin{step}\label{step:numdiff}[Numerical differentiation]
	Using neighborhood $\mathcal{N}_s$, determine $\{ \partial_x V^0_{-2}(c_s), \partial_y V^0_{-2}(c_s) \:;\: 1 \leq s \leq S \}$ as the least square solution to
%	by solving the system of linear equations in the sense of least square
        \[
		(\xi_t-\xi_s) \partial_x V^0_{-2}(c_s)
		+ (\eta_t-\eta_s) \partial_y V^0_{-2}(c_s)
		= V^0_{-2}(c_t) - V^0_{-2}(c_s),
		\quad \text{for all $t \neq s$ with $\tau_t \in \mathcal{N}_s$, $1 \leq t \leq S$}.
        \]
