		%  \begin{pmatrix}
			%    \xi_1-\xi_s & \eta_1-\eta_s & \tfrac{1}{2}(\xi_1-\xi_s)^2 & \tfrac{1}{2}(\xi_1-\xi_s)(\eta_1-\eta_s) & \tfrac{1}{2}(\eta_1-\eta_s)^2\\
			%    \vdots\\
			%    \xi_t-\xi_s & \eta_t-\eta_s & \tfrac{1}{2}(\xi_t-\xi_s)^2 & \tfrac{1}{2}(\xi_t-\xi_s)(\eta_t-\eta_s) & \tfrac{1}{2}(\eta_t-\eta_s)^2
			%  \end{pmatrix}
		%  \begin{pmatrix}
			%    \partial_x V^1_{-1}(c_s)\\
			%    \partial_y V^1_{-1}(c_s)\\
			%    \partial^2_{xx} V^1_{-1}(c_s)\\
			%    \partial^2_{xy} V^1_{-1}(c_s)\\
			%    \partial^2_{yy} V^1_{-1}(c_s)
			%  \end{pmatrix}
		%  \\
		%  =
		%  \begin{pmatrix}
			%    V^1_{-1}(c_1) - V^1_{-1}(c_s)\\
			%    \vdots\\
			%    V^1_{-1}(c_t) - V^1_{-1}(c_s)
			%  \end{pmatrix}.
		%  \end{multline*}

		Using neighborhood $\mathcal{N}_s$, determine 
	$\{ \partial_x V^1_{-1}(c_s), \partial_y V^1_{-1}(c_s), 
	\partial^2_{xx} V^1_{-1}(c_s), \partial^2_{xy} V^1_{-1}(c_s), \partial^2_{yy} V^1_{-1}(c_s) \:;\: 1 \leq s \leq S \}$
	as the least square solution to
	\begin{multline*}
		(\xi_t-\xi_s)      \partial_x V^1_{-1}(c_s)
		+ (\eta_t-\eta_s)    \partial_y V^1_{-1}(c_s)\\
		+ \dfrac{1}{2}\left\{
		(\xi_t-\xi_s)^2    \partial^2_{xx} V^1_{-1}(c_s)
		+ 2(\xi_t-\xi_s)(\eta_t-\eta_s)    \partial^2_{xy} V^1_{-1}(c_s)
		+ (\eta_t-\eta_s)^2    \partial^2_{yy} V^1_{-1}(c_s)\right\}\\
		=
		V^1_{-1}(c_t) - V^1_{-1}(c_s),
		\quad\text{for all $t \neq s$ with $\tau_t \in \mathcal{N}_s$, $1 \leq t \leq S$}.
	\end{multline*}
	%  \[
	%  \begin{pmatrix}
		%    \xi_1-\xi_s & \eta_1-\eta_s \\
		%    \vdots \\
		%    \xi_t-\xi_s & \eta_t-\eta_s \\
		%  \end{pmatrix}
	%  \begin{pmatrix}
		%    \partial_x V^0_{-2}(c_s)\\
		%    \partial_y V^0_{-2}(c_s)\\
		%  \end{pmatrix}
	%  =
	%  \begin{pmatrix}
		%    V^0_{-2}(c_1) - V^0_{-2}(c_s)\\
		%    \vdots\\
		%    V^0_{-2}(c_t) - V^0_{-2}(c_s)
		%  \end{pmatrix}.
	%  \]
\end{step}

%	\begin{align}\label{f1_defn}
%	f_{1}(z) := \overline{\del} v^0_{0}(z) +\del v^0_{-2}(z), \quad z \in \OM^+,
%\end{align}
%and define the vector field inside $\OM^+$ by
