\begin{step}\label{step:F1}%[Discretization of the equation \eqref{f1_defn}.]
	Compute for $1 \leq s \leq S$
	\begin{multline*}
		F_1(c_s)
		= \dfrac{1}{4}\Bigl(\partial^2_{xx}V^1_{-1}(c_s) + \partial^2_{yy}V^1_{-1}(c_s) \Bigr)\\
		+ \dfrac{1}{4}\overline{\Bigl(\partial^2_{xx}V^1_{-1}(c_s) - \partial^2_{yy}V^1_{-1}(c_s) - 2i\partial^2_{xy}V^1_{-1}(c_s)\Bigr)}
		+ \dfrac{1}{2}\Bigl(\partial_x V^0_{-2}(c_s) - i \partial_y V^0_{-2}(c_s) \Bigr).
	\end{multline*}
\end{step}

\begin{step}\label{step:final}[Reconstruction of  $f$ via  the equation \eqref{F_defn}.]
	Compute for $1 \leq s \leq S$
	\[
        f|_{\tau_s} \approx \bigl\langle 2\Repart{F_1(c_s)}, 2\Impart{F_1(c_s)}\bigr\rangle.
        \]
	This ends the algorithm. \qed
\end{step}



