We denote the edges $\hat{A}_1\hat{A}_2$, $\hat{A}_2\hat{A}_3$, $\hat{A}_3\hat{A}_4$, $\hat{A}_4\hat{A}_5$, $\hat{A}_5\hat{A}_1$, and $\hat{A}_3\hat{A}_5$ by $\hat{e}_1$ to $\hat{e}_6$, respectively, with $\hat{m}_i$ being the midpoint of $\hat{e}_i$ (see Figure \ref{degree}). The macro-element $\hat{K}$ consists of triangular ($\hat{T}$) and quadrilateral ($\hat{Q}$) subelements. 

The basis functions defined on the macro-element $\hat{K}$ resemble Hsieh–Clough–Tocher type element and are constructed according to the finite element triple $(\hat{K}, \mathcal{P}_{\hat{K}}, \mathcal{N})$, where
\begin{equation}
	\left\{
	\begin{aligned}
		&\mathcal{P}_{\hat{K}}=\{v\in L^2(\hat{K}); v|_{\hat{T}}\in P_1(\hat{T}),~v|_{\hat{Q}}\in P_1(\hat{Q}), [\![v(\hat{m}_6)]\!] =0\},	\\
		&\mathcal{N} = \{\mathcal{N}_1,\mathcal{N}_2,\cdots,\mathcal{N}_5\}~ \text{where} ~\mathcal{N}_i(v) = v(\hat{m}_i),~ 1\leq i\leq 5.
	\end{aligned}
	\right.
\end{equation}
This definition implies that there are no degrees of freedom on edges belonging to $\widetilde{\mathcal{E}}_h^{\Gamma}$. The unisolvence can be directly deduced via straightforward calculations. Furthermore, the explicit basis functions $\hat{\phi}_i \in \mathcal{P}_{\hat{K}}$ corresponding to $\mathcal{N}_i$ are given by:
\begin{align}
	\hat{\phi}_1 &= \begin{cases} 
		\dfrac{(s - t)\hat{x} + (s - 2)\hat{y} + t - st/2}{|\hat{Q}|}, & (\hat{x},\hat{y}) \in \hat{Q} \\[10pt]
		-\dfrac{(s - t)\hat{x} + (s - 1)\hat{y} + (1 + t - s - st)/2}{|\hat{T}|}, & (\hat{x},\hat{y}) \in \hat{T}
	\end{cases} \\
	\hat{\phi}_2 &= \begin{cases} 
		\dfrac{t\hat{x} + \hat{y} - t/2}{|\hat{Q}|}, & (\hat{x},\hat{y}) \in \hat{Q} \\[10pt]
		\dfrac{(s - t)\hat{x} + (s - 1)\hat{y} + (1 + t - s - st)/2}{|\hat{T}|}, & (\hat{x},\hat{y}) \in \hat{T}
	\end{cases} \\
	\hat{\phi}_3 &= \begin{cases} 
		0, & (\hat{x},\hat{y}) \in \hat{Q} \\[10pt]
		-\dfrac{(1 - s)\hat{x} + (1 - s)\hat{y} + (1 + t)(1 - s)/2}{|\hat{T}|}, & (\hat{x},\hat{y}) \in \hat{T}
	\end{cases} \\
	\hat{\phi}_4 &= \begin{cases} 
		0, & (\hat{x},\hat{y}) \in \hat{Q} \\[10pt]
		-\dfrac{(t - 1)\hat{x} + (1 - t)(1 - s)/2}{|\hat{T}|}, & (\hat{x},\hat{y}) \in \hat{T}
	\end{cases} \\
	\hat{\phi}_5 &= \begin{cases} 
		\dfrac{-s\hat{x} + (1 - s)\hat{y} + s/2}{|\hat{Q}|}, & (\hat{x},\hat{y}) \in \hat{Q} \\[10pt]
		-\dfrac{(s - t)\hat{x} + (s - 1)\hat{y} + (1 + t)(1 - s)/2}{|\hat{T}|}, & (\hat{x},\hat{y}) \in \hat{T}
	\end{cases}
\end{align}
where $|\hat{Q}| = \frac{1}{2}(t + s - st)$ and $|\hat{T}| = \frac{1}{2}(1 - t)(1 - s)$ denote the areas of the subelements.

\begin{lemma}\label{lem:basis-estimate}
	The basis functions satisfy the uniform estimate:
	\begin{equation}
		|\hat{\phi}_i|_{H^1(\hat{Q})} \lesssim |\hat{Q}|^{-1/2}, \quad 1 \leq i \leq 5.
	\end{equation}
\end{lemma}

\begin{proof}
	The bound follows from direct computation of the explicit expressions.
\end{proof}


Accordingly, the finite element space on the reference macro-element is defined as
\[
\hat{V}_h(\hat{K}) = \text{span}\left\{ \hat{\phi}_1, \hat{\phi}_2, \ldots, \hat{\phi}_5 \right\},
\]
and the corresponding physical-element space is given by
\[
V_h(K) = \left\{ v_h ~\middle|~ v_h = \hat{v}_h \circ F^{-1}_K,\; \hat{v}_h \in \hat{V}_h(\hat{K}) \right\}.
\]

\subsection{Weak formulation}
The continuous weak formulation of the elliptic interface problem is:
\begin{equation}\label{cweak}
	\begin{cases}
		\text{Find } u \in V := H^1_0(\Omega) \text{ such that} \\
		a(u,v) = F(v) \quad \forall v \in V,
	\end{cases}
\end{equation}
where $a(u,v) = (\beta\nabla u, \nabla v)$ and $F(v) = (f,v)$. The discrete variational formulation is given by:
\begin{equation}\label{dweak}
	\begin{cases}
		\text{Find } u_h \in \mathring{V}_h := \left\{ v \in V_h \ \middle|\ \int_e v  ds = 0\ \forall e \in \widetilde{\mathcal{E}}_h^{0} \right\} \text{ such that}\\
		a_h(u_h, v_h) = F(v_h) \quad \forall v_h \in \mathring{V}_h,
	\end{cases}
\end{equation}
where the discrete bilinear form is defined as $a_h(u_h, v_h) = \sum_{i=1}^{2} \sum_{K \in \widetilde{\mathcal{T}}_{h,i}} (\beta_i \nabla u_h, \nabla v_h)_K.$
This formulation corresponds to replacing the piecewise constant coefficient $\beta$ by its discrete approximation $\beta_h$, defined as
\[
\beta_h|_{K} =
\begin{cases}
	\beta_1 & K \in \widetilde{\mathcal{T}}_{h,1}, \\
	\beta_2 & K \in \widetilde{\mathcal{T}}_{h,2},
\end{cases}
\]
allowing the bilinear form to be equivalently expressed as
\[
a_h(u_h, v_h) = \sum_{K \in \widetilde{\mathcal{T}}_h} (\beta_h \nabla u_h, \nabla v_h)_K.
\]
\subsection{Interpolation error analysis}
Recall that $\widetilde{\mathcal{E}}_h^{\Gamma}$ denote the collection of all the edges align with $\Gamma_h$ and $\widetilde{\mathcal{E}}_h^N = \widetilde{\mathcal{E}}_h\setminus \widetilde{\mathcal{E}}_{h}^{\Gamma}$. Define $\pi_h:\tilde{H}^2(\Omega_{1}\cup\Omega_{2})\rightarrow \mathring{V}_h$ by
\begin{equation}
  \pi_h v(m_i) = (v(A_i)+v(A_{i+1}))/2\quad \forall e\in \mathcal{E}_h^N,
\end{equation}
where $A_i$ and $A_{i+1}$ is the two endpoints of $e$ and $m_i$ is the middle point. Denote $\pi_{K}$ the restriction of $\pi_{h}$ to element $K$.
\begin{remark} We note that for $K\in \widetilde{\mathcal{T}}_h^N$, $\pi_K v$ coincides with the standard nodal interpolation of linear conforming finite element. 
\end{remark}
We only need to analyze the interpolation error on interface macro element. For $K\in \mathcal{T}_h^{\Gamma}$, by a standard scaling argument, one has
	\begin{align}
		|v-\pi_{K}v|_{H^1(K)}
		&\leq C|\text{det}(B)|^{1/2}\|B^{-1}\||\hat{v}-\hat{\pi}_{\hat{K}}\hat{v}|_{H^1(\hat{K})}\\
		&\leq C|\hat{v}-\hat{\pi}_{\hat{K}}\hat{v}|_{H^1(\hat{K})}.
	\end{align}

For an arbitrary triangular element $T$, $\pi_{T}$ coincides with the standard nodal interpolation operator, i.e., $\pi_{T}v(A_i) = v(A_i)$. Since the triangular element $T$ satisfies the maximum angle condition, the following lemma holds, which is fundamentally attributed to Babuška \cite{Babuska1976on}:

\begin{lemma}
	Let $T$ be a triangular element satisfying the maximum angle condition. For all $v \in H^2(T)$, we have
	\begin{equation}
		|v - \pi_{T} v|_{H^1(T)} \lesssim h_T |v|_{H^2(T)},
	\end{equation}
	where $h_T$ denotes the diameter of element $T$.
\end{lemma}

