For elements $K \in \mathcal{T}_h^N$, the triangular subelements generated by the discrete interface $\Gamma_h$ satisfy the maximum angle condition. The interpolation error estimates on these triangles follow from the preceding lemmas. We now focus on the interpolation error analysis for quadrilateral subelements $Q \subset K\in \mathcal{T}_h^{\Gamma}$.

Let $\hat{Q}$ denote the quadrilateral subelement of a reference interface element $\hat{K}$ (see Figure \ref{split}), and let $\hat{T}_{ijk}$ represent the triangular subelement with vertices $\hat{A}_i$, $\hat{A}_j$, and $\hat{A}_k$. Define $\hat{\pi}^c$ as the standard linear conforming nodal interpolation operator on triangle $\hat{T}_{125}$.

The following trace theorem \cite{Acosta2000} provides geometrically explicit constants:
\begin{lemma}[Trace theorem]\label{lem:trace}
	For any triangle $T$ with diameter $h_T$ and edge $e$,
	\begin{equation}
		\|v\|_{L^2(e)} \leq \left( 2 \frac{|e|}{|T|} \right)^{1/2} \left( \|v\|_{L^2(T)} + h_T |v|_{H^1(T)} \right) \quad \forall v \in H^1(T).
	\end{equation}
\end{lemma}

The next interpolation estimate originates from Acosta and Durán \cite{Acosta2000}; we provide a concise proof for completeness.
\begin{lemma}[Acosta and Durán, 2000]\label{lem:acosta}
	For any $\hat{v} \in H^2(\hat{Q})$, we have  
	\begin{equation}
		|\hat{v} - \hat{\pi}^c \hat{v}|_{H^1(\hat{Q})} \lesssim |\hat{v}|_{H^2(\hat{Q})}.
	\end{equation}
\end{lemma}
\begin{proof}
	Let $\bm{w} = (w_1, w_2)^\top = \nabla (\hat{v} - \hat{\pi}^c \hat{v})$, it is sufficient to prove
	\begin{equation*}
		\|\bm{w}\|_{L^2(\hat{Q})}\lesssim |\bm{w}|_{H^1(\hat{Q})}.
	\end{equation*}
	Let $\bar{w}=(\bar{w}_1,\bar{w}_2)^t= \frac{1}{|\hat{Q}|}\int_{\hat{Q}} wds$, since $\int_{\hat{e}_1}w_1(x,0)ds=0$, we have
	\begin{align*}
	\|\bar{w}_1\|_{L^2(\hat{Q})} &=|\hat{Q}|^{1/2}|\bar{w}_1|\\
	&=|\hat{Q}|^{1/2}\big|\int_{\hat{e}_1} (w_1-\bar{w}_1)ds\big|\\
	&\lesssim |\hat{Q}|^{1/2}|\hat{e}_1|^{1/2}\|w_1-\bar{w}_1\|_{L^2(\hat{e}_1)}\\
	&\lesssim |\hat{Q}|^{1/2}|\hat{e}_1|^{1/2} \frac{|\hat{e}_1|^{1/2}}{|\hat{T}_{125}|^{1/2}}(\|w_1-\bar{w}_1\|_{L^2(\hat{T}_{125})}+|w_1|_{H^1(\hat{T}_{125})})\\
	&\lesssim \frac{|\hat{Q}|^{1/2}}{|T_{125}|^{1/2}}|\hat{e_1}||w_1|_{H^1(\hat{T}_{125})}\quad (\text{using } |\hat{Q}|\sim |T_{125}|)\\
	&\lesssim |w_1|_{H^1(\hat{Q})}.
   \end{align*}
	 Similarly, $\|\bar{w}_2\|_{L^2(\hat{Q})} \lesssim |w_2|_{H^1(\hat{Q})}$. Finally,
	\begin{align*}
		\|\bm{w}\|_{L^2(\hat{Q})} &\leq \|\bm{w} - \bar{\bm{w}}\|_{L^2(\hat{Q})} + \|\bar{\bm{w}}\|_{L^2(\hat{Q})} \\
		&\lesssim |\bm{w}|_{H^1(\hat{Q})}. 
	\end{align*}
\end{proof}

Applying Lemma \ref{lem:acosta}, we derive the following interpolation error estimate on $\hat{Q}$:

\begin{lemma}\label{lem:quad-interp}
	For any $\hat{v} \in H^2(\hat{Q})$, the following estimate holds:
	\begin{equation}
		|\hat{v} - \hat{\pi}_{\hat{Q}} \hat{v}|_{H^1(\hat{Q})} \lesssim |\hat{v}|_{H^2(\hat{Q})}.
	\end{equation}
\end{lemma}

\begin{proof}
	Using the definitions of $\hat{\pi}^c$ and $\hat{\pi}_{\hat{Q}}$, it follows that
	\begin{align*}
		\hat{\pi}^c \hat{v} - \hat{\pi}_{\hat{Q}} \hat{v} &= \sum_{i \in \{1,2,5\}} \left[ \left( \hat{\pi}^c \hat{v} \right)(\hat{m}_i) - \left( \hat{\pi}_{\hat{Q}} \hat{v} \right)(\hat{m}_i) \right] \hat{\phi}_i \\
		&= \left[ \left( \hat{\pi}^c \hat{v} \right)(\hat{m}_2) - \left( \hat{\pi}_{\hat{Q}} \hat{v} \right)(\hat{m}_2) \right] \hat{\phi}_2 \\
		&= \frac{1}{2} \left( \hat{\pi}^c \hat{v} - \hat{v} \right)(\hat{A}_3) \hat{\phi}_2.
	\end{align*}
	Since $\left( \hat{\pi}^c \hat{v} - \hat{v} \right)(\hat{A}_2) = 0$, we derive
	\begin{align*}
		\left( \hat{\pi}^c \hat{v} - \hat{v} \right)(\hat{A}_3) &= \left| \int_{\hat{e}_2} \partial_\tau \left( \hat{\pi}^c \hat{v} - \hat{v} \right) \, ds \right| \\
		&\leq |\hat{e}_2|^{1/2} \, \left| \hat{\pi}^c \hat{v} - \hat{v} \right|_{H^1(\hat{e}_2)} \\
		&\lesssim \frac{|\hat{e}_2|}{|\hat{T}_{123}|^{1/2}} \left( \left| \hat{\pi}^c \hat{v} - \hat{v} \right|_{H^1(\hat{T}_{123})} + |\hat{v}|_{H^2(\hat{T}_{123})} \right) \\
		&\lesssim \frac{|\hat{e}_2|}{|\hat{T}_{123}|^{1/2}} |\hat{v}|_{H^2(\hat{Q})} \\
		&\lesssim t^{1/2} |\hat{v}|_{H^2(\hat{Q})}.
	\end{align*}
	Using Lemma \ref{lem:basis-estimate}, we have	
	\begin{align*}
		|\hat{\phi}_2|_{H^1(\hat{Q})} \lesssim t^{-1/2}.
	\end{align*}
	Therefore, through the triangle inequality, we obtain
	\begin{align*}
		|\hat{v} - \hat{\pi}_{\hat{Q}} \hat{v}|_{H^1(\hat{Q})} &\leq |\hat{v} - \hat{\pi}^c \hat{v}|_{H^1(\hat{Q})} + |\hat{\pi}^c \hat{v} - \hat{\pi}_{\hat{Q}} \hat{v}|_{H^1(\hat{Q})} \\
		&\lesssim |\hat{v}|_{H^2(\hat{Q})} + \left| \left( \hat{\pi}^c \hat{v} - \hat{v} \right)(\hat{A}_3) \right| \, |\hat{\phi}_2|_{H^1(\hat{Q})} \\
		&\lesssim |\hat{v}|_{H^2(\hat{Q})}.
	\end{align*}
\end{proof}

Using a similar argument as Theorem 4.1 in \cite{Hu2021optimal}, we have
\begin{theorem} \label{pih}
For any $v\in H^2(\Omega_1\cup\Omega_2)$, we have
	\begin{align}
		%|v-\pi v|_{L^2(\Omega)}\lesssim h^2|v|_{H^2(\Omega_{1}\cup\Omega_{2})},\\
		|v-\pi_h v|_{H^1(\Omega)}\lesssim h|v|_{H^2(\Omega_{1}\cup\Omega_{2})}.
	\end{align}
\end{theorem}

\subsection{Consistency  Error Analysis}
In this section, we analyze the consistency error for the nonconforming finite element space. By definition, this error is expressed as
\begin{equation}\label{E_h}
	\begin{aligned}
		E_h(u,v_h) &= a_h(u,v_h) - (f,v_h) \\
		&= \sum_{i=1}^{2} \sum_{K \in \mathcal{T}_{h,i}} (\beta_i \nabla u, \nabla v_h)_K - \int_{\Omega} f v_h  dx \\
		&= \sum_{i=1}^{2} \sum_{K \in \mathcal{T}_{h,i}} \big( (\beta_{i+1} - \beta_i) \nabla u, \nabla v_h \big)_{K \cap \Omega_i} 
		+ \sum_{K} \sum_{e \subset \partial K} \int_{e} \beta \frac{\partial u}{\partial \boldsymbol{n}} v_h  ds \\
		&=: E_1(u,v_h) + E_2(u,v_h)
	\end{aligned}
\end{equation}
The consistency error for nonconforming elements in interface problems thus decomposes into two components: 
$E_1(u, v_h)$ arises from piecewise linear approximation of the curved interface, whereas $E_2(u, v_h)$ represents the intrinsic consistency error of the nonconforming method. 
The analysis of $E_1(u, v_h)$ is established in \cite{Hu2021optimal}. 

\begin{lemma}\label{E1}
	For any $u\in \tilde{H}^2(\Omega_1\cup\Omega_2)$, the following estimate holds:
	\begin{equation}
		E_1(u,v_h) \lesssim h \|u\|_{H^2(\Omega_1 \cup \Omega_2)} \|v_h\|_{V_h},
	\end{equation}
	where $\|\cdot\|_{V_h}$ denotes the piecewise $H^1$ semi-norm. 
\end{lemma}

This subsection focuses on rigorous analysis of $E_2(u, v_h)$. For notational brevity, define $\bm{\eta} = \beta \nabla u$ and $E(\bm{\eta}, v_h) := E_2(u, v_h)$. 
Although $\bm{\eta}$ possesses $H^1$-regularity in each subdomain $\Omega_i$, it may lack $H^1$-regularity over individual elements. 
To address this issue, we invoke the Sobolev extension theorem: there exist operators $T_i : H^1(\Omega_i) \to H^1(\Omega)$ satisfying
\begin{equation}
	T_i v_i\big|_{\Omega_i} = v_i \quad \text{and} \quad \|T_i v_i\|_{H^1(\Omega)} \lesssim \|v_i\|_{H^1(\Omega_i)}, \quad i=1,2.
\end{equation}
Define the piecewise extension operator
\begin{equation}
	T\bm{\eta} :=
	\begin{cases}
		T_1 \bm{\eta} & \text{in } \Omega_{1,h}, \\
		T_2 \bm{\eta} & \text{in } \Omega_{2,h}.
	\end{cases}
\end{equation}
Consequently, the consistency error decomposes as
\begin{align}
	E(\bm{\eta}, v_h) = E(T\bm{\eta}, v_h) + E(\bm{\eta} - T\bm{\eta}, v_h).
\end{align}
Prior to estimating the consistency error, we introduce notation that will be used throughout the subsequent analysis. For a function $v \in H^1(K)$, let $v^{(e)}$ denote the trace of $v$ on edge $e$. We define
\begin{align*}
	\bar{v}^{(e)} &:= \frac{1}{|e|} \int_{e} v  ds, \\
	\delta v^{(e)} &:= v^{(e)} - \bar{v}^{(e)}.
\end{align*}
For vector-valued functions $\bm{\eta}$, we denote its components by $\eta_x$ and $\eta_y$. When the superscript is replaced by an element $K$ (e.g., $\bar{v}^{(K)}$), the definitions carry analogous meanings over the element $K$. For an interface macro element $K$ (see Figure \ref{fig:macro-element}), we frequently analyze its subtriangular components. To enhance notational brevity, superscripts or subscripts may be omitted when no ambiguity arises.

The following refined trace theorem on anisotropic triangle elements (cf. [Dura2020]) accounts for element geometry.
\begin{lemma}
	Let $K$ be an arbitrary tirangle, for any edge $e \subset \partial K$, the following inequality holds:
	\begin{equation}\label{eq:aniso-trace}
		\|v\|_{L^{2}(e)} \leq \left( \frac{|e|}{|K|} \right)^{1/2} \left( \|v\|_{L^2(K)} + h_K |v|_{H^1(K)} \right).
	\end{equation}
\end{lemma}

The following lemma provides an estimate for $E(\bm{\eta} - T\bm{\eta}, v_h)$.

\begin{lemma}\label{lemma:eta-Teta}
	For any $\boldsymbol{\eta} \in \big( H^1(\Omega_1 \cup \Omega_2) \big)^2$, 
	\begin{equation}\label{eq:eta-diff}
		E(\boldsymbol{\eta} - T\boldsymbol{\eta}, v_h) \lesssim h \|\boldsymbol{\eta}\|_{H^1(\Omega_1 \cup \Omega_2)} \|v_h\|_{V_h}.
	\end{equation}
\end{lemma}

\begin{proof}
	Define $\bm{\omega} = (T_i\boldsymbol{\eta} - T_j\boldsymbol{\eta}) \cdot \bm{n}$. 
	Applying the trace theorem, Cauchy-Schwarz inequality, and standard interpolation estimates yields:
	\begin{equation*}
		\begin{aligned}
			E(\boldsymbol{\eta} - T\boldsymbol{\eta}, v_h)
			&= \sum_{e \in \mathcal{E}_h^{\Gamma}} \int_{e} \delta\omega^{(e)} \delta v_h^{(e)}  ds \\
			&\lesssim \sum_{T \in \mathcal{T}_h^{\Gamma}} \frac{|e|}{|T_k|} \left( \|\delta\omega^{(T_k)}\|_{0,T_k} + h_{T_k} |\delta\omega^{(T_k)}|_{1,T_k} \right)
			\left( \|\delta v_h^{(T_k)}\|_{0,T_k} + h_{T_k} |\delta v_h^{(T_k)}|_{1,T_k} \right) \\
			&\lesssim \left( \frac{|e|}{|T_k|} \right) h^2 \|\bm{\eta}\|_{H^1(\Omega_1 \cup \Omega_2)} \|v_h\|_{V_h}.
		\end{aligned}
	\end{equation*}

	Consider the interface position parameter $t \in (0,1)$ (see Figure \ref{fig:macro-element}) :
	\begin{itemize}
		\item For $0 < t \leq \frac{1}{2}$, select $T_k = T_{345}$ with area $|T_k| = \frac{1}{2}|e_3||e_4|\sin\theta_{345} \lesssim (1-t)|e_6|$. 
		This implies $\frac{|e|}{|T_k|} \lesssim (1-t)^{-1}h_T^{-1} \lesssim h_T^{-1}$.

		\item For $\frac{1}{2} < t < 1$, choose $T_k = T_{135}$ with area $|T_k| = \frac{1}{2}|e_5||e_6|\sin\theta_{135} \lesssim t h_T|e_6|$. 
		Consequently, $\frac{|e|}{|T_k|} \lesssim t^{-1}h_T^{-1} \lesssim h_T^{-1}$.
	\end{itemize}
	Combining both cases, we obtain $\frac{|e|}{|T_k|} \lesssim h_T^{-1}$, which completes the proof of \eqref{eq:eta-diff}.
\end{proof}

Since each quadrilateral element in the mesh $\widetilde{\mathcal{T}}_h$ can be subdivided along one diagonal into two triangular subelements satisfying the maximum angle condition, we denote the resulting refined mesh by $\widetilde{\mathcal{T}}_h^R$. The consistency error term $E(\bm{\eta}, v_h)$ can then be expressed as
\begin{align*}
	E(\bm{\eta}, v_h) = \sum_{K \in \widetilde{\mathcal{T}}_h^R} \sum_{e \subset \partial K} \int_e (\bm{\eta} \cdot \bm{n}) v_h  ds.
\end{align*}
The continuity of $v_h$ within quadrilateral elements implies that the contributions along the subdivided diagonals vanish. Consequently, it suffices to estimate the consistency error for triangular elements satisfying the maximum angle condition. These include both original elements in $\widetilde{\mathcal{T}}_h$ and subelements generated by diagonal subdivision of quadrilaterals.

Building upon the refined trace theorem, we establish two fundamental estimates:

\begin{lemma}\label{lemma:edge-estimates}
	Let $T$ be an arbitrary triangular element with diameter $h_T$, and $e$ an edge of $T$. Then:
	\begin{align}
		\|\delta v^{e}\|_{L^2(e)} &\lesssim \left( \frac{|e|}{|T|} \right)^{1/2} h_T |v|_{H^1(T)}. \label{eq:gen-est}
	\end{align}
	Moreover, if $v \in P_1(T)$, the following improved estimate holds:
	\begin{align}
		\|\delta v^{e}\|_{L^2(e)} &\lesssim \left( \frac{|e|}{|T|} \right)^{1/2} |e| |v|_{H^1(T)}. \label{eq:p1-est}
	\end{align}
\end{lemma}

\begin{proof}
	Utilizing the $L^2$-projection property of the integral mean and the trace theorem, we derive:
	\begin{equation*}
		\begin{aligned}
			\|\delta v^{e}\|_{L^2(e)} 
			&= \|v - \bar{v}^{e}\|_{L^2(e)} \\
			&\leq \|v - \bar{v}^{T}\|_{L^2(e)} \\
			&\lesssim \left( \frac{|e|}{|T|} \right)^{1/2} \left( \|v - \bar{v}^{T}\|_{L^2(T)} + h_T |v|_{H^1(T)} \right) \\
			&\lesssim \left( \frac{|e|}{|T|} \right)^{1/2} h_T |v|_{H^1(T)}.
		\end{aligned}
	\end{equation*}
	When $v \in P_1(T)$, the Poincaré inequality provides enhanced approximation:
	\begin{equation*}
		\begin{aligned}
			\|\delta v^{e}\|_{L^2(e)} 
			&\leq |e||v|_{H^1(e)} \\
			&\lesssim \left( \frac{|e|}{|T|} \right)^{1/2} |e|\left( |v |_{H^1(T)} + h_T|v|_{H^2(T)} \right) \\
			&= \left( \frac{|e|}{|T|} \right)^{1/2} |e| |v|_{H^1(T)}.
		\end{aligned}
	\end{equation*}
\end{proof}

The mesh $\tilde{\mathcal{T}}_h$ comprises both triangular and quadrilateral elements, where triangular elements satisfy the maximum angle condition, and quadrilateral elements satisfy the RDP condition. This property ensures that each quadrilateral can be subdivided along its longer diagonal into two triangles satisfying the maximum angle condition. We denote the resulting interface-refined mesh by $\tilde{\mathcal{T}}_h^r$, following the work \cite{Xu2016optimal} where $P_1$ conforming elements were employed on this mesh for interface problems. Given the continuity of the finite element space within quadrilateral elements, it suffices to estimate the consistency error on triangular elements $K\in \tilde{\mathcal{T}}_h^r$ satisfying the maximum angle condition.

As rotation and reflection transformations preserve integral values, we consider a representative triangle $K$ with vertices positioned at
\begin{align*}
	A_1(0,0), \quad A_2(h_1,0), \quad A_3(h_2,h_3).
\end{align*}
Denoting the interior angles at vertices $A_i$ by $\theta_i$, without loss of generality, we assume that $\theta_2 \leq \theta_1 \leq \theta_3$. The corresponding edges are parameterized as follows:
\begin{equation*}
	\begin{aligned}
		e_1 &= \left\{ (x,y) \mid y = y_1(x),\ h_2 \leq x \leq h_1 \right\} 
		= \left\{ (x,y) \mid x = x_1(y),\ 0 \leq y \leq h_3 \right\}, \\
		e_2 &= \left\{ (x,y) \mid y = y_2(x),\ 0 \leq x \leq h_2 \right\} 
		= \left\{ (x,y) \mid x = x_2(y),\ 0 \leq y \leq h_3 \right\}, \\
		e_3 &= \left\{ (x,y) \mid y = 0,\ 0 \leq x \leq h_1 \right\}.
	\end{aligned}
\end{equation*}
Based on the geometric properties of the mesh $\widetilde{\mathcal{T}}_h^r$, the following bounds hold:
\begin{equation}
	\begin{aligned}
		&1\lesssim \theta_1\leq \pi/2,\quad 0\leq \theta_2\leq \pi/2,\label{thetah}\\
		&h_2\leq h_3\leq h_1,\quad 0\leq h_2 \leq h_1/2.
	\end{aligned}
\end{equation}
The line integrals over the element edges can be transformed into coordinate integrals as follows (see Figure~\ref{triangleR} for the correspondence between edges and coordinate axes):
\begin{align*}
	&\text{For edge } e_1: && \int_{e_1} v \sin\theta_2 \, ds = \int_{0}^{h_3} v \, dy, \quad \int_{e_1} v \cos\theta_2 \, ds = \int_{h_2}^{h_1} v \, dx, \\
	&\text{For edge } e_2: && \int_{e_2} v \sin\theta_2 \, ds = \int_{0}^{h_3} v \, dy, \quad \int_{e_2} v \cos\theta_2 \, ds = \int_{0}^{h_2} v \, dx, \\
	&\text{For edge } e_3: && \int_{e_3} v \, ds = \int_{0}^{h_1} v \, dx.
\end{align*}


