\begin{lemma}\label{lemma:Eeta}
	For any $\boldsymbol{\eta}\in (H^1(\Omega_1\cup\Omega_2))^2$ and $v_h \in \mathring{V}_h$, it holds
	\begin{equation}\label{eq:Eeta-bound}
		E(T\boldsymbol{\eta},v_h) \lesssim h \|\boldsymbol{\eta}\|_{H^1(\Omega_1 \cup \Omega_2)} \|v_h\|_{V_h}.
	\end{equation}
\end{lemma}

\begin{proof}
	We decompose the consistency error element-wise:
	\begin{equation*}
		\begin{aligned}
			E(T\boldsymbol{\eta},v_h) 
			&= \sum_{e\in\mathcal{E}_h} \int_e \{T\bm{\eta}\cdot\boldsymbol{n}\}[v_h]  ds \\
			&= \sum_{e\in\mathcal{E}_h} \int_e \{ (T\bm{\eta} - \overline{T\bm{\eta}}) \cdot \boldsymbol{n} \} [v_h - \bar{v}_h]  ds \\
			&= \sum_{K\in\mathcal{T}_h^r} \sum_{e\subset\partial K} \int_e ( (T\bm{\eta} - \overline{T\bm{\eta}}) \cdot \boldsymbol{n} ) (v_h - \bar{v}_h)  ds \\
			&= \sum_{K\in\mathcal{T}_h^r} E_K(T\bm{\eta},v_h),
		\end{aligned}
	\end{equation*}
	where $E_K(T\bm{\eta},v_h) = \sum_{e\subset\partial K} \int_e (\delta T\bm{\eta} \cdot \boldsymbol{n}) \delta v_h  ds$. 
	The $H^1$-regularity of $T\bm{\eta}$ on each $K$ is ensured by the extension operator. 
	For notational brevity when unambiguous, we denote $T\bm{\eta}$ simply by $\bm{\eta}$.

	\begin{align*}
		E_K(\bm{\eta},v_h) 
		&= \left( -\int_0^{h_3} \delta \eta_x^{(1)} \delta v_h^{(1)}  dy + \int_0^{h_3} \delta \eta_x^{(3)} \delta v_h^{(3)}  dy \right) \\
		&\quad + \left( \int_0^{h_2} \delta \eta_y^{(1)} \delta v_h^{(1)}  dx + \int_{h_2}^{h_1} \delta \eta_y^{(3)} \delta v_h^{(3)}  dx 
		- \int_{0}^{h_1} \delta \eta_y^{(2)} \delta v_h^{(2)}  dx \right) \\
		&=: (I) + (II).
	\end{align*}
	Utilizing $\int_{e_i} \delta v_h^{(i)}  ds = \int_{e_i} \delta \eta_x^{(i)}  ds = \int_{e_i} \delta \eta_y^{(i)}  ds = 0$, we introduce intermediate terms.

	\textbf{Estimation of $(I)$:} Applying the Cauchy-Schwarz inequality, Lemma \ref{lemma:edge-estimates}, and geometric properties \eqref{thetah}:
	\begin{align*}
		(I) &= \int_0^{h_3} \left( \delta\eta_x^{(3)} - \delta\eta_x^{(1)} \right) \delta v_h^{(1)}  dy 
		+ \int_0^{h_3} \delta\eta_x^{(3)} \left( \delta v_h^{(3)} - \delta v_h^{(1)} \right)  dy \\
		&= \int_0^{h_3} \left( \int_{x_1(y)}^{x_3(y)} \partial_x \eta_x  dx \right) \delta v_h^{(1)}  dy
		+ \int_0^{h_3} \delta\eta_x^{(3)} \left( \int_{x_1(y)}^{x_3(y)} \partial_x v_h  dx \right)  dy \\
		&\leq |\sin\theta_1|^{1/2}h_1^{1/2}\|\partial_x\eta_x\|_{L^2(K)}\|\delta v_h^{(1)}\|_{L^2(e_1)} + |\sin\theta_2|^{1/2}h_1^{1/2}\|\delta \eta_x^{(3)}\|_{L^2(e_3)}\|\partial_x v_h\|_{L^2(K)} \\
		&\lesssim |e_1|^{1/2}|\eta_x|_{H^1(K)}|v_h|_{H^1(K)} + |e_3|^{1/2}|\eta_x|_{H^1(K)}|v_h|_{H^1(K)} \\
		&\lesssim h_1|\eta_x|_{H^1(K)}|v_h|_{H^1(K)}.
	\end{align*}

	\textbf{Estimation of $(II)$:} After introducing intermediate terms, we decompose:
	\begin{align*}
		(II) &= \int_0^{h_2} (\delta\eta_y^{(1)} - \delta\eta_y^{(2)}) \delta v_h^{(1)}  dx 
		+ \int_{h_2}^{h_1} (\delta \eta_y^{(3)} - \delta \eta_y^{(2)}) \delta v_h^{(3)}  dx \\
		&\quad + \int_{0}^{h_1} \delta \eta_y^{(2)} (v_h^{(1)} - v_h^{(2)})  dx 
		+ \int_{h_2}^{h_1} \delta \eta_y^{(2)} (v_h^{(3)} - v_h^{(2)})  dx \\
		&\quad + \int_{0}^{h_2} \delta \eta_y^{(2)} \bar{v}_h^{(1)}  dx 
		+ \int_{h_2}^{h_1} \delta \eta_y^{(2)} \bar{v}_h^{(3)}  dx \\
		&= (II)_a + (II)_b + (II)_c.
	\end{align*}
	Terms $(II)_a$ and $(II)_b$ are bounded similarly to $(I)$. For $(II)_c$, using geometric properties \eqref{thetah}:
	\begin{align*}
		(II)_c &= (\bar{v}_h^{(1)} - \bar{v}_h^{(3)}) \int_{0}^{h_2} \delta \eta_y^{(2)}  dx \\
		&= h_3^{-1} \left( \int_0^{h_3} v_h^{(1)}  dy - \int_0^{h_3} v_h^{(3)}  dy \right) \int_0^{h_2} \delta \eta_y^{(2)}  dx \\
		&= h_3^{-1} \left( \int_0^{h_3} \int_{x_3(y)}^{x_1(y)} \partial_x v_h  dx dy \right) \int_0^{h_2} \delta \eta_y^{(2)}  dx \\
		&\leq h_3^{-1}h_2^{1/2} |K|^{1/2}\|\partial_x v_h\|_{L^2(K)} \|\delta \eta_y^{(2)}\|_{L^1(e_2)} \\
		&\lesssim h_1 \|\eta_y\|_{H^1(K)} \|v_h\|_{H^1(K_e)}.
	\end{align*}
	Here $K_e$ is a shape-regular triangular element with edge $e$ and diameter $\mathcal{O}(|e|)$, which does not necessary belong to the mesh $\tilde{\mathcal{T}}_h^r$. Although adjacent $K_e$ elements may overlap, the overlap is bounded.

	Combining estimates for $(I)$, $(II)_a$, $(II)_b$, and $(II)_c$, then summing over $K \in \mathcal{T}_h^r$, we have
	\begin{align*}
		E(T\boldsymbol{\eta},v_h) &\lesssim h \left( \|T_1\boldsymbol{\eta}\|_{H^1(\Omega)} + \|T_2\boldsymbol{\eta}\|_{H^1(\Omega)} \right) \|v_h\|_{V_h} \\
		&\lesssim h \|\boldsymbol{\eta}\|_{H^1(\Omega_1\cup\Omega_2)} \|v_h\|_{V_h}.
	\end{align*}
	The proof completes.
\end{proof}
Combining Lemmas \ref{E1}, \ref{lemma:eta-Teta} and \ref{lemma:Eeta}, we establish the following fundamental estimate for the consistency error:

\begin{theorem}\label{thm:consistency}
	For any $u \in \tilde{H}^2(\Omega_1 \cup \Omega_2)$, the consistency error satisfies
	\begin{equation}
		E_h(u, v_h) \lesssim h \|u\|_{H^2(\Omega_1 \cup \Omega_2)} \|v_h\|_{V_h}.
	\end{equation}
\end{theorem}

\subsection{Error estimates for the interface problems}
With the consistency error bound established in Theorem \ref{thm:consistency} and the interpolation estimates from previous sections, we now derive the main convergence result for the interface problem:

\begin{theorem}\label{thm:main-error}
	Let $u \in \tilde{H}^2(\Omega_1 \cup \Omega_2)$ and $u_h$ be solutions of problems $(P)$ and $(P_h)$, respectively. The following optimal-order error estimate holds:
	\begin{align}
		\|u - u_h\|_{V_h} \lesssim h \|u\|_{H^2(\Omega_1 \cup \Omega_2)}.
	\end{align}
\end{theorem}

\begin{proof}
	Applying Strang's second lemma for nonconforming methods:
	\begin{align*}
		\|u - u_h\|_{V_h} &\lesssim \inf_{w_h \in V_h} \|u - w_h\|_{V_h} + \sup_{v_h \in V_h \backslash \{0\}} \frac{|E_h(u, v_h)|}{\|v_h\|_{V_h}} \\
		&\lesssim \|u - \pi_h u\|_{V_h} + \sup_{v_h \in V_h} \frac{|E_h(u, v_h)|}{\|v_h\|_{V_h}} \\
		&\lesssim h \|u\|_{H^2(\Omega_1 \cup \Omega_2)} \quad \text{(by Theorems \ref{pih} and \ref{thm:consistency})}.
	\end{align*}
\end{proof}
